// ===== 00_dil.js =====
// ---------- Dil (D-096, T-33): Türkçe ve İngilizce ----------
// Ekran metinleri kodda Türkçe yazılır ve ç() ile sarılır: ç("Kaydet"), ç("{n} arkadaş", { n: 3 }). Türkçede metin aynen
// döner (yer tutucular doldurulur); İngilizcede katalogdan gelir (apps/istemci/dil/en.json: "Türkçe" → "English"; derlemede
// DIL_EN olarak gömülür). Sayı türündeki değerler dilin biçimiyle yazılır. İngilizcede tekil ve çoğul ayrı yazılabilir
// ({ "one": "…", "other": "…" }; seçimi "n" değeri yapar). Katalogda olmayan metin Türkçesiyle kalır; eksiği
// tools/istemci/dil.test.ts yakalar (kaynakta ç() dışında kalmış metin de).
// Veriden gelen metinler (kural dosyalarındaki adlar, sunucunun hata iletileri) çv() ile aynı katalogdan çevrilir.
// Aynı Türkçe kelimenin iki ayrı çevirisi gerekirse anahtar bağlamla yazılır: ç("eylem::Sahne") (Türkçede "Sahne" görünür).
// Dil: bu cihazda seçilen (civora.dil; Ayarlar ya da giriş ekranı), yoksa tarayıcının dili (Türkçe değilse İngilizce).
// Dil değişince sayfa yeniden yüklenir: üst düzeydeki tablolar da baştan kurulur. Hesaptaki dil (profiles.locale) seçimle
// birlikte kaydedilir (sunucunun ileride yazacağı e-postalar için).
const DIL = (() => {
  const DILLER = ["tr", "en"];
  let secili = null;
  try { secili = localStorage.getItem("civora.dil"); } catch { /* depolama kapalı */ }
  const tarayici = String(navigator.languages?.[0] ?? navigator.language ?? "tr").toLowerCase();
  const kod = DILLER.includes(secili) ? secili : tarayici.startsWith("tr") ? "tr" : "en";
  const yerel = kod === "en" ? "en-US" : "tr-TR";
  try { document.documentElement.lang = kod; } catch { /* belge yok */ }
  return {
    kod,
    yerel,
    DILLER,
    katalog: kod === "en" && typeof DIL_EN === "object" ? DIL_EN : {},
    cogul: new Intl.PluralRules(yerel),
    secildi: DILLER.includes(secili),
    // Dili değiştirir (bu cihazda); farklıysa sayfa yeniden yüklenir.
    ayarla(yeni) {
      if (!DILLER.includes(yeni)) return;
      try { localStorage.setItem("civora.dil", yeni); } catch { /* depolama kapalı */ }
      if (yeni !== kod) location.reload();
    },
  };
})();

function ç(metin, d) {
  let s = metin.includes("::") ? metin.replace(/^[a-z_]+::/, "") : metin;
  if (DIL.kod !== "tr") {
    const k = DIL.katalog[metin];
    if (typeof k === "string") s = k;
    // Çoğul: sayı n'den; n yoksa biçimlenmiş kredi tutarından ({kr}: "1,234.5")
    else if (k && typeof k === "object") s = k[DIL.cogul.select(Number(d?.n ?? (typeof d?.kr === "string" ? d.kr.replace(/[^\d.-]/g, "") : 0)))] ?? k.other ?? metin;
  }
  if (!d) return s;
  return s.replace(/\{(\w+)\}/g, (m, a) => (a in d ? (typeof d[a] === "number" ? d[a].toLocaleString(DIL.yerel) : String(d[a] ?? "")) : m));
}
// Veriden gelen metin (kural adları, sunucu iletisi): katalogda varsa çevrilir, yoksa olduğu gibi kalır.
const çv = (metin, d) => (metin == null ? "" : ç(String(metin), d));
// Kural verisinin istemcideki kopyası (ör. görünüm seçenekleri): adlar veridir, Türkçe kalır; gösterilirken çv() ile çevrilir.
// Dil denetimi veri() içindeki adları çevrilmemiş metin saymaz, İngilizcelerinin katalogda olmasını ister.
const veri = (x) => x;
// Liste: "a, b ve c" / "a, b and c"
const listeYaz = (l) => new Intl.ListFormat(DIL.yerel, { type: "conjunction" }).format(l.map(String));

// Dünya adları: İngilizcede ülke ve bölgenin İngilizce adı (Natural Earth; derlemede "en" alanı).
if (DIL.kod === "en" && typeof DUNYA === "object") {
  for (const grup of [DUNYA.ulkeler, DUNYA.bolgeler]) for (const x of Object.values(grup ?? {})) if (x.en) x.ad = x.en;
}

// ===== 01_temel.js =====
// İstemcinin ortak yardımcıları (apps/arayuz/kaynak/01_temel.js'ten; örnek veriler ve eski tarif listesi çıkarıldı).
// Tarifler, savaş ve ekonomi değerleri sunucunun yürürlükteki kuralından gelir (api.rules).
// ---------- Yardımcılar ----------
const $ = (s, el = document) => el.querySelector(s);
const $$ = (s, el = document) => [...el.querySelectorAll(s)];
const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
const ikon = (ad, sinif = "") =>
  `<svg class="ik ${sinif}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${IKON[ad] ?? ""}</svg>`;
const sayi = (n) => Number(n).toLocaleString(DIL.yerel);
// Para alt birimle tutulur (1 kredi = 100), şartname §09.
const kr = (alt) => (alt / 100).toLocaleString(DIL.yerel, { minimumFractionDigits: alt % 100 ? 2 : 0, maximumFractionDigits: 2 });
const yuzde = (p) => ç("%{n}", { n: Math.round(p * 100) });
const sure = (sn) => {
  sn = Math.max(0, Math.round(sn));
  const s = Math.floor(sn / 3600), d = Math.floor((sn % 3600) / 60), n = sn % 60;
  if (s >= 48) return s % 24 ? ç("{g} gün {s} sa", { g: Math.floor(s / 24), s: s % 24 }) : ç("{g} gün", { g: Math.floor(s / 24) });
  if (s > 0) return ç("{s} sa {d} dk", { s, d });
  if (d > 0) return ç("{d} dk {n} sn", { d, n: String(n).padStart(2, "0") });
  return ç("{n} sn", { n });
};
const kisalt = (ad) => ad.split(/\s+/).map((p) => p[0]).join("").slice(0, 2).toLocaleUpperCase(DIL.yerel);

function rastgele(tohum) {
  let a = tohum >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const ozet = (s) => {
  let h = 2166136261;
  for (const c of String(s)) { h ^= c.codePointAt(0); h = Math.imul(h, 16777619); }
  return h >>> 0;
};
const yumusak = {
  cikis: (t) => 1 - Math.pow(1 - t, 3),
  girisCikis: (t) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2),
  geri: (t) => { const c1 = 1.5, c3 = c1 + 1; return 1 + c3 * Math.pow(t - 1, 3) + c1 * Math.pow(t - 1, 2); },
};
const hareketAzalt = matchMedia("(prefers-reduced-motion: reduce)").matches;
const telefon = () => matchMedia("(max-width: 860px)").matches;

// Çift gönderim koruması (22 Ekim 2026 incelemesi): aynı form art arda ikinci kez gönderilmez (çift tıklama, iki kez Enter).
// Yakalama aşamasında çalışır; ikinci "submit" 1,5 saniye içinde yutulur. Kilit, bir alan değişince (kullanıcı düzeltip yeniden
// gönderiyordur) ya da form formSerbest(f) deyince hemen kalkar; pencereForm düğmeyi ayrıca kapatır.
const FORM_KILIT_MS = 1500;
document.addEventListener("submit", (e) => {
  const f = e.target;
  if (!(f instanceof HTMLFormElement)) return;
  const t = Date.now();
  if (f._mesgul && t - f._mesgul < FORM_KILIT_MS) { e.preventDefault(); e.stopImmediatePropagation(); return; }
  f._mesgul = t;
  f.addEventListener("input", () => { f._mesgul = 0; }, { once: true });
}, true);
const formSerbest = (f) => { if (f) f._mesgul = 0; };

function tost(metin, ik = "sparkles") {
  const kutu = $("#tostlar");
  // Aynı anda en çok iki bildirim: eskisi hemen çekilir (ekranın altını kapatmasın).
  const eski = [...kutu.children].filter((x) => !x.classList.contains("cikis"));
  for (const x of eski.slice(0, Math.max(0, eski.length - 1))) { x.classList.add("cikis"); setTimeout(() => x.remove(), 320); }
  const el = document.createElement("div");
  el.className = "tost";
  el.innerHTML = `${ikon(ik)}<span>${esc(metin)}</span>`;
  kutu.appendChild(el);
  setTimeout(() => { el.classList.add("cikis"); setTimeout(() => el.remove(), 320); }, 3600);
}

// Onay penceresi: işlemden önce bedel ve sonucu gösterir (şartname: işlem öncesi fiyat özeti).
// Pencerelerde klavye (22 Ekim 2026 incelemesi, TECH-03): Tab pencerenin içinde döner, arka plan odak almaz; kapanınca odak
// pencereyi açan öğeye döner. Dönen işlev kapanışta çağrılır.
function pencereOdak(perde) {
  const acan = document.activeElement instanceof HTMLElement ? document.activeElement : null;
  const odaklanir = () => [...perde.querySelectorAll("a[href], button, input, select, textarea, [tabindex]")].filter((el) => !el.disabled && el.tabIndex >= 0 && el.offsetParent !== null);
  const tab = (e) => {
    if (e.key !== "Tab") return;
    const l = odaklanir();
    if (!l.length) { e.preventDefault(); return; }
    const ilk = l[0], son = l[l.length - 1];
    if (e.shiftKey && (document.activeElement === ilk || !perde.contains(document.activeElement))) { e.preventDefault(); son.focus(); }
    else if (!e.shiftKey && (document.activeElement === son || !perde.contains(document.activeElement))) { e.preventDefault(); ilk.focus(); }
  };
  perde.addEventListener("keydown", tab);
  return () => { if (acan?.isConnected) { try { acan.focus({ preventScroll: true }); } catch { /* yok */ } } };
}

// Üst üste açılan pencerelerin başlık kimliği ayrı (aria-labelledby ilk eşleşeni okur; yoksa üstteki pencere alttakinin adıyla
// okunurdu)
let pencereSayaci = 0;
const pencereBaslikKimligi = () => "pencere-baslik-" + (++pencereSayaci);

function pencere({ ust, baslik, govde, dugmeler }) {
  const perde = document.createElement("div");
  perde.className = "perde";
  const bk = pencereBaslikKimligi();
  perde.innerHTML = `<div class="pencere" role="dialog" aria-modal="true" aria-labelledby="${bk}">
      ${ust ? `<p class="ust-yazi">${esc(ust)}</p>` : ""}
      <h2 class="b2" id="${bk}">${esc(baslik)}</h2>
      <div>${govde}</div>
      <div class="pencere-dugmeler"></div>
    </div>`;
  const kutu = $(".pencere-dugmeler", perde);
  const odakDon = pencereOdak(perde);
  const kapat = () => { perde.remove(); document.removeEventListener("keydown", tus); odakDon(); };
  const tus = (e) => { if (e.key === "Escape") kapat(); };
  for (const d of dugmeler ?? [{ ad: ç("Kapat") }]) {
    const b = document.createElement("button");
    b.className = "dugme " + (d.sinif ?? "ikincil");
    b.innerHTML = (d.ikon ? ikon(d.ikon) : "") + esc(d.ad);
    b.onclick = () => { kapat(); d.is?.(); };
    kutu.appendChild(b);
  }
  perde.addEventListener("click", (e) => { if (e.target === perde) kapat(); });
  document.addEventListener("keydown", tus);
  document.body.appendChild(perde);
  $(".pencere-dugmeler button:last-child", perde)?.focus();
}

// Formlu pencere: onaylanınca "is" çalışır; hata verirse pencere açık kalır ve iletisi altta görünür, başarıda kapanır.
// "is" Error fırlatırsa iletisi gösterilir (sunucu hatası sunucunun Türkçe iletisiyle).
function pencereForm({ ust, baslik, govde, onayAd, onaySinif = "altin", onayIkon, is }) {
  const perde = document.createElement("div");
  perde.className = "perde";
  const bk = pencereBaslikKimligi();
  perde.innerHTML = `<form class="pencere" role="dialog" aria-modal="true" aria-labelledby="${bk}" novalidate>
      ${ust ? `<p class="ust-yazi">${esc(ust)}</p>` : ""}
      <h2 class="b2" id="${bk}">${esc(baslik)}</h2>
      <div class="form pencere-govde">${govde}</div>
      <div class="form-mesaj"></div>
      <div class="pencere-dugmeler"><button type="button" class="dugme ikincil" data-vazgec>${ç("Vazgeç")}</button>
        <button type="submit" class="dugme ${onaySinif}">${onayIkon ? ikon(onayIkon) : ""}${esc(onayAd)}</button></div>
    </form>`;
  const f = $("form", perde);
  const odakDon = pencereOdak(perde);
  const kapat = () => { perde.remove(); document.removeEventListener("keydown", tus); odakDon(); };
  const tus = (e) => { if (e.key === "Escape") kapat(); };
  $("[data-vazgec]", f).onclick = kapat;
  perde.addEventListener("click", (e) => { if (e.target === perde) kapat(); });
  f.addEventListener("submit", async (e) => {
    e.preventDefault();
    const d = $("button[type=submit]", f);
    d.disabled = true;
    $(".form-mesaj", f).innerHTML = "";
    try {
      await is(new FormData(f), f);
      kapat();
    } catch (err) {
      const metin = err instanceof SunucuHatasi ? hataMetni(err) : err?.message || hataMetni(err);
      $(".form-mesaj", f).innerHTML = `<div class="hata-kutusu" style="margin-top:12px">${ikon("circle-alert")}<span>${esc(metin)}</span></div>`;
      d.disabled = false;
    } finally { formSerbest(f); }
  });
  document.addEventListener("keydown", tus);
  document.body.appendChild(perde);
  ($("input:not([type=hidden]), select, textarea", f) ?? $("button[type=submit]", f)).focus();
  return { perde, form: f, kapat };
}

// Kullanıcının yazdığı yüzde ("6", "6,5", "%6") → ppm (1,00 = 1.000.000). Geçersizse NaN.
const yuzdePpm = (metin) => {
  const s = String(metin ?? "").replace(/[%\s]/g, "").replace(",", ".");
  return /^\d+(\.\d{1,4})?$/.test(s) ? Math.round(Number(s) * 10000) : NaN;
};
// Kullanıcının yazdığı adet ("12"; boşluk ve binlik ayraç olmadan tam sayı) → sayı; başka her şey (1,5 / -5 / 1e3 / harf) NaN.
// Rakam dışını silmek "1,5"i 15'e, "-5"i 5'e çeviriyordu (22 Ekim 2026 incelemesi): geçersiz girdi sessizce değişmez, reddedilir.
const adetAl = (metin) => { const s = String(metin ?? "").trim(); return /^\d{1,9}$/.test(s) ? Number(s) : NaN; };
// Para alanının başlangıç değeri: alt birim → seçili dilde, binlik ayraçsız metin ("12,34" / "12.34"); krediAlt aynı sayıyı geri
// okur. (JavaScript'in "12.34" metni Türkçede binlik ayraç sanılıp 1234 krediye dönüşüyordu; 22 Ekim 2026 incelemesi.)
const krediGirdi = (alt) => (Number(alt ?? 0) / 100).toLocaleString(DIL.yerel, { useGrouping: false, maximumFractionDigits: 2 });
// Kullanıcının yazdığı kredi (Türkçede "1.250", "1250,50"; İngilizcede "1,250", "1250.50") → alt birim (1 kredi = 100).
// Geçersizse NaN.
const krediAlt = (metin) => {
  let s = String(metin ?? "").replace(/\s/g, "");
  s = DIL.kod === "en" ? s.replace(/,/g, "") : s.replace(/\./g, "").replace(",", ".");
  return /^\d+(\.\d{1,2})?$/.test(s) ? Math.round(Number(s) * 100) : NaN;
};

// ---------- Karakter resmi (kodla, parçalardan; şartname: avatar lisanslı parçalardan kurulur) ----------
const TEN = ["#F3D2B3", "#E8BC94", "#D7A07A", "#B97B55", "#8E5A3B", "#6A4029"];
const SAC = ["#2B211C", "#4A3326", "#7A4E2D", "#B07A43", "#D9B26A", "#8A8580"];
const GIYSI = ["#174A40", "#C65A3B", "#23395B", "#D9A548", "#367F70", "#7D5FA0", "#8B6B4A"];
const ZEMIN = ["#F6E3BE", "#DCEBE3", "#F6E1D8", "#DFE5EF", "#ECE4F3", "#EDE7D6"];
// Profil resmi: kayıtlı görünüm (D-095; 04_gorunus.js) ya da addan türetilen. ek: { ulke (üniformadaki bant), rutbe (sıra) }.
// Çizim sırası: zemin (mağaza zemini: geçiş ve desen), arkadaki saç (at kuyruğu), gövde ve kıyafet (beden eniyle; mağaza kumaş
// rengi ve deseni), boyun, baş, yanaklar, sakal, kaşlar, saç, kep ya da mağaza şapkası, gözler ve ağız, gözlük, çerçeve (D-134).
// Kaşlar saçın ve kep siperinin altında kalabilir; gözler ve ağız her zaman görünür. Üniformada şapka, desen ve kumaş rengi yok.
const AVATAR_BEDEN = { ince: { o: 0.86, boyun: 8.4, rx: 10.8 }, orta: { o: 1, boyun: 9.2, rx: 11.2 }, iri: { o: 1.16, boyun: 10.6, rx: 11.7 } };
// Mağaza ürünlerinin SVG tanımları (gradient, desen, süzgeç) resim başına tekil kimlik alır (D-134; çizim 04a_magaza_cizim.js'te)
let magazaSvgSayac = 0;
// Kıvırcık saçın bukleleri (x, y, yarıçap): başın üstünde yay boyunca; ilk iki ve son iki bukle yanlarda (kep altında da kalır).
const AVATAR_KIVIR = [[20.7, 26, 3], [21.9, 22.3, 3.4], [24.7, 18.9, 3.7], [28.5, 16.8, 3.9], [32, 16.2, 3.9], [35.5, 16.8, 3.9],
  [39.3, 18.9, 3.7], [42.1, 22.3, 3.4], [43.3, 26, 3]];
function avatarSvg(ad, gorunus = null, ek = {}) {
  const g = gorunus ?? varsayilanGorunus(ad);
  const K = gorunusKurali();
  const sec = (dizi, yedek, i) => (dizi ?? yedek)[i] ?? yedek[0];
  const U = typeof gorunusUrunleri === "function" ? gorunusUrunleri(g) : {};
  const uid = "mg" + (magazaSvgSayac++).toString(36);
  let defs = "";
  const ten = sec(K.skin, TEN, g.ten), sac = sec(K.hairColor, SAC, g.sacRenk);
  let zemin = sec(K.backgrounds, ZEMIN, g.zemin), zeminDesen = "";
  if (U.zemin) {
    const zd = magazaDolgu(U.zemin.data.fill ?? zemin, uid + "-z", 135);
    defs += zd.defs;
    zemin = zd.fill;
    zeminDesen = U.zemin.data.pattern ? magazaZeminDeseni(U.zemin.data.pattern, U.zemin.data.patternColor) : "";
  }
  const uniforma = g.kiyafet === "uniforma";
  const giysi = uniforma ? UNIFORMA.kumas : U.renk?.data.color ?? sec(K.outfitColors, GIYSI, g.renk);
  const gomlek = "#F1EADB";
  const ust = g.kiyafet === "tulum" || g.kiyafet === "yelek" ? gomlek : giysi;
  // Kumaş: desen (yalnız üstü kıyafetin renginde olan kıyafetlerde), metal parıltısı ve neon ışıltısı
  const govdeYol = "M9 66c1.6-12.4 10.6-19 23-19s21.4 6.6 23 19z";
  let kumasUst = "", kumasAlt = "";
  if (!uniforma && U.desen && ust === giysi) {
    defs += magazaKumasDeseni(U.desen.data.pattern, uid + "-d", U.desen.data.color);
    kumasUst += `<path d="${govdeYol}" fill="url(#${uid}-d)"/>`;
  }
  if (!uniforma && U.renk?.data.metal && ust === giysi) {
    defs += `<linearGradient id="${uid}-m" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#FFFFFF" stop-opacity=".5"/><stop offset=".45" stop-color="#FFFFFF" stop-opacity="0"/><stop offset="1" stop-color="#000000" stop-opacity=".18"/></linearGradient>`;
    kumasUst += `<path d="${govdeYol}" fill="url(#${uid}-m)"/>`;
  }
  if (!uniforma && U.renk?.data.glow && ust === giysi) {
    defs += `<filter id="${uid}-gl" x="-20%" y="-20%" width="140%" height="140%"><feGaussianBlur stdDeviation="2.2"/></filter>`;
    kumasAlt = `<path d="${govdeYol}" fill="${giysi}" opacity=".75" filter="url(#${uid}-gl)"/>`;
  }
  const sapkaUrun = !uniforma && U.sapka ? U.sapka : null;
  const ortulu = uniforma || (!!sapkaUrun && !["bandana", "tac"].includes(sapkaUrun.data.shape));
  const cerceve = U.cerceve ? magazaCerceveSvg(U.cerceve, uid) : null;
  if (cerceve) defs += cerceve.defs;
  const bant = DUNYA.ulkeler?.[ek.ulke]?.renk ?? "#C65A3B";
  const B = AVATAR_BEDEN[g.beden] ?? AVATAR_BEDEN.orta;
  // Yatayda ortadan (x = 32) genişletme: gövde beden eniyle, baş ve saç başın eniyle.
  const enle = (f) => (f === 1 ? "" : ` transform="matrix(${f} 0 0 1 ${(32 - 32 * f).toFixed(2)} 0)"`);
  const kivir = (liste) => liste.map(([x, y, r]) => `<circle cx="${x}" cy="${y}" r="${r}"/>`).join("");
  const saclar = {
    kisa: `<path d="M20.5 27.5c-.6-8.4 4.6-13.6 11.5-13.6s12.3 5 11.6 13.4c-1.6-4.6-5.4-7.4-11.6-7.4s-9.9 3-11.5 7.6z" fill="${sac}"/>`,
    uzun: `<path d="M19.6 41c-2.2-6-1.8-12.6.4-17.3 2.3-5.3 6.6-9 12-9 6 0 10.4 4 12.3 9.4 1.7 4.9 1.8 11-.7 16.9-1.3-5-1-9.4-1.6-13-.9-4.3-4.4-7-10-7s-9 2.9-10 7.2c-.8 3.7-.9 8-2.4 12.8z" fill="${sac}"/>`,
    topuz: `${ortulu ? "" : `<circle cx="32" cy="12.5" r="4.6" fill="${sac}"/>`}<path d="M20.8 27c-.4-7.9 4.5-12.6 11.2-12.6S43.5 19 43.2 27c-1.9-4.1-5.4-6.3-11.2-6.3S22.7 22.9 20.8 27z" fill="${sac}"/>`,
    yan: `<path d="M20.4 28c-1.3-8.6 4-14.8 11.6-14.8 6.3 0 10.6 3.5 11.8 8.6-3.5-1.9-7-1.6-10.4-3.2-2.6 3.6-7.4 5.1-13 9.4z" fill="${sac}"/>`,
    kirpik: `<path d="M21.2 25.6c1-6.2 5.2-9.8 10.8-9.8s9.8 3.6 10.8 9.8c-3-1.8-6.6-2.7-10.8-2.7s-7.8.9-10.8 2.7z" fill="${sac}"/>`,
    kivircik: `<path d="M20.4 28.6c-.9-8.6 4.6-14.4 11.6-14.4s12.5 5.8 11.6 14.4c-2.2-4.2-6.4-6.6-11.6-6.6s-9.4 2.4-11.6 6.6z" fill="${sac}"/>
      <g fill="${sac}" stroke="rgba(0,0,0,.16)" stroke-width=".6">${kivir(ortulu ? [...AVATAR_KIVIR.slice(0, 2), ...AVATAR_KIVIR.slice(7)] : AVATAR_KIVIR)}</g>`,
    atkuyrugu: `<path d="M20.6 27.8c-.5-8.2 4.6-13.6 11.4-13.6s12 5.4 11.4 13.6c-1.8-4.6-5.6-7.6-11.4-7.6s-9.6 3-11.4 7.6z" fill="${sac}"/>
      <path d="M23.4 21.6q8.6-5.4 17.2 0" fill="none" stroke="rgba(255,255,255,.18)" stroke-width="1"/>`,
    kel: `<path d="M20.9 31.5q-.8-4.6 1.4-7.4M43.1 31.5q.8-4.6-1.4-7.4" fill="none" stroke="${sac}" stroke-width="2.2" stroke-linecap="round"/>`,
  };
  // At kuyruğu başın arkasından yana sarkar (başın altında çizilir); tokası kırmızı.
  const arkaSac = g.sac === "atkuyrugu" ? `<g${enle(B.rx / 11.2)}><path d="M40.4 18.8c5.6.2 8.6 4.6 8.2 10.6-.3 4.8-2.4 8.8-5.6 11.4 1.1-3.8 1.4-7.8.4-11.2-.8-2.8-2.2-4.8-4.4-6.4z" fill="${sac}"/>
    <circle cx="42" cy="20.2" r="1.5" fill="#C65A3B"/></g>` : "";
  const altin = UNIFORMA.sirma;
  // Omuz apoleti: rütbe işareti şerit (çizgi), yıldız (nokta) ve defne (yay) olarak
  const apolet = (x, aci) => {
    const b = rutbeBicimi(ek.rutbe ?? 0);
    const n = b.serit || b.yildiz;
    const isaret = Array.from({ length: n }, (_, k) => b.serit
      ? `<path d="M${(x + 3.4 + k * 1.6).toFixed(1)} 50.9v2.8" stroke="${altin}" stroke-width=".8"/>`
      : `<circle cx="${(x + 3.6 + k * 1.7).toFixed(1)}" cy="52.3" r=".6" fill="${altin}"/>`).join("")
      + (b.defne ? `<path d="M${x + 2.4} 53.6q3.2 1.6 6.4 0" fill="none" stroke="${altin}" stroke-width=".55"/>` : "");
    return `<g transform="rotate(${aci} ${x + 5.25} 52.3)"><rect x="${x}" y="50.4" width="10.5" height="3.8" rx="1.9" fill="${UNIFORMA.koyu}"/>${isaret}</g>`;
  };
  const kiyafet = {
    gunluk: `<path d="M26.6 46.6 32 52l5.4-5.4" fill="none" stroke="rgba(255,255,255,.55)" stroke-width="1.6"/>`,
    takim: `<path d="M27.2 47.2 32 58.5l4.8-11.3z" fill="#F4EFE3"/><path d="M31.1 50.2h1.8l.9 7.4-1.8 1.9-1.8-1.9z" fill="#A9472C"/>
      <path d="M26.4 47.6 30.3 60M37.6 47.6 33.7 60" stroke="rgba(0,0,0,.22)" stroke-width="1.3" fill="none"/>`,
    tulum: `<path d="M21.5 66V56.5q0-1.5 1.5-1.5h18q1.5 0 1.5 1.5V66z" fill="${giysi}"/>
      <path d="M24.5 55.5 22.6 48.6M39.5 55.5l1.9-6.9" stroke="${giysi}" stroke-width="2.6" stroke-linecap="round"/>
      <circle cx="25" cy="57.8" r=".9" fill="#E9D7A0"/><circle cx="39" cy="57.8" r=".9" fill="#E9D7A0"/>`,
    kazak: `<path d="M26.2 47.6q5.8 4.6 11.6 0" fill="none" stroke="rgba(0,0,0,.2)" stroke-width="2.6" stroke-linecap="round"/>`,
    spor: `<path d="M32 51v15" stroke="rgba(255,255,255,.8)" stroke-width="1.1"/>
      <path d="M12.5 61q3.2-8 10.5-11.5M51.5 61q-3.2-8-10.5-11.5" fill="none" stroke="#FFFFFF" stroke-width="1.5" stroke-linecap="round"/>
      <path d="M27 47.4q5 3.2 10 0" fill="none" stroke="rgba(255,255,255,.75)" stroke-width="1.6"/>`,
    yelek: `<path d="M9 66c1.6-12.4 10.6-19 19.5-19L30 66z" fill="${giysi}"/><path d="M55 66c-1.6-12.4-10.6-19-19.5-19L34 66z" fill="${giysi}"/>
      <g fill="#E2B54A"><circle cx="27.6" cy="55" r=".9"/><circle cx="28.2" cy="59.5" r=".9"/><circle cx="36.4" cy="55" r=".9"/><circle cx="35.8" cy="59.5" r=".9"/></g>`,
    uniforma: `<path d="M27 47.2 32 52l5-4.8" fill="none" stroke="${UNIFORMA.koyu}" stroke-width="2.4"/>
      <g fill="${altin}"><circle cx="32" cy="56" r=".85"/><circle cx="32" cy="60.5" r=".85"/></g>
      ${apolet(12.6, -24)}${apolet(40.9, 24)}<rect x="11.6" y="57.2" width="4" height="2.6" rx=".5" fill="${bant}"/>`,
  };
  const kep = uniforma ? `<path d="M20.4 22.2q11.6-9.2 23.2 0l.5 2.4H19.9z" fill="${UNIFORMA.kumas}"/><rect x="20" y="22.3" width="24" height="2.3" fill="${bant}"/>
    <path d="M19.2 24.5h25.6q-2.6 3.1-12.8 3.1t-12.8-3.1z" fill="${UNIFORMA.koyu}"/><circle cx="32" cy="19.2" r="1.3" fill="${altin}"/>` : "";
  const sakal = g.sakal === "sakal"
    ? `<path d="M21.6 31c1 6.8 5 10.4 10.4 10.4S41.4 37.8 42.4 31c-2.2 2.6-5.6 3.6-10.4 3.6S23.8 33.6 21.6 31z" fill="${sac}"/>`
    : g.sakal === "biyik" ? `<path d="M27.2 33.3q4.8-2.6 9.6 0-4.8 1.5-9.6 0z" fill="${sac}"/>` : "";
  // Yüz: kaşlar (saçın altında), gözler ve ağız (en üstte), yanak allığı
  const goz = "#2A2420", agizR = "#7A3E2E";
  const cizgi = (d, renk, kalin) => `<path d="${d}" fill="none" stroke="${renk}" stroke-width="${kalin}" stroke-linecap="round"/>`;
  const yuzler = {
    sakin: { goz: `<circle cx="27.6" cy="29.2" r="1.35" fill="${goz}"/><circle cx="36.4" cy="29.2" r="1.35" fill="${goz}"/>`,
      agiz: cizgi("M28.6 34.4q3.4 2.6 6.8 0", agizR, 1.4) },
    gulec: { allik: true, kas: cizgi("M25.8 25.2q1.9-1.2 3.8 0M34.4 25.2q1.9-1.2 3.8 0", sac, 1),
      goz: cizgi("M26 29.9q1.6-2.1 3.2 0M34.8 29.9q1.6-2.1 3.2 0", goz, 1.25), agiz: cizgi("M27.6 33.8q4.4 4.2 8.8 0", agizR, 1.6) },
    ciddi: { kas: cizgi("M25.6 26.4h3.9M34.5 26.4h3.9", sac, 1.2),
      goz: `<ellipse cx="27.6" cy="29.4" rx="1.3" ry="1.05" fill="${goz}"/><ellipse cx="36.4" cy="29.4" rx="1.3" ry="1.05" fill="${goz}"/>`,
      agiz: cizgi("M29.3 35h5.4", agizR, 1.4) },
    neseli: { allik: true, kas: cizgi("M25.7 24.8q1.9-1.3 3.8 0M34.5 24.8q1.9-1.3 3.8 0", sac, 1),
      goz: `<circle cx="27.6" cy="29" r="1.75" fill="${goz}"/><circle cx="36.4" cy="29" r="1.75" fill="${goz}"/>
        <circle cx="28.2" cy="28.4" r=".55" fill="#FFFFFF"/><circle cx="37" cy="28.4" r=".55" fill="#FFFFFF"/>`,
      agiz: `<path d="M28.2 33.6q3.8 5 7.6 0z" fill="${agizR}"/><path d="M30.4 35.6q1.6 1 3.2 0q-1.6-.8-3.2 0z" fill="#D9776A"/>` },
    dalgin: { kas: cizgi("M25.8 25.1q1.9-1.1 3.8 0M34.4 25.1q1.9-1.1 3.8 0", sac, 1),
      goz: `<ellipse cx="28.1" cy="29.7" rx="1.35" ry=".8" fill="${goz}"/><ellipse cx="36.9" cy="29.7" rx="1.35" ry=".8" fill="${goz}"/>`
        + cizgi("M26.4 29q1.7-.5 3.4 0M35.2 29q1.7-.5 3.4 0", goz, .8),
      agiz: cizgi("M30.6 35q1.8.8 3.8-.2", agizR, 1.3) },
    kararli: { kas: cizgi("M25.4 25.6l4 1.3M38.6 25.6l-4 1.3", sac, 1.35),
      goz: `<circle cx="27.6" cy="29.4" r="1.3" fill="${goz}"/><circle cx="36.4" cy="29.4" r="1.3" fill="${goz}"/>`,
      agiz: cizgi("M29 34.7q3 1.3 6 0", agizR, 1.5) },
  };
  const Y = yuzler[g.yuz] ?? yuzler.sakin;
  const allik = Y.allik ? `<circle cx="24.6" cy="32.8" r="2.1" fill="#F29C8F" opacity=".45"/><circle cx="39.4" cy="32.8" r="2.1" fill="#F29C8F" opacity=".45"/>` : "";
  return `<svg viewBox="0 0 64 64" role="img" aria-label="${esc(ad)}">${defs ? `<defs>${defs}</defs>` : ""}
    <rect width="64" height="64" fill="${zemin}"/>${zeminDesen}
    ${arkaSac}
    <g${enle(B.o)}>${kumasAlt}<path d="${govdeYol}" fill="${ust}"/>${kumasUst}
    ${kiyafet[g.kiyafet] ?? kiyafet.gunluk}</g>
    <rect x="${(32 - B.boyun / 2).toFixed(1)}" y="36" width="${B.boyun}" height="11.5" rx="4" fill="${ten}" style="filter:brightness(.93)"/>
    <ellipse cx="32" cy="28.5" rx="${B.rx}" ry="12.6" fill="${ten}"/>
    ${allik}
    <g${enle(B.rx / 11.2)}>${sakal}</g>
    ${Y.kas ?? ""}
    <g${enle(B.rx / 11.2)}>${saclar[g.sac] ?? saclar.kisa}${kep}${sapkaUrun ? magazaSapkaSvg(sapkaUrun) : ""}</g>
    ${Y.goz}${Y.agiz}${U.gozluk ? `<g${enle(B.rx / 11.2)}>${magazaGozlukSvg(U.gozluk)}</g>` : ""}
    ${cerceve ? cerceve.svg : ""}
  </svg>`;
}

