  "feedback.answered": () => [ç("Geri bildirimine yanıt geldi (Ayarlar → Geri bildirim)."), "badge-check"],
  "house.sold": () => [ç("Evin satıldı."), "house"],
  "square.replied": () => [ç("Meydan'daki paylaşımına yanıt geldi."), "message-circle"],
  "citizenship.changed": (d) => [d.reason === "state_dissolved" ? ç("Devlet dağıldı; önceki vatandaşlığına döndün.") : ç("Vatandaşlığın değişti."), "id-card"],
  // Onaylı üyelik (D-137): başkanın kararı isteği gönderene
  "party.join_decided": (d) => [d.approved ? ç("{parti} üyelik isteğini kabul etti; artık üyesin.", { parti: d.party ?? "" })
    : ç("{parti} üyelik isteğini reddetti.", { parti: d.party ?? "" }), d.approved ? "users-round" : "circle-alert"],
  // İşbirliği (D-107): teslim ve şantiye işi kendi işlemindir (ekranda görünür); elçilik kanalına gelen mesaj bildirilir
