  "account.deletion_requested": () => [ç("Hesap silme talebin alındı; bekleme süresinde vazgeçebilirsin."), "circle-alert"],
  // Kaçakçılık (D-097): sonuç varışta sunucunun zarıyla belli olur. Kefaletle çıkış kendi işlemin olduğundan bildirilmez.
  "shadow.run_resolved": (d) => d.status === "sold" ? [ç("Kaçak yük satıldı: {kr} kredi kazandın.", { kr: kr(d.payout_cr) }), "coins"]
    : d.status === "caught" ? [ç("Gümrükte yakalandın: yük ve {kr} kredi ceza el kondu, gözaltındasın.", { kr: kr(d.fine_cr) }), "lock"] : null,
  // Kara borsa (D-105): satıcıya; alıcının kendi alımı ekranda görünür
