    for (const [x, y, gx, gy] of [[(px0 + px1) / 2, py0 - 0.05, pg + 0.2, 0.1], [(px0 + px1) / 2, py1, pg + 0.2, 0.08], [px0 - 0.04, py0, 0.08, py1 - py0], [px1 + 0.04, py0, 0.08, py1 - py0], [(px0 + px1) / 2, py0, 0.05, py1 - py0]]) {
      kabuk.add(kutu(gx, gy, 0.2, krem, x, y, -0.04));
    }
    kabuk.add(kutu(pg + 0.3, 0.06, 0.32, krem, (px0 + px1) / 2, py0 - 0.06, 0.08)); // denizlik
    // Dışarısı: pencere boşluğunun hemen arkasında
