  const PARTI_RENK3B = { sohbet: ["#E2B54A", "#C0663E", "#F1E6D2"], muzik: ["#9B6BFF", "#3FD0FF", "#FF4FA3", "#FFD24F"],
    kutlama: ["#E5577A", "#F2C94C", "#5FB0D2", "#6F9B6A"], sofra: ["#C9A227", "#9C3F33", "#F1E6D2"] };
