  // ---------- Yaşayan oda (D-110 #5): figür, yorgan, "z" ve kiler rafı ----------
  const fp = figurParcasi(THREE);
  const figur = fp.grup;
  figur.scale.setScalar(ODA_FIGUR_OLCEK);
  figur.visible = false;
  // Kök döner (yüzünün yönü), figür kökün içinde yatırılır
