  yerYatagi.visible = false;
  sahne.add(yorgan, yerYatagi);
  const zDoku = dokuCiz(64, 64, (g, W, H) => {
    g.fillStyle = "#FFFFFF"; g.font = "bold 50px sans-serif"; g.textAlign = "center"; g.textBaseline = "middle";
    g.fillText("z", W / 2, H / 2 + 3);
  });
  const zler = [0, 1, 2].map(() => {
    const z = new THREE.Sprite(new THREE.SpriteMaterial({ map: zDoku, color: "#C9D8FF", transparent: true, depthWrite: false }));
    z.visible = false;
    sahne.add(z);
    return z;
  });
  // Kiler rafı: sol duvarda, en öndeki karenin üstünde yüksekte (dolabın ve kitaplığın üstünden geçer); paketler çantadaki erzak
  const kiler = new THREE.Group();
  sahne.add(kiler);
