      parti: d.parti?.tema ?? "", partiMasa: d.parti && partiMasa ? (partiMasa.masa ? partiMasa.id : "pencere") : "",
      partiTepsi: d.parti && d.parti.tepsi > 0 ? String(partiTepsiGorunen) : "", partiTabak: String(d.parti ? ikramlar.length : 0),
