    const sg = (performance.now() - selamBasi) / 1000;
    const selamE = selamBasi && sg > 0 && sg < 1.8 ? Math.min(1, sg * 4, (1.8 - sg) * 4) : 0;
    const ayakta = !b && !yeme && (durak?.tur ?? "ayakta") === "ayakta";
    figurKok.position.set(konum.x, konum.y, konum.z);
    figurKok.rotation.y = ayakta && selamE ? aci(konum.yon, Math.atan2(kamera.position.x - konum.x, kamera.position.z - konum.z), selamE) : konum.yon;
    figur.rotation.x = -Math.PI / 2 * konum.yat;
