  const EV_SURE = { wave: 2400, cheer: 3200, laugh: 2600 };   // ms; dans ve oturma yürüyene dek sürer
  const kaliciE = (e) => e === "dance" || e === "sit";
  const ziyaretAcik = () => !!d.ziyaret && !d.duzen;
