  const benHalka = new THREE.Mesh(new THREE.RingGeometry(0.26, 0.34, 32).rotateX(-Math.PI / 2),
    new THREE.MeshBasicMaterial({ color: "#E2B54A", transparent: true, opacity: 0.9, depthWrite: false }));
