    if (yol) for (let i = 1; i < yol.length; i++) o.plan.push({ tur: "yuru", bas: yol[i - 1], son: yol[i] });
    else if (!durak) o.plan.push({ tur: "kay", bas: null, son: varis, sure: 0.3, eylem: "bekle" });
    if (durak) o.plan.push({ tur: "kay", bas: null, son: varis, sure: 0.5, eylem: durak.eylem ?? "otur" });
