    s.savasGrup = g;
    if (s.savasDuman || s.savasIsci) savasGuncelle(performance.now() / 1000);
    // Sahnedeki savaş izlerinin sayıları (erişilebilirlik ve sınama için kapta; ekrana dönünce yeni kaba yeniden yazılır)
    s.savasSayilar = { hasar: String(cokuk.length + hasarli.length), cokuk: String(cokuk.length),
      savasDuman: String(s.savasDuman ? s.savasDuman.kaynak.length : 0), bayrak: String(bayrak), direnisAfis: String(afis), iskele: String(iskele) };
    if (kap) Object.assign(kap.dataset, s.savasSayilar);
