const FIGUR_BAS_Y = 1.84;
// Mağaza kumaş deseni (D-134): kıyafet renginin üstüne desen çizilmiş küçük tuval dokusu (tekrarlı). Renk ve desen başına bir kez.
const figurDesenOnbellek = new Map();
function figurDesenDokusu(THREE, renk, desen) {
  const k = renk + "|" + desen.pattern + "|" + (desen.color ?? "");
  if (figurDesenOnbellek.has(k)) return figurDesenOnbellek.get(k);
  const c = document.createElement("canvas");
  c.width = c.height = 64;
  const x = c.getContext("2d");
  x.fillStyle = renk;
  x.fillRect(0, 0, 64, 64);
  const acik = desen.color ?? "rgba(255,255,255,.42)", koyu = "rgba(0,0,0,.2)";
  x.fillStyle = acik;
  x.strokeStyle = acik;
  x.lineWidth = 3;
  const yildiz = (cx, cy, r) => {
    x.beginPath();
    for (let i = 0; i < 10; i++) { const a = (i * Math.PI) / 5 - Math.PI / 2, rr = i % 2 ? r * 0.45 : r; x.lineTo(cx + Math.cos(a) * rr, cy + Math.sin(a) * rr); }
    x.closePath();
    x.fill();
  };
  switch (desen.pattern) {
    case "stripes": for (let i = 0; i < 64; i += 16) x.fillRect(i, 0, 6, 64); break;
    case "checks": for (let i = 0; i < 4; i++) for (let j = 0; j < 4; j++) if ((i + j) % 2 === 0) x.fillRect(i * 16, j * 16, 16, 16); break;
    case "dots": for (let i = 0; i < 4; i++) for (let j = 0; j < 4; j++) { x.beginPath(); x.arc(i * 16 + 8 + (j % 2) * 4, j * 16 + 8, 3.2, 0, Math.PI * 2); x.fill(); } break;
    case "camo":
      for (const [cx, cy, r, f] of [[14, 14, 13, "rgba(60,80,40,.6)"], [44, 20, 15, "rgba(120,100,60,.55)"], [26, 46, 14, "rgba(40,50,30,.5)"], [54, 50, 12, "rgba(60,80,40,.6)"], [6, 40, 9, "rgba(120,100,60,.55)"]]) {
        x.fillStyle = f; x.beginPath(); x.ellipse(cx, cy, r, r * 0.7, 0.6, 0, Math.PI * 2); x.fill();
      }
      break;
    case "stars": for (const [cx, cy] of [[12, 12], [40, 8], [56, 30], [26, 34], [8, 52], [44, 52]]) yildiz(cx, cy, 5); break;
    case "flowers":
      for (const [cx, cy] of [[16, 16], [48, 16], [16, 48], [48, 48]]) {
        for (let i = 0; i < 5; i++) { const a = (i * Math.PI * 2) / 5; x.beginPath(); x.arc(cx + Math.cos(a) * 5, cy + Math.sin(a) * 5, 3.2, 0, Math.PI * 2); x.fill(); }
        x.fillStyle = "#F2C27B"; x.beginPath(); x.arc(cx, cy, 2.6, 0, Math.PI * 2); x.fill(); x.fillStyle = acik;
      }
      break;
    case "zigzag":
      for (let y = 8; y < 64; y += 20) { x.beginPath(); for (let i = 0; i <= 8; i++) x.lineTo(i * 8, y + (i % 2 ? -5 : 5)); x.stroke(); }
      break;
    case "herringbone":
      x.strokeStyle = koyu;
      for (let i = -1; i < 5; i++) { x.beginPath(); x.moveTo(i * 16, 0); x.lineTo(i * 16 + 16, 16); x.lineTo(i * 16 + 32, 0); x.stroke();
        x.beginPath(); x.moveTo(i * 16, 32); x.lineTo(i * 16 + 16, 48); x.lineTo(i * 16 + 32, 32); x.stroke(); }
      break;
  }
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(3, 3);
  t.colorSpace = THREE.SRGBColorSpace;
  figurDesenOnbellek.set(k, t);
  return t;
}
