  // ---------- Kamp ateşi ----------
  const alevMat = new THREE.MeshStandardMaterial({ color: "#FF9A4A", emissive: new THREE.Color("#FF7A2A"), emissiveIntensity: 0.6, roughness: 0.4 });
  const alev = new THREE.Mesh(new THREE.ConeGeometry(0.16, 0.42, 7), alevMat);
