      const f = ((t + i * 4.7) / 14) % 1;
      const x = f < 0.35 ? 6.4 - (f / 0.35) * 1.8 : f < 0.65 ? 4.6 : 4.6 + ((f - 0.65) / 0.35) * 1.8;
      k.position.set(x, 0, 0.55 + i * 0.7);
