    const Dm = MEYDAN_DOSEME;
    if (_z.x < Dm.minX - 1.5 || _z.x > Dm.maxX + 1.5 || _z.z < Dm.minZ - 1.5 || _z.z > Dm.maxZ + 2) return;   // binalar, sokaklar
