      x.fillText(d.baskan ? ç("Belediye Başkanı") : ç("Belediye"), t.width / 2, 44, t.width - 40);
      x.fillStyle = "#1F2A2E"; x.font = `800 46px Figtree, system-ui, sans-serif`;
      x.fillText(d.baskan ? String(d.baskan).slice(0, 26) : ç("Geçici sistem yönetimi"), t.width / 2, 100, t.width - 40);
