const fikraMetni = (n) => FIKRALAR[Number(n) - 1] ?? "";

// ---------- Mekândaki yerin: giriş ve kalp atışı, canlı olaylar, yürüme ve eylem (hız sınırı), sipariş, fıkra ----------
// MekanZiyareti.ac(mekan, yer): yer "main" (salon) ya da "room:n" (otelin odası). Ekran bir görünüm bağlar (bagla); görünüm yeniden
// kurulsa da yerin kalır. Görünümün işleyicileri: durum(s) (sunucunun durumu: api.venue_state), yuru(p, x, z, kendim),
// eylem(p, e, hedef, oturak), cik(p), balon(kimlik, metin), ikram(veri), fikra(veri), gul(veri), bitti(neden, hata) — neden:
// "giris", "cikarildi", "kapi", "yolda", "kapandi", "aski", "dolu", "oda". Bağlantı koparsa yerin kalır, kalp atışı yeniden dener.
const MekanZiyareti = (() => {
  function ac(mekan, yer0 = "main") {
    let s = null, kapandi = false, gorunum = null, kanalBirak = null, sohbetBirak = null, kalp = null, kalpMs = 0;
    let durumZaman = null, giriyor = null, sonEylem = 0, benYerel = null, yer = yer0;
    const kisiler = new Map();
    const yuruS = { son: 0, pencere: 0, n: 0, bekleyen: null, zaman: null };
    const bildir = (ad, ...a) => { try { gorunum?.[ad]?.(...a); } catch (e) { console.error(e); } };
    const benimki = () => (s ? kisiler.get(s.presence_id) ?? null : null);

    async function gir() {
      if (kapandi) return null;
      if (giriyor) return giriyor;
      giriyor = (async () => {
        try {
          const yeni = await MekanYolu.gir(mekan, yer);
          if (kapandi) { MekanYolu.cik().catch(() => {}); return null; }
          durumAl(yeni);
          return yeni;
        } catch (e) {
          if (kapandi) return null;
          if (s && (e?.kod === "AG" || /^HATA_5/.test(String(e?.kod ?? "")))) return null;
          const ilk = !s;
          birak();
          bildir("bitti", ilk ? MEKAN_DUSME[e?.kod] ?? "giris" : MEKAN_DUSME[e?.kod] ?? "giris", e);
          return null;
        } finally { giriyor = null; }
      })();
      return giriyor;
    }
    function durumAl(yeni) {
      if (kapandi || !yeni) return;
      if (!yeni.in_venue) { gir(); return; }
      const once = s;
      if (s?.topic !== yeni.topic) {
        kanalBirak?.();
        kanalBirak = MekanYolu.dinle(yeni.topic, canliOlay);
        sohbetBirak?.();
        // Mekânın sohbeti (Burası): yazanın balonu figürünün üstünde
        sohbetBirak = Sunucu.Canli.dinle("place:" + yeni.topic, (olay, yuk) => {
          const m = yuk?.data ?? {};
          if (olay === "chat.message" && m.channel === "place" && m.author_id) bildir("balon", m.author_id, m.body ?? "");
        });
      }
      s = yeni;
      kisiler.clear();
      for (const k of s.people ?? []) kisiler.set(k.p, k);
      const ben = benimki();
      if (ben && benYerel && Date.now() - benYerel.t < 4000) Object.assign(ben, benYerel.veri);
      kalpKur();
      bildir("durum", s);
      if (!once || once.topic !== s.topic) Konusma.yerYenile?.();
    }
    function birak() {
      kanalBirak?.(); sohbetBirak?.();
      kanalBirak = sohbetBirak = null;
      clearInterval(kalp); kalp = null; kalpMs = 0;
      clearTimeout(durumZaman); clearTimeout(yuruS.zaman);
      const vardi = !!s;
      s = null;
      kisiler.clear();
      if (vardi) Konusma.yerYenile?.();
    }
    function kalpKur() {
      const yeni = Math.max(10, Number(s?.rule?.heartbeatSec ?? 45)) * 1000;
      if (kalp && yeni === kalpMs) return;
      clearInterval(kalp);
      kalpMs = yeni;
      kalp = setInterval(() => { if (!document.hidden) gir(); }, kalpMs);
    }
    const gorunurluk = () => { if (!document.hidden && !kapandi && s) gir(); };
    document.addEventListener("visibilitychange", gorunurluk);
    function durumIste() {
      clearTimeout(durumZaman);
      durumZaman = setTimeout(() => {
        if (!s || kapandi) return;
        MekanYolu.durum().then(durumAl).catch(() => {});
      }, 400);
    }
    function canliOlay(olay, v) {
      if (!s || kapandi) return;
      if (olay === "venue.entered" || olay === "venue.updated") { durumIste(); return; }
      if (olay === "venue.left") {
        if (v.p === s.presence_id) {
          birak();
          bildir("bitti", v.kicked ? "cikarildi" : v.closed ? "kapandi" : v.suspended ? "aski" : v.room_closed ? "oda" : v.door ? "kapi" : "giris");
          return;
        }
        if (kisiler.delete(v.p)) { s.people = [...kisiler.values()]; bildir("cik", v.p); bildir("durum", s); }
        return;
      }
      if (olay === "venue.served") {
        s.served = [...(s.served ?? []), { p: v.p, item: v.item, cat: v.cat, at: v.at }];
        if (v.feed_id) durumIste();
        bildir("ikram", v);
        const k = kisiler.get(v.p);
        if (k?.me && v.from !== s.presence_id) {
          tost(v.cat === "gift" ? ç("{ad} sana {kalem} hediye etti.", { ad: v.actor ?? ç("Biri"), kalem: menuAdi(v.item) })
            : ç("{ad} sana {kalem} ısmarladı.", { ad: v.actor ?? ç("Biri"), kalem: menuAdi(v.item) }), v.cat === "gift" ? "gift" : "hand-coins");
        }
        return;
      }
      if (olay === "venue.joke") { durumIste(); bildir("fikra", v); return; }
      if (olay === "venue.laugh") {
        const f = (s.feed ?? []).find((x) => Number(x.feed_id) === Number(v.feed_id));
        if (f) f.laughs = Number(v.laughs);
        bildir("gul", v);
        return;
      }
      const k = kisiler.get(v.p);
      if (!k) return;
      if (olay === "venue.moved") {
        if (k.me && benYerel && Date.now() - benYerel.t < 4000 && Number(benYerel.veri.x) === Number(v.x) && Number(benYerel.veri.z) === Number(v.z)) return;
        Object.assign(k, { x: Number(v.x), z: Number(v.z), moved_at: v.at, emote: null, emote_target: null, seat: null });
        bildir("yuru", v.p, Number(v.x), Number(v.z), false);
      } else if (olay === "venue.emote") {
        if (k.me) return;
        Object.assign(k, { emote: v.e, emote_at: v.at, emote_target: v.to ?? null, seat: v.seat ?? null });
        bildir("eylem", v.p, v.e, v.to ?? null, v.seat ?? null);
        if (v.e === "wave" && v.to && v.to === s.presence_id) {
          tost(k.hidden ? ç("Biri sana el salladı.") : ç("{ad} sana el salladı.", { ad: k.name }), "hand");
        }
      }
    }
    function yuru(x, z) {
      if (!s) { tost(ç("Mekâna giriliyor…"), "footprints"); return; }
      const w = s.rule ?? {}, simdi = Date.now();
      if (simdi - yuruS.pencere >= 60000) { yuruS.pencere = simdi; yuruS.n = 0; }
      if (yuruS.n >= Number(w.movesPerMinute ?? 40)) { tost(ç("Bir dakikada çok fazla yürüdün; biraz bekle."), "footprints"); return; }
      const ben = benimki();
      if (ben) Object.assign(ben, { x, z, emote: null, emote_target: null, seat: null });
      bildir("yuru", s.presence_id, x, z, true);
      benYerel = { t: simdi, veri: { x, z, emote: null, emote_target: null, seat: null } };
      yuruS.bekleyen = [x, z];
      clearTimeout(yuruS.zaman);
      yuruS.zaman = setTimeout(yuruGonder, Math.max(0, yuruS.son + Number(w.moveMinMs ?? 600) + 60 - simdi));
    }
    async function yuruGonder() {
      const h = yuruS.bekleyen;
      yuruS.bekleyen = null;
      if (!h || !s || kapandi) return;
      yuruS.son = Date.now();
      yuruS.n++;
      try { await MekanYolu.yuru(h[0], h[1]); } catch (e) {
        if (e?.kod === "VENUE_NOT_INSIDE") gir();
        else { tost(hataMetni(e), "footprints"); durumIste(); }
      }
    }
    // sessiz: hız sınırına takılınca uyarmadan vazgeçer (fıkraya gülünce figürün kendiliğinden gülmesi)
    function eylem(e, hedef = null, oturak = null, { sessiz = false } = {}) {
      if (!s) { if (!sessiz) tost(ç("Mekâna giriliyor…"), "hand"); return; }
      const simdi = Date.now();
      if (simdi - sonEylem < Number(s.rule?.emoteMinMs ?? 2000)) { if (!sessiz) tost(ç("Biraz yavaş: bir sonraki adım az sonra."), "hand"); return; }
      sonEylem = simdi;
      const ben = benimki();
      if (ben) Object.assign(ben, { emote: e, emote_at: new Date().toISOString(), emote_target: hedef, seat: oturak });
      bildir("eylem", s.presence_id, e, hedef, oturak);
      benYerel = { t: simdi, veri: { ...(benYerel && simdi - benYerel.t < 4000 ? benYerel.veri : {}), emote: e, emote_target: hedef, seat: oturak } };
      MekanYolu.eylem(e, hedef, oturak).catch((err) => {
        if (err?.kod === "VENUE_NOT_INSIDE") gir(); else { if (!sessiz) tost(hataMetni(err), "hand"); durumIste(); }
      });
    }
    async function cikar(p) {
      const r = await MekanYolu.cikar(p);
      if (s && kisiler.delete(p)) { s.people = [...kisiler.values()]; bildir("cik", p); bildir("durum", s); }
      return r;
    }
    function kapat() {
      if (kapandi) return;
      kapandi = true;
      document.removeEventListener("visibilitychange", gorunurluk);
      const icerde = !!s;
      birak();
      gorunum = null;
      if (icerde) MekanYolu.cik().catch(() => {}).finally(() => Konusma.yerYenile?.());
    }
    return {
      get s() { return s; }, get kisiler() { return [...kisiler.values()]; }, get kapandi() { return kapandi; }, get mekan() { return mekan; },
      get yer() { return yer; },
      gir, yuru, eylem, cikar, kapat, durumIste,
      bagla(g) { gorunum = g; if (s) bildir("durum", s); return () => { if (gorunum === g) gorunum = null; }; },
    };
  }
  return { ac };
})();

// ===== 98zg_mekan.js =====
// ---------- Şehrim → Mekânlar ve Mekânım (D-141) ----------
// Mekânlar (sehir/mekanlar): bu şehrin kahvehanesi (belediyenin; her şehirde), oyuncuların mekânları (tür, ad, sahibi, kapı,
// içerideki sayı, bugünkü etkinlik, otelde boş oda), şehrin yaklaşan etkinlikleri ("İlgileniyorum"), Mekânım (sahibi ya da
// yöneticisi olduğun: kasa, gider, durum) ve Konaklaman (otel odan); "Mekân aç" (ruhsat). Meydanın "Mekânlar" kapısı
// buraya açılır. Mekânım (sehir/mekanim): mekânın yönetimi — bugünün ve dünün kaydı, kasa (yalnız sahibi), tezgâh (erzak),
// fiyatlar (kural bandında), kapı, kulübün tarzı ve konser kirası, otelin gecelik fiyatı ve odaları, etkinlikler,
// yöneticiler (sahibinin arkadaşları), ad, askıdan çıkış ve kapatma. Dekor mekânın içinde düzenlenir (98zh_mekan_ic.js).
// Ekran sunucunun sınırlarını gösterir ve önceden denetler; karar sunucuda (venue-1.0.0).

const MEKAN_KAPI_ACIKLAMA = {
  open: ç("Herkes girer."),
  friends: ç("Yalnız sahibinin arkadaşları girer; yöneticiler ve otelin konukları her zaman girer."),
  closed: ç("Yalnız sahibi ve yöneticileri girer; içeridekiler dışarı çıkar."),
};
const MEKAN_ETKINLIK_DURUM = { scheduled: ç("Bekliyor"), live: ç("Sürüyor"), ended: ç("Bitti"), cancelled: ç("İptal edildi") };
const venueKurali = () => Durum.v.kurallar?.data?.venue ?? {};

// Yakınlığın yazısı (kişinin kartı, profil): basamak, puan, sıradaki basamağa kalan
function bagYazisi(b) {
  if (!b) return "";
  if (!b.tier) return `${ikon("hand")}${esc(ç("Henüz yakınlığınız yok: selamlaşınca, ısmarlayınca ve aynı masada oturunca artar."))}`;
  const kalan = b.next_tier === "friend" ? ç("arkadaş olunca basamak ilerler")
    : b.next_tier && b.next_at ? ç("{tur} için {n} puan daha", { tur: BAG_TUR[b.next_tier] ?? "", n: sayi(Math.max(0, Number(b.next_at) - Number(b.points))) }) : "";
  return `${ikon(BAG_IK[b.tier] ?? "hand")}<b>${esc(BAG_TUR[b.tier] ?? "")}</b> · ${esc(ç("yakınlık {n}", { n: sayi(b.points ?? 0) }))}${kalan ? " · " + esc(kalan) : ""}`;
}

// Düğmeli işlem: düğme işlem bitene dek kapalı (çift dokunuş iki istek göndermez); hata tostla
async function mekanIsle(dugme, is) {
  if (dugme?.disabled) return null;
  if (dugme) dugme.disabled = true;
  try { return await is(); } catch (e) { tost(hataMetni(e), "circle-alert"); return null; } finally { if (dugme?.isConnected) dugme.disabled = false; }
}

// Yönetim sayfasına git (hedef bir kez; sayfa yenilenirse oturumdan)
let mekanimHedef = null;
function mekanimGit(id) {
  mekanimHedef = id ?? null;
  try { if (id) sessionStorage.setItem("civora.mekanim", id); } catch { /* yok */ }
  Kabuk.git("sehir/mekanim");
}

// Mekânın satırı (Mekânlar ve Mekânım)
function mekanSatirHtml(v) {
  const tur = v.system ? ç("Şehrin kahvehanesi") : MEKAN_TUR[v.kind] ?? v.kind;
  const rol = v.role === "owner" ? ç("Senin mekânın") : v.role === "manager" ? ç("Yöneticisisin") : null;
  const giremez = !v.role && (v.status === "suspended" || v.door === "closed" || (v.door === "friends" && !v.owner_friend));
  const alt = [Number(v.people) ? ç("şu an içeride {n} kişi", { n: sayi(v.people) }) : ç("şu an içeride kimse yok"),
    !v.system && v.owner && v.role !== "owner" ? ç("sahibi {ad}", { ad: v.owner }) : null,
    v.kind === "otel" && !v.system ? ç("{n} boş oda", { n: sayi(v.rooms_free ?? 0) }) : null,
    v.status === "suspended" ? MEKAN_DURUM.suspended : !v.system && v.door !== "open" ? MEKAN_KAPI[v.door] : null].filter(Boolean).join(" · ");
  const e = v.event;
  const etk = e ? `<span class="cip ${e.status === "live" ? "konser-canli" : "altin"} mekan-etk-cip">${ikon(MEKAN_ETKINLIK_IK[e.kind] ?? "calendar")}${esc(e.status === "live"
    ? ç("Şimdi: {tur}", { tur: MEKAN_ETKINLIK[e.kind] ?? e.kind }) : ç("{zaman}: {tur}", { zaman: saatYaz(e.starts_at), tur: MEKAN_ETKINLIK[e.kind] ?? e.kind }))}</span>` : "";
  return `<div class="liste-satir mekan-satir${giremez ? " kapali" : ""}" data-mekan-satir="${esc(v.venue_id)}" data-tur="${esc(v.system ? "sistem" : v.kind)}">
    <span class="liste-ikon ${v.role ? "yesil" : ""}">${ikon(MEKAN_TUR_IK[v.kind] ?? "sofa")}</span>
    <div><span class="tur">${esc(tur)}${rol ? " · " + esc(rol) : ""}</span><b>${esc(mekanAdi(v))}</b><div class="alt">${esc(alt)}</div>${etk}</div>
    <div class="mekan-satir-dugmeler">
      <button class="dugme kucuk-d" data-mekan-git="${esc(v.venue_id)}" ${!v.role && v.status === "suspended" ? "disabled" : ""}>${ikon("door-open")}${ç("Gir")}</button>
      ${v.kind === "otel" && !v.system && !v.role ? `<button class="dugme ikincil kucuk-d" data-mekan-kal="${esc(v.venue_id)}" ${Number(v.rooms_free) > 0 && v.status === "open" ? "" : "disabled"}>${ikon("bed")}${ç("Oda tut")}</button>` : ""}
      ${v.role ? `<button class="dugme ikincil kucuk-d" data-mekan-yonet="${esc(v.venue_id)}">${ikon("settings")}${ç("Yönet")}</button>` : ""}
    </div></div>`;
}

// Mekân açmak (ruhsat): tür (şehrin seviyesine göre), ad; ruhsat, gider ve sınırlar önceden yazılır
function mekanAcPenceresi(r, sonra) {
  const R = venueKurali(), Rk = R.kinds ?? r?.rule?.kinds ?? {};
  const seviye = Number(r?.city_level ?? 1);
  const turler = ["kahvehane", "kulup", "otel"];
  const ilk = turler.find((t) => seviye >= Number(Rk[t]?.minLevel ?? 1));
  const N = R.name ?? r?.rule?.name ?? { min: 3, max: 40, renameDays: 30 };
  const gun = Number((R.suspend ?? r?.rule?.suspend)?.graceDays ?? 14);
  const L = R.limits ?? r?.rule?.limits ?? {};
  pencereForm({ ust: ç("Mekân aç · {sehir}", { sehir: bolgeAdi(r?.region_id) }), baslik: ç("Kendi mekânını aç"), onayAd: ç("Ruhsatı al ve aç"), onayIkon: "key-round",
    govde: `<fieldset class="alan"><legend>${ç("Türü")}</legend><div class="radyo-liste">${turler.map((t) => {
        const k = Rk[t] ?? {}, acik = seviye >= Number(k.minLevel ?? 1);
        return `<label class="radyo${acik ? "" : " kapali"}"><input type="radio" name="tur" value="${t}" ${acik ? "" : "disabled"} ${t === ilk ? "checked" : ""}>
          <span><b>${ikon(MEKAN_TUR_IK[t])} ${esc(MEKAN_TUR[t])}</b><span class="kucuk">${esc(MEKAN_TUR_ACIKLAMA[t])}</span>
          <span class="kucuk">${esc(acik ? ç("Ruhsat {r} kredi · günlük gider {g} kredi · {n} kişilik", { r: kr(Number(k.licenseCr ?? 0)), g: kr(Number(k.upkeepCr ?? 0)), n: sayi(Number(k.capacity ?? 0)) })
            : ç("Şehir {s}. seviyeye büyüyünce açılır.", { s: Number(k.minLevel ?? 2) }))}</span></span></label>`;
      }).join("")}</div></fieldset>
      <label class="alan"><span>${ç("Mekânın adı")}</span><input name="ad" required minlength="${Number(N.min)}" maxlength="${Number(N.max)}" autocomplete="off" placeholder="${ç("Örn. Çınaraltı Kahvesi")}">
        <small>${ç("{a}–{b} harf. Ad topluluk kurallarına uyar; {g} günde bir değiştirilir.", { a: Number(N.min), b: Number(N.max), g: Number(N.renameDays ?? 30) })}</small></label>
      <p class="kucuk">${ç("Ruhsat ve günlük gider ülkenin başkent belediyesine geçer. Gider her gün mekânın kasasından ödenir; kasa yetmezse mekân askıya girer, {g} gün askıda kalan kapanır.", { g: gun })}</p>
      <p class="kucuk">${ç("Kişi başına bir mekân. Bu şehirde {n} / {m} mekân yeri dolu; şehir büyüdükçe artar. Hesabın en az {d} günlük olmalı.",
        { n: (r?.venues ?? []).length, m: Number(r?.city_venues_max ?? seviye * 2), d: Number(L.accountDays ?? 3) })}</p>`,
    is: async (d) => {
      const tur = String(d.get("tur") ?? ""), ad = String(d.get("ad") ?? "").trim().replace(/\s+/g, " ");
      if (!tur) throw new Error(ç("Mekânın türünü seç."));
      if (ad.length < Number(N.min) || ad.length > Number(N.max)) throw new Error(ç("Mekânın adı {a}–{b} harf olmalı.", { a: Number(N.min), b: Number(N.max) }));
      const v = await MekanYolu.ac(tur, ad);
      tost(ç("Mekânın açıldı: {ad}. Menüyü, fiyatları ve dekoru Mekânım'dan düzenlersin.", { ad: v.name ?? ad }), "key-round");
      Durum.ozet().catch(() => {});
      sonra?.(v);
    } });
}

// Otelde oda tutmak: gece sayısı, toplam bedel (beklenen bedelle gönderilir; fiyat değiştiyse sunucu yapmaz)
function otelKalPenceresi(v, sonra) {
  const H = venueKurali().hotel ?? {};
  const enCok = Number(H.maxNights ?? 7), fiyat = Number(v.night_price_cr ?? 0), kredi = krediVar();
  pencereForm({ ust: ç("Otel · {sehir}", { sehir: bolgeAdi(v.region_id) }), baslik: mekanAdi(v), onayAd: ç("Odayı tut"), onayIkon: "bed",
    govde: `<p class="aciklama">${ç("Gecesi {kr} kredi · {n} boş oda.", { kr: kr(fiyat), n: sayi(v.rooms_free ?? 0) })}</p>
      <label class="alan"><span>${ç("Kaç gece")}</span><select name="gece">${Array.from({ length: enCok }, (_, i) => i + 1).map((n) =>
        `<option value="${n}" ${n * fiyat > kredi ? "disabled" : ""}>${esc(ç("{n} gece · {kr} kredi", { n, kr: kr(n * fiyat) }))}</option>`).join("")}</select></label>
      <p class="kucuk">${ç("Bedelin tamamı hesabında ayrılır; her gecenin başında bir gecelik bedel otele geçer. Erken ayrılırsan kalan geceler sana döner.")}</p>
      <p class="kucuk">${ç("Oda senin geçici odandır: arkadaşların en çok {n} kişi gelir, içinde Burası odanın sohbetidir. Oda güç ya da ikamet vermez.", { n: Number(H.guests ?? 3) })}</p>`,
    is: async (d) => {
      const n = Number(d.get("gece"));
      if (!(n >= 1 && n <= enCok)) throw new Error(ç("Gece sayısını seç."));
      const s = await MekanYolu.kal(v.venue_id, n, n * fiyat);
      tost(ç("Odan hazır: {oda}. oda, {n} gece.", { oda: Number(s.room), n: Number(s.nights) }), "bed");
      Durum.ozet().catch(() => {});
      sonra?.(s);
    } });
}

// Hediyelerim: yalnız kendin görürsün (profilde yalnız sayısı)
async function hediyelerimPenceresi() {
  let h;
  try { h = await MekanYolu.hediyeler(); } catch (e) { tost(hataMetni(e), "circle-alert"); return; }
  const l = h?.items ?? [];
  pencere({ ust: ç("Hediyelerim"), baslik: ç("{n} hediye", { n: sayi(h?.count ?? l.length) }),
    govde: `<p class="aciklama">${ç("Mekânlarda sana verilen hediyeler. Yalnız sen görürsün; profilinde yalnız sayısı görünür. Hediye satılmaz ve para etmez.")}</p>
      ${l.length ? `<div class="liste mekan-hediyeler">${l.map((x) => `<div class="liste-satir"><span class="liste-ikon mor">${ikon(MENU_KALEM[x.item]?.[1] ?? "gift")}</span>
          <div><span class="tur">${esc(zamanOnce(x.at))}</span><b>${esc(menuAdi(x.item))}</b><div class="alt">${esc([x.from ? ç("{ad} verdi", { ad: x.from }) : ç("silinmiş bir oyuncu verdi"),
            x.venue ?? (x.region_id ? ç("{sehir} Kahvehanesi", { sehir: bolgeAdi(x.region_id) }) : null), x.venue && x.region_id ? bolgeAdi(x.region_id) : null].filter(Boolean).join(" · "))}</div></div><span></span></div>`).join("")}</div>`
        : `<p class="bos">${ç("Henüz hediyen yok. Mekânlarda arkadaşların sana çiçek, çikolata ya da kitap verebilir.")}</p>`}` });
}

// Konaklamanın satırı: otel, oda, geceler; odana git, ayrıl
function kalisHtml(s, burada) {
  const ayni = burada === s.region_id;
  return `<div class="liste-satir" data-kalis="${esc(s.stay_id)}"><span class="liste-ikon lacivert">${ikon("bed")}</span>
    <div><span class="tur">${esc(bolgeAdi(s.region_id))}</span><b>${esc(ç("{otel} · {oda}. oda", { otel: s.venue ?? "", oda: Number(s.room) }))}</b>
      <div class="alt">${esc(ç("{a} / {b} gece ödendi · çıkış {zaman}", { a: Number(s.nights_paid), b: Number(s.nights), zaman: saatYaz(s.ends_at) }))}${ayni ? "" : " · " + esc(ç("odana otelin şehrinde girersin"))}</div></div>
    <div class="mekan-satir-dugmeler"><button class="dugme kucuk-d" data-kalis-git ${ayni ? "" : "disabled"}>${ikon("bed")}${ç("Odana git")}</button>
      <button class="dugme sade kucuk-d" data-kalis-ayril>${ikon("door-open")}${ç("Ayrıl")}</button></div></div>`;
}
function kalisAyril(s, sonra) {
  const kalan = Math.max(0, Number(s.nights) - Number(s.nights_paid));
  pencere({ ust: ç("Konaklama"), baslik: ç("{otel} otelinden ayrıl", { otel: s.venue ?? "" }),
    govde: `<p class="aciklama">${kalan ? ç("Ödenmemiş {n} gecenin bedeli ({kr} kredi) sana döner; oda boşalır.", { n: kalan, kr: kr(kalan * Number(s.night_price_cr ?? 0)) })
      : ç("Bütün geceler ödendi; oda boşalır.")}</p>`,
    dugmeler: [{ ad: ç("Vazgeç") }, { ad: ç("Ayrıl"), sinif: "mercan", ikon: "door-open", is: async () => {
      try { await MekanYolu.ayril(s.stay_id); tost(ç("Otelden ayrıldın."), "door-open"); Durum.ozet().catch(() => {}); } catch (e) { tost(hataMetni(e), "circle-alert"); }
      sonra?.();
    } }] });
}

// ---------- Ekran: bu şehrin mekânları ----------
Kabuk.kaydet("sehir/mekanlar", {
  async ac(kap) {
    let r = null, hata = null;
    const bildiri = mekanBildiri;
    mekanBildiri = null;
    await Durum.kurallar().catch(() => null);
    async function yukle() { try { r = await MekanYolu.burada(); hata = null; } catch (e) { hata = e; } }

    function ciz() {
      if (hata && !r) {
        kap.innerHTML = `<div class="sayfa"><div class="hata-kutusu">${ikon("circle-alert")}<span>${esc(hataMetni(hata))}</span></div>
          <button class="dugme ikincil" style="margin-top:14px" id="mekan-yeniden">${ç("Yeniden dene")}</button></div>`;
        $("#mekan-yeniden", kap).onclick = () => tazele();
        return;
      }
      const sis = r.system, venues = r.venues ?? [], mine = r.mine ?? [], olaylar = r.events ?? [];
      const sahibi = mine.some((v) => v.role === "owner");
      const enCok = Number(r.city_venues_max ?? 0);
      kap.innerHTML = `<div class="sayfa">
        <div class="sayfa-bas"><div><p class="ust-yazi">${ç("Şehrim")}</p><h1 class="b1">${ç("Mekânlar")}</h1>
          <p class="aciklama">${ç("Kahvehanede, kulüpte ve otelde şehrin oyuncularıyla oturursun: çay ısmarlar, hediye verir, fıkra anlatırsın. Kendi mekânını da açabilirsin.")}</p></div>
          ${meydanaDonDugme("mekan")}</div>
        ${bildiri ? `<div class="bilgi-kutusu" id="mekan-bildiri" style="margin-bottom:14px">${ikon("door-open")}<span>${esc(bildiri)}</span></div>` : ""}
        ${r.on_road ? `<div class="bilgi-kutusu" style="margin-bottom:14px">${ikon("route")}<span>${ç("Yoldasın; vardığın şehrin mekânları burada görünür.")}</span></div>` : ""}
        ${sis ? mekanBant("mekan_kahvehane", bolgeAdi(sis.region_id), mekanAdi(sis),
          ç("Belediyenin kahvehanesi: çay, kahve, ayran, limonata ve çiçek. Şu an içeride {n} kişi.", { n: sayi(sis.people ?? 0) }),
          `<button class="dugme altin" data-mekan-git="${esc(sis.venue_id)}" id="mekan-sistem-gir">${ikon("door-open")}${ç("İçeri gir")}</button>`) : ""}
        <div class="izgara mekan-izgara">
          <section class="kart" id="mekan-liste"><div class="kart-bas"><div><p class="ust-yazi">${esc(r.region_id ? bolgeAdi(r.region_id) : ç("Yoldasın"))}</p>
            <h2 class="b2">${ç("Oyuncuların mekânları")}</h2></div><span class="ik-kutu">${ikon("sofa")}</span></div>
            ${venues.length ? `<div class="liste">${venues.map(mekanSatirHtml).join("")}</div>`
              : `<p class="bos">${r.region_id ? ç("Bu şehirde henüz oyuncu mekânı yok. İlk kahvehaneyi sen aç!") : ç("Yoldayken mekânlar görünmez.")}</p>`}
            ${r.region_id ? `<p class="kucuk" style="margin-top:10px">${ç("Bu şehirde {n} / {m} mekân yeri dolu (şehrin seviyesine göre).", { n: venues.length, m: enCok })}</p>` : ""}
          </section>
          <section class="kart" id="mekan-etkinlikler"><div class="kart-bas"><div><p class="ust-yazi">${ç("Bu şehirde")}</p><h2 class="b2">${ç("Etkinlikler")}</h2></div><span class="ik-kutu">${ikon("calendar")}</span></div>
            ${olaylar.length ? `<div class="liste">${olaylar.map(etkinlikSatir).join("")}</div>`
              : `<p class="bos">${ç("Yaklaşan etkinlik yok. Mekân sahipleri çay saati, canlı müzik, şiir gecesi gibi etkinlikler açar.")}</p>`}</section>
          <section class="kart" id="mekan-mekanim"><div class="kart-bas"><div><p class="ust-yazi">${ç("Mekânım")}</p><h2 class="b2">${mine.length ? ç("Yönettiğin mekânlar") : ç("Kendi mekânın")}</h2></div><span class="ik-kutu">${ikon("key-round")}</span></div>
            ${mine.length ? `<div class="liste">${mine.map(mekanimSatir).join("")}</div>` : `<p class="aciklama">${ç("Kahvehane (her şehirde), kulüp ya da otel (şehir 2. seviyede) açabilirsin. Menüye fiyat koyar, dekoru düzenler, etkinlik açarsın; müşterilerin siparişi ve günlük simülasyon müşterisi kasana gelir.")}</p>`}
            ${!sahibi && r.region_id ? `<div class="oneri-dugmeler" style="margin-top:12px"><button class="dugme altin kucuk-d" id="mekan-ac">${ikon("key-round")}${ç("Mekân aç")}</button></div>` : ""}
          </section>
          ${r.stay ? `<section class="kart" id="mekan-kalis"><div class="kart-bas"><div><p class="ust-yazi">${ç("Otel")}</p><h2 class="b2">${ç("Konaklaman")}</h2></div><span class="ik-kutu">${ikon("bed")}</span></div>
            <div class="liste">${kalisHtml(r.stay, r.region_id)}</div></section>` : ""}
          <section class="kart" id="mekan-baglar"><div class="kart-bas"><div><p class="ust-yazi">${ç("Yakınlık")}</p><h2 class="b2">${ç("Tanıdık → arkadaş → yakın dost → kanka")}</h2></div><span class="ik-kutu">${ikon("heart-handshake")}</span></div>
            <p class="aciklama">${ç("Mekânda selamlaştıkça, ısmarladıkça, fıkrasına güldükçe ve aynı masada oturdukça yakınlığınız artar (son 90 gün). Arkadaşken 20 puanda yakın dost, 50 puanda kanka olursunuz. Yakınlık güç, gelir ya da oy vermez.")}</p>
            <div class="oneri-dugmeler"><button class="dugme ikincil kucuk-d" id="mekan-arkadaslar">${ikon("users-round")}${ç("Arkadaşlar ve tanıdıklar")}</button>
              <button class="dugme ikincil kucuk-d" id="mekan-hediyeler">${ikon("gift")}${ç("Hediyelerim")}</button></div></section>
        </div></div>`;
      bagla();
    }
    function etkinlikSatir(e) {
      const canli = e.status === "live";
      const yer = e.venue_system ? ç("{sehir} Kahvehanesi", { sehir: bolgeAdi(r.region_id) }) : e.venue ?? "";
      return `<div class="liste-satir" data-etkinlik-satir="${esc(e.event_id)}"><span class="liste-ikon ${canli ? "mercan" : "altin"}">${ikon(MEKAN_ETKINLIK_IK[e.kind] ?? "calendar")}</span>
        <div><span class="tur">${esc(canli ? ç("Şimdi · {saat}'e kadar", { saat: saatKisa(e.ends_at) }) : saatYaz(e.starts_at))}</span><b>${esc(MEKAN_ETKINLIK[e.kind] ?? e.kind)}</b>
          <div class="alt">${esc([yer, MEKAN_TUR[e.venue_kind] ?? null, Number(e.interested) ? ç("{n} kişi ilgileniyor", { n: sayi(e.interested) }) : null].filter(Boolean).join(" · "))}</div></div>
        <div class="mekan-satir-dugmeler">${canli ? "" : `<button class="dugme ${e.mine ? "" : "ikincil"} kucuk-d" data-etkinlik-ilgi="${esc(e.event_id)}" aria-pressed="${!!e.mine}">${ikon("bell")}${e.mine ? ç("İlgileniyorsun") : ç("İlgileniyorum")}</button>`}
          <button class="dugme kucuk-d" data-mekan-git="${esc(e.venue_id)}">${ikon("door-open")}${ç("Git")}</button></div></div>`;
    }
    function mekanimSatir(v) {
      const m = v.manage ?? {};
      const durum = v.status === "suspended" ? ç("Askıda: borç {kr} kredi", { kr: kr(m.debt_cr ?? 0) })
        : ç("Kasa {kr} kredi · günlük gider {g} kredi", { kr: kr(m.cash?.spendable ?? 0), g: kr(m.upkeep_cr ?? 0) });
      return `<div class="liste-satir mekan-satir" data-mekanim-satir="${esc(v.venue_id)}"><span class="liste-ikon ${v.status === "suspended" ? "mercan" : "yesil"}">${ikon(MEKAN_TUR_IK[v.kind] ?? "sofa")}</span>
        <div><span class="tur">${esc([MEKAN_TUR[v.kind], bolgeAdi(v.region_id), v.role === "owner" ? ç("sahibisin") : ç("yöneticisisin")].join(" · "))}</span><b>${esc(v.name)}</b>
          <div class="alt">${esc(durum)} · ${esc(Number(v.people) ? ç("içeride {n} kişi", { n: sayi(v.people) }) : ç("içeride kimse yok"))}</div></div>
        <div class="mekan-satir-dugmeler"><button class="dugme kucuk-d" data-mekan-git="${esc(v.venue_id)}">${ikon("door-open")}${ç("Gir")}</button>
          <button class="dugme ikincil kucuk-d" data-mekan-yonet="${esc(v.venue_id)}">${ikon("settings")}${ç("Yönet")}</button></div></div>`;
    }
    const bul = (id) => [r.system, ...(r.venues ?? []), ...(r.mine ?? [])].find((v) => v?.venue_id === id) ?? null;
    function bagla() {
      meydanaDonBagla(kap);
      for (const b of $$("[data-mekan-git]", kap)) b.onclick = () => MekanYolu.git(b.dataset.mekanGit);
      for (const b of $$("[data-mekan-yonet]", kap)) b.onclick = () => mekanimGit(b.dataset.mekanYonet);
      for (const b of $$("[data-mekan-kal]", kap)) b.onclick = () => { const v = bul(b.dataset.mekanKal); if (v) otelKalPenceresi(v, () => tazele()); };
      for (const b of $$("[data-etkinlik-ilgi]", kap)) b.onclick = () => mekanIsle(b, async () => {
        const e = (r.events ?? []).find((x) => x.event_id === b.dataset.etkinlikIlgi);
        if (!e) return;
        const y = await MekanYolu.ilgi(e.event_id, !e.mine);
        tost(y.mine ? ç("Etkinlik başlarken haber vereceğiz.") : ç("Artık haber vermeyeceğiz."), "bell");
        await tazele();
      });
      $("#mekan-ac", kap)?.addEventListener("click", () => mekanAcPenceresi(r, (v) => { if (v?.venue_id) mekanimGit(v.venue_id); else tazele(); }));
      $("#mekan-arkadaslar", kap)?.addEventListener("click", () => Kabuk.git("meydan/arkadas"));
      $("#mekan-hediyeler", kap)?.addEventListener("click", hediyelerimPenceresi);
      const k = $("#mekan-kalis", kap);
      if (k && r.stay) {
        $("[data-kalis-git]", k)?.addEventListener("click", () => MekanYolu.git(r.stay.venue_id, r.stay.space));
        $("[data-kalis-ayril]", k)?.addEventListener("click", () => kalisAyril(r.stay, () => tazele()));
      }
    }
    const tazele = tazeleyici(async () => { await yukle(); ciz(); });
    await yukle();
    ciz();
    // Şehrin mekânları değişince (açıldı, askıya girdi, kapandı, etkinlik) ve kişisel mekân olaylarında tazelenir
    const b1 = Sunucu.Canli.dinle("public:place", (olay, yuk) => { if (olay === "venue.changed" && yuk?.data?.region_id && yuk.data.region_id === r?.region_id) tazele(); });
    const b2 = Durum.dinle("olay", ({ olay }) => { if (/^(venue\.|travel\.arrived)/.test(olay)) tazele(); });
    const saat = setInterval(() => { if (!document.hidden) tazele(); }, 60000);
    return () => { b1(); b2(); clearInterval(saat); };
  },
});

// ---------- Ekran: mekânın yönetimi (sahibi ve yöneticisi) ----------
Kabuk.kaydet("sehir/mekanim", {
  async ac(kap) {
    let r = null, v = null, hata = null, ark = null;
    let id = mekanimHedef ?? (() => { try { return sessionStorage.getItem("civora.mekanim"); } catch { return null; } })();
    mekanimHedef = null;
    await Durum.kurallar().catch(() => null);
    async function yukle() {
      try {
        r = await MekanYolu.burada();
        const l = r.mine ?? [];
        v = l.find((x) => x.venue_id === id) ?? l[0] ?? null;
        if (v) { id = v.venue_id; try { sessionStorage.setItem("civora.mekanim", id); } catch { /* yok */ } }
        if (v?.role === "owner" && ark === null) ark = (await Sunucu.cagir("friends").catch(() => null))?.friends ?? [];
        hata = null;
      } catch (e) { hata = e; }
    }
    const R = () => venueKurali();
    // Kaydedilmemiş giriş (bir alana yazıldı ya da seçim değişti): canlı olay ve dakikalık tazeleme sayfayı yeniden çizmez,
    // yazılan kaybolmaz; tazeleme bir sonraki çizimden sonraya kalır. Tazeleme başladıktan sonra yazılmaya başlandıysa da
    // (yanıt yazarken gelir) yeniden çizilmez (27 Ekim 2026: geç gelen hediye bildirimi kasaya yazılan tutarı siliyordu).
    let kirli = false, bekleyen = false;
    const degisti = () => { kirli = true; };
    kap.addEventListener("input", degisti);
    kap.addEventListener("change", degisti);
    const tazeleIste = () => { if (kirli) bekleyen = true; else arkaTazele(); };

    function ciz() {
      kirli = false;
      if (bekleyen) { bekleyen = false; setTimeout(() => arkaTazele()); }
      if (hata && !v) {
        kap.innerHTML = `<div class="sayfa"><div class="hata-kutusu">${ikon("circle-alert")}<span>${esc(hataMetni(hata))}</span></div>
          <button class="dugme ikincil" style="margin-top:14px" id="mekanim-yeniden">${ç("Yeniden dene")}</button></div>`;
        $("#mekanim-yeniden", kap).onclick = () => tazele();
        return;
      }
      if (!v) {
        kap.innerHTML = `<div class="sayfa"><div class="sayfa-bas"><div><p class="ust-yazi">${ç("Şehrim · Mekânlar")}</p><h1 class="b1">${ç("Mekânım")}</h1>
            <p class="aciklama">${ç("Sahibi ya da yöneticisi olduğun bir mekân yok.")}</p></div></div>
          <div class="oneri-dugmeler"><button class="dugme ikincil" id="mekanim-liste">${ikon("sofa")}${ç("Mekânlar")}</button>
            ${r?.region_id ? `<button class="dugme altin" id="mekanim-ac">${ikon("key-round")}${ç("Mekân aç")}</button>` : ""}</div></div>`;
        $("#mekanim-liste", kap).onclick = () => Kabuk.git("sehir/mekanlar");
        $("#mekanim-ac", kap)?.addEventListener("click", () => mekanAcPenceresi(r, (x) => { id = x?.venue_id ?? id; tazele(); }));
        return;
      }
      const m = v.manage ?? {}, sahibi = v.role === "owner";
      const digerleri = (r.mine ?? []).filter((x) => x.venue_id !== v.venue_id);
      kap.innerHTML = `<div class="sayfa">
        <div class="sayfa-bas"><div><p class="ust-yazi">${esc([ç("Mekânım"), MEKAN_TUR[v.kind], bolgeAdi(v.region_id)].join(" · "))}</p><h1 class="b1" id="mekanim-ad">${esc(v.name)}</h1>
          <p class="aciklama">${esc([sahibi ? ç("Sahibisin.") : ç("Yöneticisisin: kasaya dokunmaz, mekânı kapatmazsın."), MEKAN_DURUM[v.status] ?? "", MEKAN_KAPI[v.door] ?? ""].filter(Boolean).join(" · "))}</p></div>
          <div class="kart-bas-dugmeler"><button class="dugme altin kucuk-d" data-mekan-git="${esc(v.venue_id)}">${ikon("door-open")}${ç("İçeri gir")}</button>
            <button class="dugme ikincil kucuk-d" id="mekanim-dekor">${ikon("move")}${ç("Dekoru düzenle")}</button>
            <button class="dugme sade kucuk-d" id="mekanim-liste">${ikon("sofa")}${ç("Mekânlar")}</button></div></div>
        ${digerleri.length ? `<div class="secim-sec" style="margin-bottom:12px">${[v, ...digerleri].map((x) => `<button class="secim-cip" type="button" data-mekanim-sec="${esc(x.venue_id)}" aria-pressed="${x.venue_id === v.venue_id}">${ikon(MEKAN_TUR_IK[x.kind] ?? "sofa")}${esc(x.name)}</button>`).join("")}</div>` : ""}
        ${v.status === "suspended" ? askiHtml(v, m, sahibi) : ""}
        ${v.name_reset ? `<div class="hata-kutusu" style="margin-bottom:14px">${ikon("id-card")}<span>${ç("Moderatör mekânın adını kaldırdı; aşağıdan yeni bir ad seç (beklemeden bir kez).")}</span></div>` : ""}
        <div class="izgara mekanim-izgara">
          ${gunHtml(v, m)}${kasaHtml(m, sahibi)}${tezgahHtml(m, sahibi)}${fiyatHtml(v)}${ayarHtml(v)}${v.kind === "otel" ? odalarHtml(m) : ""}
          ${etkinlikHtml(m)}${yoneticiHtml(m, sahibi)}${sahibi ? adHtml(v) : ""}${sahibi ? kapatHtml() : ""}
        </div></div>`;
      bagla();
    }
    function askiHtml(v, m, sahibi) {
      const son = v.manage?.suspended_at ? new Date(Date.parse(v.manage.suspended_at) + Number(m.grace_days ?? 14) * 86400e3).toISOString() : null;
      return `<div class="hata-kutusu mekanim-aski" style="margin-bottom:14px">${ikon("circle-alert")}<span>${ç("Mekân askıda: günlük gider ödenemedi, borç {kr} kredi. Kapı kapalı, satış ve simülasyon müşterisi yok.", { kr: kr(m.debt_cr ?? 0) })}
        ${son ? " " + esc(ç("{zaman} tarihine kadar borç ödenmezse mekân kapanır.", { zaman: saatYaz(son) })) : ""}
        ${sahibi ? " " + ç("Kasaya koyup “Borcu öde ve aç” de.") : " " + ç("Borcu yalnız sahibi öder.")}</span>
        ${sahibi ? `<button class="dugme altin kucuk-d" id="mekanim-ac-yeniden">${ikon("door-open")}${ç("Borcu öde ve aç")}</button>` : ""}</div>`;
    }
    function gunHtml(v, m) {
      const t = m.today ?? {}, d = m.yesterday, dk = Math.floor(Number(t.staff_seconds ?? 0) / 60), esik = Number(m.operated_minutes ?? 15);
      return `<section class="kart" id="mekanim-gun"><div class="kart-bas"><div><p class="ust-yazi">${ç("Bugün")}</p><h2 class="b2">${ç("Mekânın günü")}</h2></div><span class="ik-kutu">${ikon("chart-line")}</span></div>
        <div class="bilgi-izgara">
          <div><small>${ç("Satış")}</small><b>${esc(ç("{n} sipariş · {kr} kredi", { n: sayi(t.sales_count ?? 0), kr: kr(t.sales_cr ?? 0) }))}</b></div>
          <div><small>${ç("İşletme")}</small><b>${esc(dk >= esik ? ç("Bugün işletildi") : ç("{n} / {m} dakika", { n: dk, m: esik }))}</b></div>
          <div><small>${ç("İçeride")}</small><b>${esc(ç("{n} / {m} kişi", { n: sayi(v.people ?? 0), m: sayi(v.capacity ?? 0) }))}</b></div>
          <div><small>${ç("Çekicilik")}</small><b>${esc(ç("{a} / {b}", { a: sayi(v.ambiance ?? 0), b: sayi(m.decor_max ?? 0) }))}</b></div>
        </div>
        <p class="kucuk">${d ? esc(ç("Dün: {s} sipariş ({kr} kredi); simülasyon müşterisi {m} kişi, {p} kredi (vergiden sonra {n}); gider {g} kredi.",
          { s: sayi(d.sales_count ?? 0), kr: kr(d.sales_cr ?? 0), m: sayi(d.sim_visitors ?? 0), p: kr(d.sim_cr ?? 0), n: kr(d.sim_net ?? 0), g: kr(d.upkeep_cr ?? 0) })) : esc(ç("Dünün kaydı yok."))}</p>
        <p class="kucuk">${ç("Simülasyon müşterisi yalnız işletilmiş günlerde gelir: sahibi ya da yöneticisi o gün en az {n} dakika içeride bulunmalı. Etkinlik günü, uygun fiyat ve çekici dekor daha çok müşteri getirir.", { n: esik })}</p></section>`;
    }
    function kasaHtml(m, sahibi) {
      const c = m.cash ?? {};
      return `<section class="kart" id="mekanim-kasa"><div class="kart-bas"><div><p class="ust-yazi">${ç("Kasa")}</p><h2 class="b2">${esc(ç("{kr} kredi", { kr: kr(c.spendable ?? 0) }))}</h2></div><span class="ik-kutu">${ikon("wallet")}</span></div>
        <p class="kucuk">${esc(ç("Günlük gider ({g} kredi) her gün kasadan belediyeye geçer.", { g: kr(m.upkeep_cr ?? 0) }))}${Number(c.held) ? " " + esc(ç("Ayrılmış: {kr} kredi.", { kr: kr(c.held) })) : ""}${Number(m.debt_cr) ? " " + esc(ç("Borç: {kr} kredi.", { kr: kr(m.debt_cr) })) : ""}</p>
        ${sahibi ? `<div class="form mekanim-form" data-mekanim-kasa><label class="alan"><span>${ç("Tutar (kredi)")}</span><input name="tutar" inputmode="decimal" autocomplete="off" placeholder="${ç("Örn. 50")}"></label>
            <div class="satir" style="flex-wrap:wrap;gap:8px"><button class="dugme kucuk-d" type="button" data-kasa="koy">${ikon("plus")}${ç("Kasaya koy")}</button>
              <button class="dugme ikincil kucuk-d" type="button" data-kasa="cek">${ikon("minus")}${ç("Kasadan çek")}</button></div>
            <p class="kucuk">${esc(ç("Hesabında {kr} kredi var.", { kr: kr(krediVar()) }))}</p></div>`
          : `<p class="kucuk">${ç("Kasaya yalnız sahibi koyar ve çeker.")}</p>`}</section>`;
    }
    function tezgahHtml(m, sahibi) {
      return `<section class="kart" id="mekanim-tezgah"><div class="kart-bas"><div><p class="ust-yazi">${ç("Tezgâh")}</p><h2 class="b2">${esc(ç("{n} / {m} erzak", { n: sayi(m.stock ?? 0), m: sayi(m.stock_max ?? 0) }))}</h2></div><span class="ik-kutu">${ikon("croissant")}</span></div>
        <p class="kucuk">${esc(ç("Yiyecek (tost, simit, atıştırmalık, kahvaltı) satılınca tezgâhtan bir erzak tükenir. Tezgâha çantandan koyarsın; mekânın şehrinde olmalısın. Çantanda {n} erzak.", { n: sayi(Durum.stok("erzak@1")) }))}</p>
        <div class="form mekanim-form" data-mekanim-tezgah><label class="alan"><span>${ç("Adet")}</span><input name="adet" inputmode="numeric" autocomplete="off" placeholder="${ç("Örn. 10")}"></label>
          <div class="satir" style="flex-wrap:wrap;gap:8px"><button class="dugme kucuk-d" type="button" data-tezgah="koy">${ikon("plus")}${ç("Tezgâha koy")}</button>
            ${sahibi ? `<button class="dugme ikincil kucuk-d" type="button" data-tezgah="al">${ikon("minus")}${ç("Tezgâhtan al")}</button>` : ""}</div></div></section>`;
    }
    function fiyatHtml(v) {
      return `<section class="kart" id="mekanim-fiyat"><div class="kart-bas"><div><p class="ust-yazi">${ç("Menü")}</p><h2 class="b2">${ç("Fiyatlar")}</h2></div><span class="ik-kutu">${ikon("receipt-text")}</span></div>
        <form class="form" data-mekanim-fiyat novalidate>
          <div class="mekanim-fiyatlar">${(v.menu ?? []).map((x) => `<label class="alan mekanim-fiyat"><span>${ikon(MENU_KALEM[x.item]?.[1] ?? "receipt-text")} ${esc(menuAdi(x.item))} <small>${esc(MENU_TUR[x.cat] ?? "")}</small></span>
            <input name="${esc(x.item)}" inputmode="decimal" value="${esc(krediGirdi(x.price))}" autocomplete="off" aria-label="${esc(ç("{kalem} fiyatı (kredi)", { kalem: menuAdi(x.item) }))}">
            <small>${esc(ç("{a}–{b} kredi", { a: kr(x.min), b: kr(x.max) }))}</small></label>`).join("")}</div>
          <p class="kucuk">${ç("Bandın tabanına yakın fiyat daha çok simülasyon müşterisi getirir (×1,2), tavanında ×0,6. Satış pazar satışı gibi vergilenir; kalan kasaya geçer.")}</p>
          <button class="dugme kucuk-d" type="submit">${ikon("check")}${ç("Fiyatları kaydet")}</button><div class="form-mesaj"></div></form></section>`;
    }
    function ayarHtml(v) {
      const Rr = R(), kulup = v.kind === "kulup", otel = v.kind === "otel";
      const kira = Rr.club?.concert?.rentCr ?? {}, gece = Rr.hotel?.nightCr ?? {};
      return `<section class="kart" id="mekanim-ayar"><div class="kart-bas"><div><p class="ust-yazi">${ç("Ayarlar")}</p><h2 class="b2">${ç("Kapı ve ayarlar")}</h2></div><span class="ik-kutu">${ikon("door-open")}</span></div>
        <form class="form" data-mekanim-ayar novalidate>
          <fieldset class="alan"><legend>${ç("Kim girer")}</legend><div class="radyo-liste">${["open", "friends", "closed"].map((k) => `<label class="radyo"><input type="radio" name="kapi" value="${k}" ${v.door === k ? "checked" : ""}>
            <span><b>${esc(MEKAN_KAPI[k])}</b><span class="kucuk">${esc(MEKAN_KAPI_ACIKLAMA[k])}</span></span></label>`).join("")}</div></fieldset>
          ${kulup ? `<label class="alan"><span>${ç("Kulübün tarzı")}</span><select name="tarz">${(Rr.club?.styles ?? ["pop", "rock", "caz", "elektronik"]).map((s) => `<option value="${esc(s)}" ${v.style === s ? "selected" : ""}>${esc(MUZIK_TUR[s] ?? s)}</option>`).join("")}</select>
              <small>${esc(ç("Bu türdeki gruplarla uyum %{a}, ötekilerle %{b}.", { a: Math.round(Number(Rr.club?.concert?.fitOwnPpm ?? 1e6) / 1e4), b: Math.round(Number(Rr.club?.concert?.fitOtherPpm ?? 7e5) / 1e4) }))}</small></label>
            <label class="alan"><span>${ç("Konser kirası (kredi)")}</span><input name="kira" inputmode="decimal" value="${esc(krediGirdi(v.concert_rent_cr ?? kira.default ?? 0))}" autocomplete="off">
              <small>${esc(ç("{a}–{b} kredi. Kulübün şehrin konser mekânları arasında görünür ({n} kişi); kira kasana geçer.", { a: kr(kira.min ?? 0), b: kr(kira.max ?? 0), n: sayi(Rr.club?.concert?.capacity ?? 120) }))}</small></label>` : ""}
          ${otel ? `<label class="alan"><span>${ç("Gecelik oda fiyatı (kredi)")}</span><input name="gece" inputmode="decimal" value="${esc(krediGirdi(v.night_price_cr ?? gece.default ?? 0))}" autocomplete="off">
              <small>${esc(ç("{a}–{b} kredi. Yeni konaklamalar bu fiyatla başlar.", { a: kr(gece.min ?? 0), b: kr(gece.max ?? 0) }))}</small></label>` : ""}
          <button class="dugme kucuk-d" type="submit">${ikon("check")}${ç("Kaydet")}</button><div class="form-mesaj"></div></form></section>`;
    }
    function odalarHtml(m) {
      const H = R().hotel ?? {}, l = m.stays ?? [];
      return `<section class="kart" id="mekanim-odalar"><div class="kart-bas"><div><p class="ust-yazi">${ç("Otel")}</p><h2 class="b2">${esc(ç("{n} / {m} oda dolu", { n: l.length, m: Number(H.rooms ?? 4) }))}</h2></div><span class="ik-kutu">${ikon("bed")}</span></div>
        ${l.length ? `<div class="liste">${l.map((s) => `<div class="liste-satir"><span class="liste-ikon lacivert">${ikon("bed")}</span><div><span class="tur">${esc(ç("{n}. oda", { n: Number(s.room) }))}</span><b>${esc(s.guest ?? "")}</b>
            <div class="alt">${esc(ç("{a} / {b} gece ödendi · çıkış {zaman}", { a: Number(s.nights_paid), b: Number(s.nights), zaman: saatYaz(s.ends_at) }))}</div></div><span></span></div>`).join("")}</div>`
          : `<p class="bos">${ç("Şu an konaklayan yok.")}</p>`}
        <p class="kucuk">${ç("Konuk 1–7 gece kiralar; her gecenin bedeli (vergiden sonra) gecenin başında kasaya geçer. Sahibi ve yöneticiler kendi otelinde oda tutmaz.")}</p></section>`;
    }
    function etkinlikHtml(m) {
      const E = R().events ?? {};
      const yerel = (t) => { const z = new Date(t); z.setMinutes(z.getMinutes() - z.getTimezoneOffset()); return z.toISOString().slice(0, 16); };
      const en = Date.now() + (Number(E.leadMin ?? 30) + 1) * 60000, son = Date.now() + Number(E.horizonDays ?? 7) * 86400e3 - 60000;
      const oneri = new Date(Math.max(en, Date.now() + 2 * 3600e3));
      oneri.setMinutes(0, 0, 0);
      if (oneri.getTime() < en) oneri.setTime(oneri.getTime() + 3600e3);
      const l = m.events ?? [];
      return `<section class="kart" id="mekanim-etkinlik"><div class="kart-bas"><div><p class="ust-yazi">${ç("Etkinlikler")}</p><h2 class="b2">${ç("Mekânın etkinlikleri")}</h2></div><span class="ik-kutu">${ikon("calendar")}</span></div>
        ${l.length ? `<div class="liste">${l.map((e) => `<div class="liste-satir" data-etkinlik="${esc(e.event_id)}"><span class="liste-ikon ${e.status === "live" ? "mercan" : "altin"}">${ikon(MEKAN_ETKINLIK_IK[e.kind] ?? "calendar")}</span>
            <div><span class="tur">${esc(saatYaz(e.starts_at))}</span><b>${esc(MEKAN_ETKINLIK[e.kind] ?? e.kind)}</b><div class="alt">${esc([MEKAN_ETKINLIK_DURUM[e.status] ?? e.status,
              Number(e.interested) ? ç("{n} kişi ilgileniyor", { n: sayi(e.interested) }) : null, e.status === "ended" ? ç("{n} kişi katıldı", { n: sayi(e.attendees ?? 0) }) : null].filter(Boolean).join(" · "))}</div></div>
            ${e.status === "scheduled" || e.status === "live" ? `<button class="dugme sade kucuk-d" data-etkinlik-iptal="${esc(e.event_id)}">${ikon("x")}${ç("İptal et")}</button>` : "<span></span>"}</div>`).join("")}</div>`
          : `<p class="bos">${ç("Henüz etkinlik yok.")}</p>`}
        ${v.status === "open" ? `<form class="form" data-mekanim-etkinlik novalidate style="margin-top:12px">
          <label class="alan"><span>${ç("Tür")}</span><select name="tur">${(E.kinds ?? Object.keys(MEKAN_ETKINLIK)).map((k) => `<option value="${esc(k)}">${esc(MEKAN_ETKINLIK[k] ?? k)}</option>`).join("")}</select></label>
          <label class="alan"><span>${ç("Başlangıç")}</span><input name="zaman" type="datetime-local" required min="${yerel(en)}" max="${yerel(son)}" value="${yerel(oneri)}"></label>
          <fieldset class="alan"><legend>${ç("Süre")}</legend><div class="radyo-liste birlik-yatay">${(E.hours ?? [1, 2, 3]).map((h, i) => `<label class="radyo"><input type="radio" name="saat" value="${Number(h)}" ${i === 1 || (E.hours ?? []).length === 1 ? "checked" : ""}><span><b>${esc(ç("{n} saat", { n: Number(h) }))}</b></span></label>`).join("")}</div></fieldset>
          <p class="kucuk">${esc(ç("En erken {d} dakika, en geç {g} gün sonra; mekânda günde bir etkinlik, en çok {n} yaklaşan. İlgilenenlere başlarken haber gider; etkinlik günü daha çok müşteri gelir.",
            { d: Number(E.leadMin ?? 30), g: Number(E.horizonDays ?? 7), n: Number(E.upcomingMax ?? 5) }))}</p>
          <button class="dugme kucuk-d" type="submit">${ikon("calendar")}${ç("Etkinlik aç")}</button><div class="form-mesaj"></div></form>` : ""}</section>`;
    }
    function yoneticiHtml(m, sahibi) {
      const l = m.managers ?? [], enCok = Number(m.managers_max ?? 2);
      const adaylar = (ark ?? []).filter((x) => !l.some((y) => y.character_id === x.character_id));
      return `<section class="kart" id="mekanim-yonetici"><div class="kart-bas"><div><p class="ust-yazi">${ç("Yöneticiler")}</p><h2 class="b2">${esc(ç("{n} / {m} yönetici", { n: l.length, m: enCok }))}</h2></div><span class="ik-kutu">${ikon("key-round")}</span></div>
        ${l.length ? `<div class="koltuk-liste">${l.map((x) => `<div class="koltuk">${avatarKutu(x.name, x.character_id)}<div><button class="baglanti" data-profil="${esc(x.character_id)}"><b>${esc(x.name)}</b></button>
            <div class="kucuk">${esc(beriYaz(x.added_at))}</div></div>${sahibi ? `<button class="dugme sade kucuk-d" data-yonetici-cikar="${esc(x.character_id)}">${ç("Görevden al")}</button>` : "<span></span>"}</div>`).join("")}</div>`
          : `<p class="bos">${ç("Yöneticin yok.")}</p>`}
        ${sahibi && l.length < enCok ? (adaylar.length ? `<div class="form mekanim-form" data-mekanim-yonetici style="margin-top:10px"><label class="alan"><span>${ç("Arkadaşlarından ekle")}</span>
            <select name="kisi">${adaylar.map((x) => `<option value="${esc(x.character_id)}">${esc(x.name)}</option>`).join("")}</select></label>
            <button class="dugme kucuk-d" type="button" data-yonetici-ekle>${ikon("user-round-plus")}${ç("Yönetici yap")}</button></div>`
          : `<p class="kucuk">${ç("Yönetici yalnız arkadaşlarından olur; önce arkadaş ekle.")}</p>`) : ""}
        <p class="kucuk">${ç("Yönetici fiyatları, dekoru, tezgâhı ve etkinlikleri düzenler, içeridekileri çıkarabilir; kasaya dokunmaz, mekânı kapatmaz. İçeride bulunması o günü işletilmiş sayar.")}</p></section>`;
    }
    function adHtml(v) {
      const N = R().name ?? { min: 3, max: 40, renameDays: 30 };
      const hazir = v.name_reset || !v.can_rename_at || Date.parse(v.can_rename_at) <= Date.now();
      return `<section class="kart" id="mekanim-adi"><div class="kart-bas"><div><p class="ust-yazi">${ç("Ad")}</p><h2 class="b2">${esc(v.name)}</h2></div><span class="ik-kutu">${ikon("id-card")}</span></div>
        ${hazir ? `<form class="form" data-mekanim-ad novalidate><label class="alan"><span>${ç("Yeni ad")}</span><input name="ad" required minlength="${Number(N.min)}" maxlength="${Number(N.max)}" autocomplete="off" value="${esc(v.name_reset ? "" : v.name)}"></label>
            <button class="dugme kucuk-d" type="submit">${ikon("check")}${ç("Adı değiştir")}</button><div class="form-mesaj"></div></form>
            <p class="kucuk">${esc(ç("Ad {g} günde bir değiştirilir.", { g: Number(N.renameDays ?? 30) }))}</p>`
          : `<p class="kucuk">${esc(ç("Ad {zaman} tarihinden sonra değiştirilebilir ({g} günde bir).", { zaman: saatYaz(v.can_rename_at), g: Number(N.renameDays ?? 30) }))}</p>`}</section>`;
    }
    const kapatHtml = () => `<section class="kart mekanim-tehlike" id="mekanim-kapat-kart"><p class="ust-yazi">${ç("Mekânı kapat")}</p>
      <p class="kucuk">${ç("Kapatınca ruhsat geri verilmez. Kasadaki kredi ve tezgâhtaki erzak sana döner; konukların kalan geceleri kendilerine döner, bekleyen konser ve etkinlikler iptal olur.")}</p>
      <button class="dugme mercan kucuk-d" id="mekanim-kapat">${ikon("x")}${ç("Mekânı kapat")}</button></section>`;

    // ---------- İşlemler ----------
    const kartAl = (y) => { if (y?.venue_id) v = { ...v, ...y }; };
    function bagla() {
      meydanaDonBagla(kap);
      for (const b of $$("[data-mekan-git]", kap)) b.onclick = () => MekanYolu.git(b.dataset.mekanGit);
      $("#mekanim-dekor", kap)?.addEventListener("click", () => MekanYolu.git(v.venue_id, "main", { duzenle: true }));
      $("#mekanim-liste", kap)?.addEventListener("click", () => Kabuk.git("sehir/mekanlar"));
      for (const b of $$("[data-mekanim-sec]", kap)) b.onclick = () => { id = b.dataset.mekanimSec; v = (r.mine ?? []).find((x) => x.venue_id === id) ?? v; ciz(); };
      for (const b of $$("[data-profil]", kap)) b.onclick = () => profilAc(b.dataset.profil, tazele);
      $("#mekanim-ac-yeniden", kap)?.addEventListener("click", (e) => mekanIsle(e.currentTarget, async () => {
        kartAl(await MekanYolu.yenidenAc(v.venue_id));
        tost(ç("Borç ödendi; mekân yeniden açık."), "door-open");
        await tazele();
      }));
      // Kasa: artı koymak, eksi çekmek
      const kasa = $("[data-mekanim-kasa]", kap);
      for (const b of $$("[data-kasa]", kasa ?? kap)) b.onclick = () => mekanIsle(b, async () => {
        const t = krediAlt($("input[name=tutar]", kasa)?.value);
        if (!Number.isFinite(t) || t <= 0) { tost(ç("Tutarı kredi olarak yaz (ör. 25 ya da 12,50)."), "circle-alert"); return; }
        kartAl(await MekanYolu.kasa(v.venue_id, b.dataset.kasa === "koy" ? t : -t));
        tost(b.dataset.kasa === "koy" ? ç("Kasaya {kr} kredi koydun.", { kr: kr(t) }) : ç("Kasadan {kr} kredi çektin.", { kr: kr(t) }), "wallet");
        Durum.ozet().catch(() => {});
        ciz();
      });
      // Tezgâh: çantadan erzak koymak ya da (sahibi) almak
      const tz = $("[data-mekanim-tezgah]", kap);
      for (const b of $$("[data-tezgah]", tz ?? kap)) b.onclick = () => mekanIsle(b, async () => {
        const n = adetAl($("input[name=adet]", tz)?.value);
        if (!Number.isFinite(n) || n <= 0) { tost(ç("Adedi tam sayı olarak yaz."), "circle-alert"); return; }
        kartAl(await MekanYolu.tezgah(v.venue_id, b.dataset.tezgah === "koy" ? n : -n));
        tost(b.dataset.tezgah === "koy" ? ç("Tezgâha {n} erzak koydun.", { n }) : ç("Tezgâhtan {n} erzak aldın.", { n }), "croissant");
        Durum.ozet().catch(() => {});
        ciz();
      });
      // Fiyatlar: yalnız değişenler gönderilir; bant önceden denetlenir
      const ff = $("[data-mekanim-fiyat]", kap);
      ff?.addEventListener("submit", async (e) => {
        e.preventDefault();
        const yaz = (m) => { $(".form-mesaj", ff).innerHTML = m ? `<div class="hata-kutusu" style="margin-top:10px">${ikon("circle-alert")}<span>${esc(m)}</span></div>` : ""; };
        const yeni = {};
        for (const x of v.menu ?? []) {
          const f = krediAlt($(`input[name="${x.item}"]`, ff)?.value);
          if (!Number.isFinite(f)) { yaz(ç("{kalem}: fiyatı kredi olarak yaz (ör. 1 ya da 1,50).", { kalem: menuAdi(x.item) })); formSerbest(ff); return; }
          if (f < Number(x.min) || f > Number(x.max)) { yaz(ç("{kalem}: fiyat {a}–{b} kredi arasında olur.", { kalem: menuAdi(x.item), a: kr(x.min), b: kr(x.max) })); formSerbest(ff); return; }
          if (f !== Number(x.price)) yeni[x.item] = f;
        }
        if (!Object.keys(yeni).length) { yaz(""); tost(ç("Fiyatlarda değişiklik yok."), "receipt-text"); formSerbest(ff); return; }
        const d = $("button[type=submit]", ff);
        d.disabled = true;
        try { kartAl(await MekanYolu.fiyatlar(v.venue_id, yeni)); tost(ç("Fiyatlar kaydedildi."), "receipt-text"); ciz(); }
        catch (err) { yaz(hataMetni(err)); d.disabled = false; } finally { formSerbest(ff); }
      });
      // Kapı, tarz, kira, gecelik fiyat
      const fa = $("[data-mekanim-ayar]", kap);
      fa?.addEventListener("submit", async (e) => {
        e.preventDefault();
        const yaz = (m) => { $(".form-mesaj", fa).innerHTML = m ? `<div class="hata-kutusu" style="margin-top:10px">${ikon("circle-alert")}<span>${esc(m)}</span></div>` : ""; };
        const fd = new FormData(fa), Rr = R(), a = { door: String(fd.get("kapi") ?? v.door) };
        if (v.kind === "kulup") {
          a.style = String(fd.get("tarz") ?? v.style);
          const k = krediAlt(fd.get("kira")), b = Rr.club?.concert?.rentCr ?? {};
          if (!Number.isFinite(k) || k < Number(b.min ?? 0) || k > Number(b.max ?? Infinity)) { yaz(ç("Konser kirası {a}–{b} kredi arasında olur.", { a: kr(b.min ?? 0), b: kr(b.max ?? 0) })); formSerbest(fa); return; }
          a.rent = k;
        }
        if (v.kind === "otel") {
          const g = krediAlt(fd.get("gece")), b = Rr.hotel?.nightCr ?? {};
          if (!Number.isFinite(g) || g < Number(b.min ?? 0) || g > Number(b.max ?? Infinity)) { yaz(ç("Gecelik fiyat {a}–{b} kredi arasında olur.", { a: kr(b.min ?? 0), b: kr(b.max ?? 0) })); formSerbest(fa); return; }
          a.night = g;
        }
        const d = $("button[type=submit]", fa);
        d.disabled = true;
        try { kartAl(await MekanYolu.ayar(v.venue_id, a)); tost(ç("Ayarlar kaydedildi."), "door-open"); ciz(); }
        catch (err) { yaz(hataMetni(err)); d.disabled = false; } finally { formSerbest(fa); }
      });
      // Etkinlik
      for (const b of $$("[data-etkinlik-iptal]", kap)) b.onclick = () => {
        const e = (v.manage?.events ?? []).find((x) => x.event_id === b.dataset.etkinlikIptal);
        pencere({ ust: ç("Etkinlik"), baslik: ç("{tur} iptal edilsin mi?", { tur: MEKAN_ETKINLIK[e?.kind] ?? "" }),
          govde: `<p class="aciklama">${ç("İlgilenenlere iptal haberi gider.")}</p>`,
          dugmeler: [{ ad: ç("Vazgeç") }, { ad: ç("İptal et"), sinif: "mercan", ikon: "x", is: () => mekanIsle(null, async () => {
            await MekanYolu.etkinlikIptal(b.dataset.etkinlikIptal);
            tost(ç("Etkinlik iptal edildi."), "x");
            await tazele();
          }) }] });
      };
      const fe = $("[data-mekanim-etkinlik]", kap);
      fe?.addEventListener("submit", async (e) => {
        e.preventDefault();
        const yaz = (m) => { $(".form-mesaj", fe).innerHTML = m ? `<div class="hata-kutusu" style="margin-top:10px">${ikon("circle-alert")}<span>${esc(m)}</span></div>` : ""; };
        const fd = new FormData(fe), z = new Date(String(fd.get("zaman") ?? ""));
        if (Number.isNaN(z.getTime())) { yaz(ç("Başlangıç zamanını seç.")); formSerbest(fe); return; }
        const d = $("button[type=submit]", fe);
        d.disabled = true;
        try {
          await MekanYolu.etkinlikAc(v.venue_id, String(fd.get("tur")), z.toISOString(), Number(fd.get("saat")));
          tost(ç("Etkinlik açıldı: {tur}, {zaman}.", { tur: MEKAN_ETKINLIK[String(fd.get("tur"))] ?? "", zaman: saatYaz(z.toISOString()) }), "calendar");
          await tazele();
        } catch (err) { yaz(hataMetni(err)); d.disabled = false; } finally { formSerbest(fe); }
      });
      // Yöneticiler
      const fy = $("[data-mekanim-yonetici]", kap);
      $("[data-yonetici-ekle]", fy ?? kap)?.addEventListener("click", (e) => mekanIsle(e.currentTarget, async () => {
        const k = $("select[name=kisi]", fy)?.value;
        if (!k) return;
        kartAl(await MekanYolu.yonetici(v.venue_id, k, true));
        tost(ç("Yönetici eklendi."), "key-round");
        ciz();
      }));
      for (const b of $$("[data-yonetici-cikar]", kap)) b.onclick = () => mekanIsle(b, async () => {
        kartAl(await MekanYolu.yonetici(v.venue_id, b.dataset.yoneticiCikar, false));
        tost(ç("Yöneticilikten çıkarıldı."), "key-round");
        ciz();
      });
      // Ad
      const fd2 = $("[data-mekanim-ad]", kap);
      fd2?.addEventListener("submit", async (e) => {
        e.preventDefault();
        const N = R().name ?? { min: 3, max: 40 };
        const yaz = (m) => { $(".form-mesaj", fd2).innerHTML = m ? `<div class="hata-kutusu" style="margin-top:10px">${ikon("circle-alert")}<span>${esc(m)}</span></div>` : ""; };
        const ad = String(new FormData(fd2).get("ad") ?? "").trim().replace(/\s+/g, " ");
        if (ad.length < Number(N.min) || ad.length > Number(N.max)) { yaz(ç("Mekânın adı {a}–{b} harf olmalı.", { a: Number(N.min), b: Number(N.max) })); formSerbest(fd2); return; }
        const d = $("button[type=submit]", fd2);
        d.disabled = true;
        try { kartAl(await MekanYolu.adDegistir(v.venue_id, ad)); tost(ç("Mekânın adı değişti: {ad}.", { ad }), "id-card"); await tazele(); }
        catch (err) { yaz(hataMetni(err)); d.disabled = false; } finally { formSerbest(fd2); }
      });
      // Kapatmak (yalnız sahibi; onaylı)
      $("#mekanim-kapat", kap)?.addEventListener("click", () => {
        pencere({ ust: ç("Mekânı kapat"), baslik: v.name,
          govde: `<p class="aciklama">${ç("Mekân kapanır ve geri açılmaz; ruhsat geri verilmez. Kasadaki kredi ve tezgâhtaki erzak sana döner.")}</p>`,
          dugmeler: [{ ad: ç("Vazgeç") }, { ad: ç("Kapat"), sinif: "mercan", ikon: "x", is: () => mekanIsle(null, async () => {
            await MekanYolu.kapat(v.venue_id);
            tost(ç("Mekânın kapandı: {ad}.", { ad: v.name }), "x");
            Durum.ozet().catch(() => {});
            try { sessionStorage.removeItem("civora.mekanim"); } catch { /* yok */ }
            Kabuk.git("sehir/mekanlar");
          }) }] });
      });
    }
    // İşlemden sonra (düğme) her zaman yeniden çizer; arka planda (canlı olay, dakikalık) yükleme sürerken yazılmaya
    // başlandıysa çizmez, sonraki çizime bırakır
    const tazele = tazeleyici(async () => { await yukle(); ciz(); });
    const arkaTazele = tazeleyici(async () => { await yukle(); if (kirli) { bekleyen = true; return; } ciz(); });
    await yukle();
    ciz();
    const b1 = Durum.dinle("olay", ({ olay }) => { if (/^venue\./.test(olay)) tazeleIste(); });
    const saat = setInterval(() => { if (!document.hidden && !$(":focus", kap)) tazeleIste(); }, 60000);
    return () => { b1(); clearInterval(saat); kap.removeEventListener("input", degisti); kap.removeEventListener("change", degisti); };
  },
});

// ===== 98zh_mekan_ic.js =====
// ---------- Şehrim → Mekân: mekânın içi (D-141) ----------
// İçerisi ev ziyaretindeki kartın mekân biçimidir (MekanPaneli): 3B mekân (44_oda3b.js; d.mekan) ya da 2B plan, içeridekiler
// kendi figürleriyle (adını gizleyen "Biri"), eylem çubuğu (el salla, dans, otur, alkış, gül), menü (kendine sipariş,
// ısmarlamak, hediye), fıkra (önerilen üçten biri) ve mekânın akışı ("Güldüm"), etkinlik bandı. Boş kareye dokununca
// yürünür, masaya, tabureye ya da koltuğa dokununca oturulur; birine dokununca kartı açılır (el salla, ısmarla, hediye ver,
// profil, mesaj; yönetim için "Mekândan çıkar"). Sahibi ve yöneticisi dekoru burada düzenler (sunucunun denetiminin aynısı
// önceden; venue_layout_check) ve yönetim sayfasına geçer (98zg_mekan.js). Otelde konuğun odası aynı kartla (yatak,
// gardırop; düzen sabit). Yerin, kalp atışı ve canlı olaylar 98zf_mekan_yol.js'te (MekanZiyareti).

// Dekorun denetimi: sunucudaki venue_layout_check'in aynısı (ilk hata kodu ya da null). m: kartın "manage"i.
const MEKAN_DUZEN_HATA = {
  VENUE_TOO_MANY: ç("Eşya sınırına ulaştın."), VENUE_ITEM_UNKNOWN: ç("Bu eşya bu mekâna konmaz."),
  VENUE_FIXTURE_LIMIT: ç("Bu parçadan daha fazla konmaz."), VENUE_ITEM_NOT_OWNED: ç("Bu eşyadan yeterince yok; önce mobilyayla kur."),
  VENUE_OUT_OF_BOUNDS: ç("Oraya sığmıyor."), VENUE_OVERLAP: ç("Orada başka bir eşya var."),
};
function mekanDenetle(m, items) {
  if (items.length > Number(m.max_items)) return "VENUE_TOO_MANY";
  const k = new Map((m.catalog ?? []).map((c) => [c.id, c]));
  const kutu = [], sayac = new Map();
  for (const p of items) {
    const c = k.get(p.i);
    if (!c) return "VENUE_ITEM_UNKNOWN";
    const n = (sayac.get(c.id) ?? 0) + 1;
    sayac.set(c.id, n);
    if (c.fixture && n > Number(c.max ?? 0)) return "VENUE_FIXTURE_LIMIT";
    if (!c.fixture && n > Number(m.free?.[c.id] ?? 0) + Number(m.owned?.[c.id] ?? 0)) return "VENUE_ITEM_NOT_OWNED";
    const iz = odaIzi(c, p);
    if (p.x < 0 || p.z < 0 || p.x + iz.w > m.grid.w || p.z + iz.d > m.grid.d) return "VENUE_OUT_OF_BOUNDS";
    kutu.push([p.x, p.z, p.x + iz.w, p.z + iz.d, !!c.rug]);
  }
  for (let b = 1; b < kutu.length; b++) for (let a = 0; a < b; a++) {
    const p = kutu[a], q = kutu[b];
    if (p[4] === q[4] && p[0] < q[2] && q[0] < p[2] && p[1] < q[3] && q[1] < p[3]) return "VENUE_OVERLAP";
  }
  return null;
}
// Çekicilik: süs eşyalarının bedelleri toplamı, türün tavanına kadar (venueAmbiance)
function mekanCekicilik(m, items) {
  const k = new Map((m.catalog ?? []).map((c) => [c.id, c]));
  const t = items.reduce((s, p) => { const c = k.get(p.i); return s + (c && !c.fixture ? Number(c.cost ?? 0) : 0); }, 0);
  return Math.min(Number(m.decor_max ?? 0), t);
}
const saatKisa = (iso) => new Date(iso).toLocaleTimeString(DIL.yerel, { hour: "2-digit", minute: "2-digit" });

// Mekândan düşmenin ya da girilememenin yazısı (Mekânlar ekranı bir kez gösterir)
let mekanBildiri = null;
const MEKAN_NEDEN = {
  cikarildi: ç("Mekânın yönetimi seni çıkardı; bir süre bu mekâna giremezsin."),
  kapi: ç("Mekânın kapısı kapandı; dışarı çıktın."),
  yolda: ç("Şehirden ayrıldın; mekândan çıktın."),
  kapandi: ç("Mekân kapandı."),
  aski: ç("Mekân askıya alındı; dışarı çıktın."),
  dolu: ç("Mekân dolu; biraz sonra yeniden dene."),
  oda: ç("Bu odaya şu an girilmiyor: konaklama bitti ya da oda yalnız konuğun arkadaşlarına açık."),
  giris: ç("Mekândan çıktın."),
};

const MekanPaneli = (() => {
  // secenek: { sehir (pencereden görünen şehrin seviyesi), duzenle (dekoru düzenleyerek aç), cik (mekândan çıkmak), bitti
  //   (yer düşünce: neden, hata), yonet (yönetim sayfası), oda (n: otel odasına çık), lobi (otelin salonuna in), kalis (otelde
  //   bu otelde kaldığın oda; yoksa null) }
  function ac(yer, zy, secenek = {}) {
    let zs = zy.s, mod = Gorunum.uc() ? "3b" : "2b", hata3b = false, kapandi = false;
    let duzen = false, items = [], secili = -1, uyari = "", gonderiliyor = false;
    const balonlar2b = new Map();   // içerideki kimlik → { metin, bitis }
    const V = () => zs?.venue ?? {};
    const yonetim = () => V().manage ?? null;
    const staff = () => !!V().role;
    const salon = () => zs?.space === "main";
    const tur3b = () => (salon() ? (V().system ? "kahvehane" : V().kind) : "oda");
    const kisiler = () => zs?.people ?? [];
    const ben = () => kisiler().find((k) => k.me) ?? null;
    const katalog = () => (duzen ? yonetim()?.catalog ?? [] : zs?.catalog ?? []);
    const oturaklar = () => (zs?.catalog ?? []).filter((c) => Number(c.seats) > 0).map((c) => c.id);
    const VR = () => Durum.v.kurallar?.data?.venue ?? {};
    const canliEtkinlik = () => (V().event?.status === "live" ? V().event : null);

    function ciz() {
      if (!zs) return;
      const v = V();
      yer.innerHTML = `<section class="kart oda-kart mekan-kart" data-mekan="${esc(v.venue_id)}" data-tur="${esc(tur3b())}" data-yer="${esc(zs.space)}"${staff() ? ` data-rol="${esc(v.role)}"` : ""}>
        <div class="kart-bas"><div><p class="ust-yazi" id="mekan-ust">${esc(ustYazi())}</p><h2 class="b2" id="mekan-baslik">${esc(baslik())}</h2></div>
          <div class="kart-bas-dugmeler">${Gorunum.webglVar() ? `<button class="dugme sade kucuk-d" id="mekan-mod" aria-pressed="${mod === "2b"}" title="${mod === "3b" ? ç("Hafif görünüme (2B) geç") : ç("3B görünüme geç")}">${ikon("layers")}${mod === "3b" ? ç("2B") : ç("3B")}</button>` : ""}</div></div>
        <div id="mekan-etkinlik">${etkinlikHtml()}</div>
        <div class="oda-sahne sahne3b mekan-sahne${duzen ? " oda-duzende" : ""}" id="mekan-sahne" data-mod="${mod}" data-tur="${esc(tur3b())}">
          ${mod === "3b" ? `<div class="yukleniyor${oda3bOrnek ? " bitti" : ""}" id="mekan-yukleniyor"><div class="yukleniyor-ic"><img src="img/amblem.png" alt=""><span>${ç("Mekân hazırlanıyor…")}</span></div></div>` : ""}
          <div class="oda-2b" id="mekan-2b"${mod === "3b" ? " hidden" : ""}></div>
          <div class="meydan-etiketler oda-etiketler" id="mekan-etiketler"${mod === "3b" ? "" : " hidden"}></div>
        </div>
        ${duzen ? araclarHtml() : `<div class="mekan-ic" id="mekan-ic">${icHtml()}</div>`}
      </section>`;
      bagla();
      if (mod === "2b") plan2b();
      sahneBagla();
    }
    const ustYazi = () => {
      const v = V();
      if (!salon()) return [ç("Otel odası"), v.name ?? "", bolgeAdi(v.region_id)].filter(Boolean).join(" · ");
      return [v.system ? ç("Şehrin kahvehanesi") : MEKAN_TUR[v.kind] ?? v.kind, bolgeAdi(v.region_id),
        !v.system && v.owner && v.role !== "owner" ? ç("sahibi {ad}", { ad: v.owner }) : null,
        v.status === "suspended" ? MEKAN_DURUM.suspended : null].filter(Boolean).join(" · ");
    };
    const baslik = () => (duzen ? ç("Dekoru düzenliyorsun") : salon() ? mekanAdi(V())
      : zs.room_mine ? ç("Odan ({n}. oda)", { n: Number(String(zs.space).slice(5)) }) : ç("{ad} adlı konuğun odası", { ad: zs.room_guest ?? "" }));

    // ---------- Etkinlik bandı ----------
    function etkinlikHtml() {
      const e = salon() ? V().event : null;
      if (!e) return "";
      const canli = e.status === "live";
      const ilgi = Number(e.interested ?? 0);
      return `<div class="mekan-etkinlik${canli ? " canli" : ""}" data-etkinlik="${esc(e.status)}">${ikon(MEKAN_ETKINLIK_IK[e.kind] ?? "calendar")}
        <span><b>${esc(MEKAN_ETKINLIK[e.kind] ?? e.kind)}</b> · ${canli ? esc(ç("şimdi sürüyor; {saat} bitiyor", { saat: saatKisa(e.ends_at) }))
          : esc(ç("{zaman} başlıyor", { zaman: saatYaz(e.starts_at) }))}${ilgi ? " · " + esc(ç("{n} kişi ilgileniyor", { n: sayi(ilgi) })) : ""}</span>
        ${canli || staff() ? "" : `<button class="dugme ${e.mine ? "" : "ikincil"} kucuk-d" data-mekan-ilgi="${esc(e.event_id)}" aria-pressed="${!!e.mine}">${ikon("bell")}${e.mine ? ç("İlgileniyorsun") : ç("İlgileniyorum")}</button>`}</div>`;
    }
    function etkinlikYaz() {
      const el = $("#mekan-etkinlik", yer);
      if (!el) return;
      el.innerHTML = etkinlikHtml();
      for (const b of $$("[data-mekan-ilgi]", el)) b.onclick = () => ilgilen(b);
    }
    async function ilgilen(b) {
      const e = V().event;
      if (!e || b.disabled) return;
      b.disabled = true;
      try {
        const r = await MekanYolu.ilgi(e.event_id, !e.mine);
        Object.assign(e, { mine: !!r.mine, interested: Number(r.interested ?? 0) });
        tost(r.mine ? ç("Etkinlik başlarken haber vereceğiz.") : ç("Artık haber vermeyeceğiz."), "bell");
      } catch (err) { tost(hataMetni(err), "circle-alert"); }
      if (!kapandi) etkinlikYaz();
    }

    // ---------- İçeridekiler, eylemler, menü, fıkra, akış ----------
    function icHtml() {
      const v = V(), hepsi = kisiler(), digerleri = hepsi.filter((k) => !k.me);
      const adli = digerleri.filter((k) => !k.hidden).sort((a, b) => (b.host - a.host) || (b.staff - a.staff) || (b.friend - a.friend)
        || String(a.name).localeCompare(String(b.name), DIL.yerel));
      const gizli = digerleri.filter((k) => k.hidden);
      const kap = Number(zs.capacity ?? 0);
      const metin = digerleri.length ? ç("İçeride sen ve {n} kişi daha varsınız (en çok {m} kişi).", { n: sayi(digerleri.length), m: sayi(kap) })
        : salon() ? ç("İçeride şimdilik yalnızsın; gelenler figürleriyle görünür.") : ç("Odada şimdilik yalnızsın; arkadaşların gelince figürleriyle görünür.");
      const musteri = salon() && !v.system && Number(zs.sim_visitors ?? 0) > 0
        ? ç("Dün {n} müşteri geldi; boş masalardaki kimliksiz figürler onlar.", { n: sayi(zs.sim_visitors) }) : "";
      const cipler = [...adli.map((k) => `<button class="cip meydan-kisi-cip${k.friend ? " arkadas" : ""}" data-mekan-kisi="${esc(k.p)}">${k.host ? ikon(salon() ? "crown" : "bed")
          : k.staff ? ikon("key-round") : k.friend ? ikon("heart") : ""}${esc(k.name)}</button>`),
        ...gizli.map((k) => `<button class="cip meydan-kisi-cip" data-mekan-kisi="${esc(k.p)}">${ikon("eye-off")}${esc(ç("Biri"))}</button>`)];
      const eylemler = `<div class="meydan-eylemler" role="group" aria-label="${ç("Hareketler")}">${MEKAN_EYLEM.map(([e, ad, ik]) =>
        `<button class="dugme ikincil kucuk-d" data-mekan-eylem="${e}">${ikon(ik)}${esc(ad)}</button>`).join("")}</div>
        <p class="kucuk">${salon() ? ç("Boş bir kareye dokununca oraya yürürsün; masaya, tabureye ya da koltuğa dokununca oturursun.")
          : ç("Boş bir kareye dokununca yürürsün; sandalyeye dokununca oturursun.")}</p>`;
      const benGizli = !!ben()?.hides_name;
      return `<div class="mekan-blok"><p class="ust-yazi">${salon() ? ç("İçeridekiler") : ç("Odadakiler")}</p>
          <p class="kucuk" id="mekan-kisi-yazi" data-kisi="${hepsi.length}">${esc(metin)}${musteri ? " " + esc(musteri) : ""}</p>
          ${cipler.length ? `<div class="meydan-kisiler" id="mekan-kisiler">${cipler.join("")}</div>` : ""}
          ${eylemler}</div>
        ${v.status === "suspended" ? `<div class="hata-kutusu">${ikon("circle-alert")}<span>${ç("Mekân askıda: içeride yalnız sahibi ve yöneticileri var; satış yok. Yönet'ten borcu ödeyip açarsın.")}</span></div>` : ""}
        ${salon() ? menuHtml(benGizli) : ""}
        <div class="mekan-blok"><div class="satir mekan-fikra-bas"><p class="ust-yazi">${ç("Mekânın akışı")}</p>
          <button class="dugme ikincil kucuk-d" id="mekan-fikra">${ikon("sparkles")}${ç("Fıkra anlat")}</button></div>
          <div id="mekan-akis">${akisHtml()}</div></div>
        <div class="oneri-dugmeler mekan-alt">
          ${staff() && salon() && !v.system ? `<button class="dugme ikincil kucuk-d" id="mekan-dekor">${ikon("move")}${ç("Dekor")}</button>
            <button class="dugme ikincil kucuk-d" id="mekan-yonet">${ikon("settings")}${ç("Yönet")}</button>` : ""}
          <button class="dugme sade kucuk-d" id="mekan-cik">${ikon("door-open")}${salon() ? ç("Mekândan çık") : ç("Odadan çık")}</button>
          ${!salon() ? `<button class="dugme ikincil kucuk-d" id="mekan-lobi">${ikon("hotel")}${ç("Lobiye in")}</button>` : ""}
          ${salon() && v.kind === "otel" && secenek.kalis?.() ? `<button class="dugme ikincil kucuk-d" id="mekan-odama">${ikon("bed")}${ç("Odana çık")}</button>` : ""}
          <button class="dugme sade kucuk-d" id="mekan-liste">${ikon("sofa")}${ç("Mekânlar")}</button>
          ${meydanaDonDugme("mekan")}
          ${salon() && !v.system && !staff() ? `<button class="dugme sade kucuk-d" id="mekan-rapor">${ikon("circle-alert")}${ç("Raporla")}</button>` : ""}
        </div>`;
    }
    function menuHtml(benGizli) {
      const v = V();
      if (staff()) {
        return `<div class="mekan-blok"><p class="ust-yazi">${ç("Menü")}</p><p class="kucuk">${ç("Kendi mekânında sipariş vermezsin. Fiyatları Yönet'ten değiştirirsin; müşterilerin siparişi kasaya geçer.")}</p>
          <div class="mekan-menu">${(v.menu ?? []).map((m) => `<span class="cip">${ikon(MENU_KALEM[m.item]?.[1] ?? "receipt-text")}${esc(menuAdi(m.item))} · ${esc(ç("{kr} kredi", { kr: kr(m.price) }))}</span>`).join("")}</div></div>`;
      }
      const gruplar = ["drink", "food", "gift"].map((cat) => [cat, (v.menu ?? []).filter((m) => m.cat === cat)]).filter(([, l]) => l.length);
      return `<div class="mekan-blok"><p class="ust-yazi">${ç("Menü")}</p>
        ${gruplar.map(([cat, l]) => `<div class="mekan-menu" data-kat="${cat}"><span class="kucuk mekan-menu-tur">${esc(MENU_TUR[cat])}</span>${l.map((m) =>
          `<button class="dugme ikincil kucuk-d mekan-kalem" data-mekan-kalem="${esc(m.item)}" ${v.status === "open" ? "" : "disabled"}>${ikon(MENU_KALEM[m.item]?.[1] ?? "receipt-text")}${esc(menuAdi(m.item))}<span class="mekan-fiyat">${esc(ç("{kr} kredi", { kr: kr(m.price) }))}</span></button>`).join("")}</div>`).join("")}
        <p class="kucuk">${benGizli ? ç("Adını gizlediğin için yalnız kendine sipariş verirsin; ısmarlama ve hediye için adın görünmeli (Arkadaşlar → Gizlilik).")
          : ç("Kendine sipariş verirsin ya da içerideki birine ısmarlarsın; hediye (çiçek, çikolata, kitap) birine verilir. Ödeyen sensin; ısmarlanan {n} dakika masada görünür.", { n: Number(zs.rule?.servedMin ?? VR().servedMin ?? 10) })}</p></div>`;
    }
    function akisHtml() {
      const f = [...(zs.feed ?? [])].reverse();
      if (!f.length) return `<p class="kucuk">${ç("Girdiğinden beri ısmarlama, hediye ya da fıkra olmadı. İlk fıkrayı sen anlat!")}</p>`;
      return `<ol class="mekan-akis-liste">${f.map(akisSatir).join("")}</ol>`;
    }
    function akisSatir(x) {
      const a = x.mine ? ç("Sen") : x.actor ?? ç("Biri"), b = x.to_me ? ç("sen") : x.target ?? ç("biri"), kalem = menuAdi(x.item);
      const zaman = `<small>${esc(zamanOnce(x.at))}</small>`;
      if (x.kind === "joke") {
        const gulebilir = !x.mine && !x.laughed;
        return `<li class="mekan-akis-fikra" data-feed="${Number(x.feed_id)}"><span class="ik-kutu">${ikon("sparkles")}</span>
          <div><b>${esc(x.mine ? ç("Bir fıkra anlattın") : ç("{a} bir fıkra anlattı", { a }))}</b>${zaman}
            <p class="mekan-fikra-metin">${esc(fikraMetni(x.joke))}</p>
            <div class="satir mekan-gul">${gulebilir ? `<button class="dugme ikincil kucuk-d" data-mekan-gul="${Number(x.feed_id)}">${ikon("sparkles")}${ç("Güldüm")}</button>` : ""}
              <span class="kucuk">${Number(x.laughs) ? esc(ç("{n} kişi güldü", { n: sayi(x.laughs) })) : x.mine ? esc(ç("Henüz gülen yok")) : ""}${x.laughed ? " · " + esc(ç("sen de güldün")) : ""}</span></div></div></li>`;
      }
      const metin = x.kind === "gift"
        ? (x.mine ? ç("{b} adlı oyuncuya {kalem} hediye ettin.", { b, kalem }) : x.to_me ? ç("{a} sana {kalem} hediye etti.", { a, kalem })
          : ç("{a}, {b} adlı oyuncuya {kalem} hediye etti.", { a, b, kalem }))
        : (x.mine ? ç("{b} için {kalem} ısmarladın.", { b, kalem }) : x.to_me ? ç("{a} sana {kalem} ısmarladı.", { a, kalem })
          : ç("{a}, {b} için {kalem} ısmarladı.", { a, b, kalem }));
      return `<li data-feed="${Number(x.feed_id)}" class="${x.to_me ? "bana" : ""}"><span class="ik-kutu">${ikon(x.kind === "gift" ? "gift" : "hand-coins")}</span>
        <div><span>${esc(metin)}</span>${zaman}</div></li>`;
    }
    function akisYaz() {
      const el = $("#mekan-akis", yer);
      if (!el) return;
      el.innerHTML = akisHtml();
      for (const b of $$("[data-mekan-gul]", el)) b.onclick = () => gul(b);
    }
    function icYaz() {
      const el = $("#mekan-ic", yer);
      if (el) { el.innerHTML = icHtml(); icBagla(); }
      const u = $("#mekan-ust", yer), b = $("#mekan-baslik", yer);
      if (u) u.textContent = ustYazi();
      if (b) b.textContent = baslik();
      etkinlikYaz();
    }
    function icBagla() {
      const el = $("#mekan-ic", yer);
      if (!el) return;
      for (const b of $$("[data-mekan-kisi]", el)) b.onclick = () => kisiKart(b.dataset.mekanKisi);
      for (const b of $$("[data-mekan-eylem]", el)) b.onclick = () => zy.eylem(b.dataset.mekanEylem);
      for (const b of $$("[data-mekan-kalem]", el)) b.onclick = () => siparis(b.dataset.mekanKalem);
      for (const b of $$("[data-mekan-gul]", el)) b.onclick = () => gul(b);
      $("#mekan-fikra", el)?.addEventListener("click", fikraAnlat);
      $("#mekan-cik", el)?.addEventListener("click", () => secenek.cik?.());
      $("#mekan-lobi", el)?.addEventListener("click", () => secenek.lobi?.());
      $("#mekan-odama", el)?.addEventListener("click", () => { const k = secenek.kalis?.(); if (k) secenek.oda?.(k.room); });
      $("#mekan-liste", el)?.addEventListener("click", () => Kabuk.git("sehir/mekanlar"));
      $("#mekan-rapor", el)?.addEventListener("click", () => raporla({ tur: "venue", ref: V().venue_id, ad: V().name }));
      $("#mekan-dekor", el)?.addEventListener("click", duzenBasla);
      $("#mekan-yonet", el)?.addEventListener("click", () => secenek.yonet?.());
      meydanaDonBagla(el);
    }

    // ---------- Sipariş, ısmarlama, hediye ----------
    // Kime: kendine (hediye değilse) ya da içerideki adı görünen biri (adını gizleyenle ve adını gizleyen kişiyle olmaz)
    function siparis(kalem, hedefP = null) {
      const v = V(), m = (v.menu ?? []).find((x) => x.item === kalem);
      if (!m || !salon()) return;
      if (staff()) { tost(ç("Kendi mekânından sipariş vermezsin."), "circle-alert"); return; }
      const hediye = m.cat === "gift", benGizli = !!ben()?.hides_name;
      const adaylar = benGizli ? [] : kisiler().filter((k) => !k.me && !k.hidden);
      const hedef = hedefP ? kisiler().find((k) => k.p === hedefP) : null;
      if (hediye && !hedef && !adaylar.length) { tost(benGizli ? ç("Adını gizlerken hediye verilmez.") : ç("Hediye için içeride birinin olması gerek."), "gift"); return; }
      const L = VR().limits ?? {};
      const secenekler = hedef ? `<input type="hidden" name="kime" value="${esc(hedef.p)}"><p class="aciklama">${esc(hediye ? ç("{kalem}, {ad} adlı oyuncuya hediye.", { kalem: menuAdi(kalem), ad: hedef.name })
          : ç("{ad} için {kalem}.", { ad: hedef.name, kalem: menuAdi(kalem) }))}</p>`
        : `<fieldset class="alan"><legend>${ç("Kime")}</legend><div class="radyo-liste">${hediye ? "" : `<label class="radyo"><input type="radio" name="kime" value="" checked><span><b>${ç("Kendime")}</b></span></label>`}
          ${adaylar.map((k, i) => `<label class="radyo"><input type="radio" name="kime" value="${esc(k.p)}" ${hediye && i === 0 ? "checked" : ""}><span><b>${esc(k.name)}</b>${k.friend ? `<span class="kucuk">${ç("arkadaşın")}</span>` : ""}</span></label>`).join("")}</div></fieldset>`;
      pencereForm({ ust: mekanAdi(v), baslik: ç("{kalem} · {kr} kredi", { kalem: menuAdi(kalem), kr: kr(m.price) }), onayAd: hediye ? ç("Hediye et") : ç("Sipariş ver"),
        onayIkon: hediye ? "gift" : "hand-coins",
        govde: `${secenekler}
          <p class="kucuk">${Number(m.erzak) ? ç("Yiyecek mekânın tezgâhından bir erzak tüketir; tezgâh boşsa yiyecek yok.") + " " : ""}${ç("Günde en çok {n} sipariş (bir mekânda {m}); başkalarına ısmarlama ve hediyeye günde en çok {kr} kredi, aynı kişiye günde en çok {k} kez.",
            { n: Number(L.ordersPerDay ?? 20), m: Number(L.ordersPerVenuePerDay ?? 10), kr: kr(Number(L.treatCrPerDay ?? 3000)), k: Number(L.treatsPerPairPerDay ?? 3) })}</p>
          ${hediye ? `<p class="kucuk">${ç("Hediye satılmaz ve para etmez; alan Hediyelerim'de saklar.")}</p>` : ""}
          ${keyifSiparisNotu(m.cat) ? `<p class="kucuk mekan-keyif-not">${ikon("face-slightly-smiling")} ${esc(keyifSiparisNotu(m.cat))}</p>` : ""}`,
        is: async (d) => {
          const kime = String(d.get("kime") ?? "") || null;
          if (hediye && !kime) throw new Error(ç("Hediye kendine verilmez; birini seç."));
          let r;
          try { r = await MekanYolu.siparis(kalem, kime, Number(m.price)); }
          catch (e) { if (e?.kod === "PRICE_CHANGED" || e?.kod === "VENUE_TARGET_GONE") zy.durumIste(); throw e; }
          tost(!kime ? ç("{kalem} geldi; afiyet olsun.", { kalem: menuAdi(kalem) }) + keyifEki(r)
            : hediye ? ç("{ad} adlı oyuncuya {kalem} hediye ettin.", { ad: r.recipient ?? "", kalem: menuAdi(kalem) })
            : ç("{ad} için {kalem} ısmarladın.", { ad: r.recipient ?? "", kalem: menuAdi(kalem) }), hediye ? "gift" : "hand-coins");
          Durum.ozet().catch(() => {});
        } });
    }
    // Kişinin kartından: ısmarlanacak (içecek, yiyecek) ya da hediye edilecek kalemi seç
    function kalemSec(p, hediye) {
      const v = V(), k = kisiler().find((x) => x.p === p);
      if (!k) return;
      const l = (v.menu ?? []).filter((m) => (hediye ? m.cat === "gift" : m.cat !== "gift"));
      pencere({ ust: hediye ? ç("Hediye ver") : ç("Ismarla"), baslik: k.name ?? "",
        govde: `<div class="mekan-menu mekan-menu-sec">${l.map((m) => `<button class="dugme ikincil kucuk-d mekan-kalem" data-kalem-sec="${esc(m.item)}">${ikon(MENU_KALEM[m.item]?.[1] ?? "receipt-text")}${esc(menuAdi(m.item))}<span class="mekan-fiyat">${esc(ç("{kr} kredi", { kr: kr(m.price) }))}</span></button>`).join("")}</div>`,
        dugmeler: [{ ad: ç("Kapat") }] });
      const pr = $$(".perde").at(-1);
      for (const b of $$("[data-kalem-sec]", pr)) b.onclick = () => { $(".pencere-dugmeler button", pr)?.click(); siparis(b.dataset.kalemSec, p); };
    }

    // ---------- Fıkra ve gülmek ----------
    function fikraAnlat() {
      const N = Math.min(FIKRALAR.length, Number(zs.rule?.jokes?.count ?? FIKRALAR.length));
      const anlatilan = new Set((zs.feed ?? []).filter((x) => x.kind === "joke").map((x) => Number(x.joke)));
      const sec = () => {
        const havuz = Array.from({ length: N }, (_, i) => i + 1).filter((n) => !anlatilan.has(n));
        const l = havuz.length >= 3 ? havuz : Array.from({ length: N }, (_, i) => i + 1);
        for (let i = l.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [l[i], l[j]] = [l[j], l[i]]; }
        return l.slice(0, 3);
      };
      const secHtml = (uc) => `<div class="radyo-liste mekan-fikra-sec">${uc.map((n, i) => `<label class="radyo"><input type="radio" name="fikra" value="${n}" ${i === 0 ? "checked" : ""}>
          <span><span class="mekan-fikra-metin">${esc(fikraMetni(n))}</span></span></label>`).join("")}</div>`;
      const J = zs.rule?.jokes ?? VR().jokes ?? {};
      const { form } = pencereForm({ ust: ç("Fıkra"), baslik: ç("Bir fıkra anlat"), onayAd: ç("Anlat"), onayIkon: "sparkles",
        govde: `<p class="aciklama">${ç("İçeridekilere anlatırsın; beğenen “Güldüm” der, gülenle aranızda yakınlık artar. {n} dakikada bir fıkra anlatılır.", { n: Math.max(1, Math.round(Number(J.minIntervalSec ?? 180) / 60)) })}</p>
          <div id="mekan-fikra-secenek">${secHtml(sec())}</div>
          <button class="dugme sade kucuk-d" type="button" id="mekan-fikra-baska">${ikon("repeat-2")}${ç("Başka üç fıkra")}</button>`,
        is: async (d) => {
          const n = Number(d.get("fikra"));
          if (!n) throw new Error(ç("Bir fıkra seç."));
          await MekanYolu.fikra(n);
          tost(ç("Fıkranı anlattın."), "sparkles");
          const k = ben();
          if (k?.character_id) gorunum.balon(k.character_id, fikraMetni(n));
          zy.durumIste();
        } });
      $("#mekan-fikra-baska", form)?.addEventListener("click", () => { const el = $("#mekan-fikra-secenek", form); if (el) el.innerHTML = secHtml(sec()); });
    }
    async function gul(b) {
      const f = Number(b.dataset.mekanGul);
      if (!f || b.disabled) return;
      b.disabled = true;
      try {
        const r = await MekanYolu.gul(f);
        const x = (zs.feed ?? []).find((y) => Number(y.feed_id) === f);
        if (x) { x.laughs = Number(r.laughs ?? x.laughs); x.laughed = true; }
        zy.eylem("laugh", null, null, { sessiz: true });
      } catch (e) { tost(hataMetni(e), "circle-alert"); b.disabled = false; return; }
      if (!kapandi) akisYaz();
    }

    // ---------- Kişinin kartı ----------
    function kisiKart(p) {
      const k = kisiler().find((x) => x.p === p);
      if (!k || k.me) return;
      const v = V(), benGizli = !!ben()?.hides_name;
      const cipler = [k.host ? `<span class="cip">${ikon(salon() ? "crown" : "bed")}${esc(salon() ? ç("Mekânın sahibi") : ç("Odanın konuğu"))}</span>` : "",
        !k.host && k.staff ? `<span class="cip">${ikon("key-round")}${esc(ç("Yönetici"))}</span>` : "",
        k.country_id ? `<span class="cip">${esc(ulkeAdi(k.country_id))}</span>` : "",
        k.friend ? `<span class="cip">${ikon("heart")}${esc(ç("Arkadaşın"))}</span>` : ""].filter(Boolean).join(" ");
      const ismarlar = salon() && !staff() && !k.hidden && !benGizli && v.status === "open";
      const cikarir = salon() ? staff() && !k.staff : !!zs.room_mine;
      pencere({ ust: salon() ? mekanAdi(v) : ç("Otel odası"), baslik: k.hidden ? ç("Adını gizleyen biri") : k.name,
        govde: `<div class="meydan-kisi-kart" data-mekan-kart="${esc(p)}">${cipler ? `<p class="satir" style="gap:6px;flex-wrap:wrap">${cipler}</p>` : ""}
          <p class="aciklama">${esc(k.hidden ? ç("Adını gizlemiş; figürü ve ülkesi görünür. Adını gizleyenle ısmarlama, hediye ve yakınlık olmaz.")
            : ç("Seninle aynı yerde. El salladıkça, ısmarladıkça ve aynı masada oturdukça yakınlığınız artar."))}</p>
          <p class="kucuk mekan-bag" id="mekan-kart-bag"></p>
          ${cikarir ? `<p class="kucuk">${esc(salon() ? ç("Mekândan çıkarırsan {n} dakika giremez.", { n: Number(VR().kickMinutes ?? 60) }) : ç("Odadan çıkarırsan odana yeniden gelebilir; kapın yalnız arkadaşlarına açık."))}</p>` : ""}</div>`,
        dugmeler: [
          { ad: ç("El salla"), ikon: "hand", sinif: "altin", is: () => zy.eylem("wave", p) },
          ...(ismarlar ? [{ ad: ç("Ismarla"), ikon: "hand-coins", is: () => kalemSec(p, false) }, { ad: ç("Hediye ver"), ikon: "gift", is: () => kalemSec(p, true) }] : []),
          ...(k.hidden ? [] : [{ ad: ç("Profil"), ikon: "user-round", is: () => profilAc(k.character_id) },
            { ad: ç("Mesaj"), ikon: "message-circle", is: () => mesajBaslat(k.character_id, k.name) }]),
          ...(cikarir ? [{ ad: salon() ? ç("Mekândan çıkar") : ç("Odadan çıkar"), ikon: "door-open", sinif: "mercan", is: () => cikar(p, k) }] : []),
          { ad: ç("Kapat") },
        ] });
      if (!k.hidden && k.character_id) {
        MekanYolu.iliski(k.character_id).then((b) => { const el = $("#mekan-kart-bag"); if (el) el.innerHTML = bagYazisi(b); }).catch(() => {});
      }
    }
    async function cikar(p, k) {
      try {
        await zy.cikar(p);
        tost(k.hidden ? ç("Biri dışarı çıkarıldı.") : ç("{ad} dışarı çıkarıldı.", { ad: k.name }), "door-open");
      } catch (e) { tost(hataMetni(e), "circle-alert"); zy.durumIste(); }
    }

    // Zemine ya da eşyaya dokunuş: boş kareye yürür, oturulacak eşyaya oturur
    function zeminDokun(x, z) {
      if (duzen || !zs) return;
      const bos = odaDuraklari(zs.grid, zs.items, zs.catalog).bos;
      if (!bos.some((q) => q[0] === x && q[1] === z)) { tost(ç("Orada eşya var; boş bir kareye git."), "footprints"); return; }
      zy.yuru(x, z);
    }
    function oturakDokun(i) {
      if (duzen || !zs) return;
      zy.eylem("sit", null, i);
    }

    // ---------- Görünüm: yerin değişince ----------
    const sahnede = () => mod === "3b" && oda3bOrnek && Uc.cizici?.etkin === oda3bOrnek && !duzen;
    const gorunum = {
      durum(s) {
        const once = zs;
        zs = s;
        if (!once || once.space !== s.space || once.venue?.venue_id !== s.venue?.venue_id) { duzen = false; ciz(); return; }
        if (duzen) { if (!s.venue?.manage) { duzen = false; ciz(); return; } guncelle(); return; }
        icYaz();
        guncelle();
      },
      yuru(p, x, z, kendim) { if (sahnede()) oda3bOrnek.kisiYuru(p, x, z, kendim); else guncelle(); },
      eylem(p, e, hedef, oturak) { if (sahnede()) oda3bOrnek.kisiEylem(p, e, hedef, oturak); else guncelle(); },
      cik(p) {
        balonlar2b.delete(p);
        if (sahnede()) oda3bOrnek.kisiCik(p);
        if (!duzen) icYaz();
      },
      balon(kimlik, metin) {
        const k = kisiler().find((x) => !x.hidden && x.character_id === kimlik);
        if (!k) return;
        const sn = Number(zs?.rule?.balloonSec ?? 7);
        if (sahnede()) oda3bOrnek.balon(kimlik, metin);
        balonlar2b.set(k.p, { metin: String(metin ?? ""), bitis: Date.now() + sn * 1000 });
        if (mod === "2b") { plan2b(); setTimeout(() => { if (!kapandi && mod === "2b") plan2b(); }, sn * 1000 + 50); }
      },
      ikram() { guncelle(); },
      fikra(v) {
        const k = kisiler().find((x) => x.p === v.p);
        if (k && !k.me && !k.hidden && k.character_id) gorunum.balon(k.character_id, fikraMetni(v.joke));
      },
      gul() { if (!duzen) akisYaz(); },
      bitti(neden, e) { secenek.bitti?.(neden, e); },
    };
    const zyBirak = zy.bagla(gorunum);

    // ---------- Dekor (sahibi ve yöneticisi; salonda) ----------
    function duzenBasla() {
      const m = yonetim();
      if (!m || !salon()) return;
      items = (m.items ?? []).map((p) => ({ ...p }));
      secili = -1; uyari = ""; duzen = true;
      ciz();
    }
    const degisti = () => JSON.stringify(items) !== JSON.stringify(yonetim()?.items ?? []);
    const esyaAdi = (i) => çv(katalog().find((c) => c.id === items[i]?.i)?.name);
    function araclarHtml() {
      const m = yonetim(), s = secili >= 0 ? items[secili] : null;
      const cek = mekanCekicilik(m, items);
      return `<div class="oda-arac mekan-arac">
        <div class="oda-secili"><b id="mekan-secili-ad">${s ? esc(esyaAdi(secili)) : ç("Bir eşyaya dokun")}</b>
          <span class="kucuk${uyari ? " oda-uyari" : ""}" id="mekan-uyari">${esc(uyari || (s ? (mod === "3b" ? ç("Sürükle ya da oklarla taşı.") : ç("Oklarla taşı.")) : ç("{n} / {m} eşya", { n: items.length, m: Number(m.max_items) })))}</span></div>
        <div class="oda-dugmeler" role="group" aria-label="${ç("Seçili eşya")}">
          <button class="dugme ikincil kucuk-d" data-mekan-yon="-1,0" aria-label="${ç("Sola taşı")}" ${s ? "" : "disabled"}>${ikon("arrow-left")}</button>
          <button class="dugme ikincil kucuk-d" data-mekan-yon="0,-1" aria-label="${ç("Geriye taşı")}" ${s ? "" : "disabled"}>${ikon("arrow-up")}</button>
          <button class="dugme ikincil kucuk-d" data-mekan-yon="0,1" aria-label="${ç("Öne taşı")}" ${s ? "" : "disabled"}>${ikon("arrow-down")}</button>
          <button class="dugme ikincil kucuk-d" data-mekan-yon="1,0" aria-label="${ç("Sağa taşı")}" ${s ? "" : "disabled"}>${ikon("arrow-right")}</button>
          <button class="dugme ikincil kucuk-d" id="mekan-dondur" ${s ? "" : "disabled"}>${ikon("rotate-cw")}${ç("Döndür")}</button>
          <button class="dugme sade kucuk-d" id="mekan-kaldir" ${s ? "" : "disabled"}>${ikon("trash")}${ç("Kaldır")}</button>
        </div>
        <p class="kucuk" id="mekan-cekicilik">${ç("Çekicilik {a} / {b}: süs eşyalarının bedeli; çekici mekâna simülasyon müşterisi daha çok gelir. Masa, tezgâh ve tabure ücretsizdir.", { a: sayi(cek), b: sayi(Number(m.decor_max ?? 0)) })}</p>
        <div class="satir" style="flex-wrap:wrap;gap:8px;margin-top:4px">
          <button class="dugme ikincil kucuk-d" id="mekan-ekle" ${items.length >= Number(m.max_items) ? "disabled" : ""}>${ikon("plus")}${ç("Eşya ekle")}</button>
          <span style="flex:1"></span>
          <button class="dugme sade kucuk-d" id="mekan-vazgec">${ç("Vazgeç")}</button>
          <button class="dugme altin kucuk-d" id="mekan-kaydet" ${degisti() && !gonderiliyor ? "" : "disabled"}>${ikon("check")}${ç("Kaydet")}</button>
        </div>
        ${degisti() ? `<p class="kucuk">${ç("Kaydedilmemiş değişiklik var. Kaydedince içeridekiler eşyanın altında kalıyorsa yanına geçer.")}</p>` : ""}
      </div>`;
    }
    function guncelle() {
      if (duzen) {
        const a = $(".mekan-arac", yer);
        if (a) a.outerHTML = araclarHtml();
        baglaAraclar();
      }
      if (mod === "2b") plan2b();
      else if (oda3bOrnek && Uc.cizici?.etkin === oda3bOrnek) oda3bOrnek.durumYaz(durum3b());
    }
    function dene(yeni, i) {
      const h = mekanDenetle(yonetim(), yeni);
      if (h) { uyari = MEKAN_DUZEN_HATA[h] ?? h; guncelle(); return false; }
      items = yeni; uyari = "";
      if (i !== undefined) secili = i;
      guncelle();
      return true;
    }
    const tasi = (i, x, z) => { if (i >= 0 && items[i]) dene(items.map((p, j) => (j === i ? { ...p, x, z } : p)), i); };
    function dondur() {
      const p = items[secili], c = katalog().find((x) => x.id === p?.i);
      if (!p || !c) return;
      const m = yonetim(), r = (p.r + 1) % 4, iz = odaIzi(c, { r });
      const x = Math.max(0, Math.min(p.x, m.grid.w - iz.w)), z = Math.max(0, Math.min(p.z, m.grid.d - iz.d));
      dene(items.map((q, j) => (j === secili ? { ...q, r, x, z } : q)), secili);
    }
    function kaldir() {
      if (secili < 0) return;
      items = items.filter((_, j) => j !== secili);
      secili = -1; uyari = "";
      guncelle();
    }
    function ekle(id) {
      const m = yonetim(), c = katalog().find((x) => x.id === id);
      if (!m || !c) return;
      for (const r of [0, 1]) for (let z = 0; z < m.grid.d; z++) for (let x = 0; x < m.grid.w; x++) {
        const yeni = [...items, { i: id, x, z, r }];
        if (!mekanDenetle(m, yeni)) { items = yeni; secili = items.length - 1; uyari = ""; guncelle(); return; }
      }
      tost(ç("{esya} için yer yok. Önce bir eşyayı kaldır ya da kaydır.", { esya: çv(c.name) }), "circle-alert");
    }
    // Katalogdan eşya: sabit parçalar (tezgâh, masa, tabure …) türün sınırına kadar ücretsiz; süs eşyası sahibinin eşyasıdır
    // (bu mekânın başlangıç düzenindekiler ücretsiz). Sahibi eksik eşyayı mobilyayla kurar (D-121); yöneticiler kuramaz.
    async function eklePenceresi() {
      const v = V(), m = yonetim();
      if (!m) return;
      const sahibi = v.role === "owner";
      let stok = null;
      if (sahibi) stok = Number((await Sunucu.cagir("home_layout").catch(() => null))?.furniture?.stock ?? 0);
      if (kapandi || !duzen) return;
      const kullanilan = (id) => items.filter((p) => p.i === id).length;
      const satir = (c) => {
        const n = kullanilan(c.id);
        const kalan = c.fixture ? Number(c.max ?? 0) - n : Number(m.free?.[c.id] ?? 0) + Number(m.owned?.[c.id] ?? 0) - n;
        const durum = c.fixture ? ç("sabit parça · en çok {n}", { n: Number(c.max ?? 0) })
          : [Number(m.free?.[c.id] ?? 0) ? ç("burada {n} ücretsiz", { n: Number(m.free[c.id]) }) : "", Number(m.owned?.[c.id] ?? 0) ? ç("sahibinin {n} tane", { n: Number(m.owned[c.id]) }) : "",
            ç("çekicilik {n}", { n: Number(c.cost ?? 0) })].filter(Boolean).join(" · ");
        const dugme = kalan > 0 ? `<button class="dugme ikincil kucuk-d" data-mekan-yeni="${esc(c.id)}">${ikon("plus")}${ç("Ekle")}</button>`
          : !c.fixture && sahibi ? `<button class="dugme altin kucuk-d" data-mekan-kur="${esc(c.id)}" ${stok >= Number(c.cost ?? 0) ? "" : "disabled"}
              title="${esc(stok >= Number(c.cost ?? 0) ? ç("{n} mobilya kullanılır; eşya senin olur.", { n: Number(c.cost ?? 0) }) : ç("Mobilyan yetmiyor; çarşıdan alabilirsin."))}">${ikon("hammer")}${ç("Kur")}</button>`
          : `<span class="kucuk">${c.fixture ? ç("Sınırda") : ç("Sahibinin eşyası yok")}</span>`;
        return `<div class="liste-satir" data-mekan-satir="${esc(c.id)}"><span class="liste-ikon" style="background:${ODA_RENK[c.id] ?? "#ccc"}33;color:${ODA_RENK[c.id] ?? "#666"}">${ikon(c.rug ? "square" : c.fixture ? "store" : "armchair")}</span>
          <div><b>${esc(çv(c.name))}</b><div class="alt">${ç("{w}×{d} kare", { w: Number(c.w), d: Number(c.d) })}${Number(c.seats) ? " · " + ç("{n} kişi oturur", { n: Number(c.seats) }) : ""} · ${esc(durum)}</div></div>
          ${dugme}</div>`;
      };
      pencere({ ust: ç("Eşya ekle"), baslik: mekanAdi(v), govde: `
        <p class="aciklama">${ç("Masa, tezgâh ve tabure gibi sabit parçalar ücretsizdir. Süs eşyası sahibinin eşyasıdır (evinde de kullanılır); başlangıç düzenindekiler ücretsiz. Süs çekiciliği artırır; güç, gelir ya da oy vermez.")}</p>
        ${sahibi ? `<p class="kucuk">${ç("Mobilyan: {n}", { n: sayi(stok) })}</p>` : `<p class="kucuk">${ç("Eksik süs eşyasını yalnız sahibi mobilyayla kurar.")}</p>`}
        <div class="liste">${(m.catalog ?? []).map(satir).join("")}</div>`,
        dugmeler: [{ ad: ç("Kapat") }] });
      const pr = $$(".perde").at(-1);
      const kapat = () => $(".pencere-dugmeler button", pr)?.click();
      for (const b of $$("[data-mekan-yeni]", pr)) b.onclick = () => { kapat(); ekle(b.dataset.mekanYeni); };
      for (const b of $$("[data-mekan-kur]", pr)) b.onclick = () => kur(b.dataset.mekanKur, b, kapat);
    }
    let kuruluyor = false;
    async function kur(id, dugme, kapat) {
      if (kuruluyor) return;
      kuruluyor = true;
      if (dugme) dugme.disabled = true;
      try {
        const r = await Sunucu.yap("home_item_make", { p_item: id, p_qty: 1 });
        const kart = await MekanYolu.kart(V().venue_id);
        if (zs && kart?.manage) zs.venue = { ...zs.venue, manage: { ...kart.manage, items: zs.venue.manage?.items ?? kart.manage.items } };
        kapat?.();
        tost(ç("{esya} kuruldu: {n} mobilya kullanıldı.", { esya: çv(katalog().find((c) => c.id === id)?.name), n: Number(r.made?.cost ?? 0) }), "hammer");
        if (!kapandi && duzen) ekle(id);
      } catch (e) {
        if (dugme) dugme.disabled = false;
        tost(hataMetni(e), "circle-alert");
      } finally { kuruluyor = false; }
    }
    async function kaydet() {
      if (gonderiliyor) return;
      gonderiliyor = true;
      guncelle();
      try {
        const kart = await MekanYolu.duzen(V().venue_id, items);
        if (zs) { zs.venue = kart; zs.items = kart.manage?.items ?? items; }
        duzen = false; secili = -1; uyari = "";
        tost(ç("Mekânın düzeni kaydedildi."), "check");
        zy.durumIste();
      } catch (e) {
        uyari = hataMetni(e);
      } finally { gonderiliyor = false; }
      if (!kapandi) ciz();
    }
    function baglaAraclar() {
      for (const b of $$("[data-mekan-yon]", yer)) b.onclick = () => {
        const [dx, dz] = b.dataset.mekanYon.split(",").map(Number);
        const p = items[secili];
        if (p) tasi(secili, p.x + dx, p.z + dz);
      };
      $("#mekan-dondur", yer)?.addEventListener("click", dondur);
      $("#mekan-kaldir", yer)?.addEventListener("click", kaldir);
      $("#mekan-ekle", yer)?.addEventListener("click", eklePenceresi);
      $("#mekan-kaydet", yer)?.addEventListener("click", kaydet);
      $("#mekan-vazgec", yer)?.addEventListener("click", () => { duzen = false; secili = -1; uyari = ""; ciz(); });
    }
    function bagla() {
      $("#mekan-mod", yer)?.addEventListener("click", () => {
        hata3b = false;
        const ikiB = mod === "3b";
        Gorunum.ayarla(ikiB ? "2b" : "3b");
        tost(ikiB ? ç("Hafif görünüm (2B) seçildi. Ayarlar'dan değiştirebilirsin.") : ç("3B görünüm seçildi."), "layers");
      });
      for (const b of $$("[data-mekan-ilgi]", yer)) b.onclick = () => ilgilen(b);
      if (duzen) baglaAraclar(); else icBagla();
    }

    // ---------- 2B plan (yukarıdan) ----------
    function plan2b() {
      const kutu = $("#mekan-2b", yer);
      if (!kutu || !zs) return;
      const its = duzen ? items : zs.items ?? [], cat = katalog(), k = new Map(cat.map((c) => [c.id, c]));
      const W = Number(zs.grid.w), D = Number(zs.grid.d);
      const izgara = duzen ? Array.from({ length: W + 1 }, (_, x) => `<line x1="${x}" y1="0" x2="${x}" y2="${D}" class="oda2b-cizgi"/>`).join("")
        + Array.from({ length: D + 1 }, (_, z) => `<line x1="0" y1="${z}" x2="${W}" y2="${z}" class="oda2b-cizgi"/>`).join("") : "";
      const sirali = its.map((p, i) => ({ p, i })).sort((a, b) => Number(!k.get(a.p.i)?.rug) - Number(!k.get(b.p.i)?.rug));
      const esyalar = sirali.map(({ p, i }) => {
        const c = k.get(p.i);
        if (!c) return "";
        const iz = odaIzi(c, p);
        const ad = ODA_KISA[c.id] ?? çv(c.name).split(" ")[0];
        const boy = Math.min(0.32, (iz.w * 0.86) / (ad.length * 0.56));
        return `<g class="oda2b-esya${i === secili && duzen ? " secili" : ""}${c.rug ? " hali" : ""}${Number(c.seats) ? " oturak" : ""}" data-mekan-esya="${i}" data-esya="${esc(c.id)}">
          <rect x="${p.x + 0.06}" y="${p.z + 0.06}" width="${iz.w - 0.12}" height="${iz.d - 0.12}" rx="0.12" fill="${ODA_RENK[c.id] ?? "#bbb"}"/>
          ${c.rug ? `<text x="${p.x + 0.16}" y="${p.z + iz.d - 0.16}" class="oda2b-yazi" style="font-size:${boy.toFixed(3)}px">${esc(ad)}</text>`
            : `<text x="${p.x + iz.w / 2}" y="${p.z + iz.d / 2 + boy * 0.36}" text-anchor="middle" class="oda2b-yazi" style="font-size:${boy.toFixed(3)}px">${esc(ad)}</text>`}</g>`;
      }).join("");
      // İçeridekiler planda (kendin altın halkalı); oturan oturduğu yerde; ısmarlanan küçük işaret; balonu üstünde
      let kisi2b = "";
      if (!duzen) {
        const dur = odaDuraklari(zs.grid, zs.items ?? [], zs.catalog ?? []);
        const kullanilan = new Map(), simdi = Date.now();
        const ikramli = new Set((zs.served ?? []).map((x) => x.p));
        kisi2b = kisiler().map((kk) => {
          let [fx, fz] = [Number(kk.x) + 0.5, Number(kk.z) + 0.5];
          const ot = kk.emote === "sit" && kk.seat != null ? Number(kk.seat) : null;
          if (ot != null) {
            const liste = [...dur.oturak, ...dur.masa].filter((q) => q.ad.split(":")[1] === String(ot));
            const n = kullanilan.get(ot) ?? 0;
            kullanilan.set(ot, n + 1);
            const yq = liste[n % Math.max(1, liste.length)];
            if (yq) [fx, fz] = yq.bas ?? [yq.x, yq.z];
          }
          const g = kk.look ?? varsayilanGorunus(kk.name || "?");
          const giysi = g.kiyafet === "uniforma" ? UNIFORMA.kumas : GIYSI[g.renk] ?? GIYSI[0];
          const ad = kk.me ? ç("Sen") : kk.hidden ? "" : String(kk.name ?? "");
          const b = balonlar2b.get(kk.p);
          const balon = b && b.bitis > simdi ? (() => {
            const m = meydanKisa(b.metin, 26), gen = Math.max(1.2, m.length * 0.17 + 0.4);
            return `<g class="oda2b-balon" transform="translate(0 -0.95)"><rect x="${(-gen / 2).toFixed(2)}" y="-0.36" width="${gen.toFixed(2)}" height="0.46" rx="0.14"/>
              <text y="-0.05" text-anchor="middle" class="oda2b-yazi" style="font-size:0.26px">${esc(m)}</text></g>`;
          })() : "";
          return `<g class="oda2b-kisi${kk.me ? " ben" : ""}${kk.host ? " ev-sahibi" : ""}" data-mekan-kisi2b="${esc(kk.p)}" data-kare="${Number(kk.x)},${Number(kk.z)}" data-eylem="${esc(ot != null ? "oturak" : kk.emote ?? "")}"${ot != null ? ` data-oturak="${ot}"` : ""}
            transform="translate(${fx.toFixed(2)} ${fz.toFixed(2)})"${kk.me ? "" : ` role="button" tabindex="0" aria-label="${esc(ad || ç("Adını gizleyen biri"))}"`}>
            ${kk.me ? `<circle r="0.42" class="oda2b-ben"/>` : ""}<circle r="0.3" fill="${giysi}" class="oda2b-figur-govde"/><circle r="0.17" cy="-0.03" fill="${TEN[g.ten] ?? TEN[0]}"/>
            ${ikramli.has(kk.p) ? `<circle r="0.11" cx="0.3" cy="-0.3" class="mekan2b-ikram"/>` : ""}
            ${ad ? `<text y="0.62" text-anchor="middle" class="oda2b-ad" style="font-size:0.24px">${esc(ad.length > 12 ? ad.slice(0, 11) + "…" : ad)}</text>` : ""}${balon}</g>`;
        }).join("");
      }
      kutu.innerHTML = `<svg viewBox="-0.35 -0.35 ${W + 0.7} ${D + 0.7}" role="img" aria-label="${esc(ç("Mekânın planı"))}" data-tur="${esc(tur3b())}" data-kisi="${duzen ? 0 : kisiler().length}" data-duzen="${duzen ? 1 : 0}">
        <rect x="0" y="0" width="${W}" height="${D}" class="oda2b-doseme mekan2b-doseme"/>${duzen ? "" : `<rect x="0" y="0" width="${W}" height="${D}" class="oda2b-zemin-tik" data-mekan-zemin/>`}${izgara}${esyalar}
        <line x1="-0.12" y1="-0.12" x2="${W}" y2="-0.12" class="oda2b-duvar"/><line x1="-0.12" y1="-0.12" x2="-0.12" y2="${D}" class="oda2b-duvar"/>${kisi2b}</svg>`;
      const svg = $("svg", kutu);
      for (const g of $$("[data-mekan-esya]", kutu)) g.addEventListener("click", (e) => {
        if (duzen) { secili = Number(g.dataset.mekanEsya); uyari = ""; guncelle(); return; }
        const i = Number(g.dataset.mekanEsya), id = its[i]?.i;
        if (k.get(id)?.rug) { const q = odaSvgKare(svg, e); if (q) zeminDokun(q[0], q[1]); }
        else if (oturaklar().includes(id)) oturakDokun(i);
        else tost(ç("Orada eşya var; boş bir kareye git."), "footprints");
      });
      $("[data-mekan-zemin]", kutu)?.addEventListener("click", (e) => { const q = odaSvgKare(svg, e); if (q) zeminDokun(q[0], q[1]); });
      for (const g of $$("[data-mekan-kisi2b]", kutu)) {
        const ac2 = (e) => { e.stopPropagation(); kisiKart(g.dataset.mekanKisi2b); };
        g.addEventListener("click", ac2);
        g.addEventListener("keydown", (e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); ac2(e); } });
      }
    }

    // ---------- 3B ----------
    function durum3b() {
      const v = V(), gece = bolgeGecesi(v.region_id);
      const its = duzen ? items : zs.items ?? [], cat = katalog();
      const duraklar = odaDuraklari(zs.grid, its, cat);
      const e = canliEtkinlik();
      return { anahtar: `mekan|${v.venue_id}|${zs.space}`, kind: "room", zone: null, garden: false, grid: zs.grid, items: its, catalog: cat,
        secili: duzen ? secili : -1, duzen, sehir: secenek.sehir ?? 1, gece, figur: null, duraklar, hedef: null, erzak: 0, kiler: false,
        ziyaret: duzen ? null : { ben: zs.presence_id, kisiler: kisiler(), kural: zs.rule, sunucu: zs.server_time, oturaklar: oturaklar(), sahibim: false },
        mekan: { tur: tur3b(), ad: salon() ? mekanAdi(v) : "", menu: (v.menu ?? []).map((m) => ({ item: m.item, price: Number(m.price) })), etkinlik: e?.kind ?? null,
          musteri: salon() && !v.system ? Number(zs.sim_visitors ?? 0) : 0, ikram: (zs.served ?? []).map((x) => ({ p: x.p, item: x.item, at: x.at })) } };
    }
    function sahneBirak() { if (oda3bOrnek && Uc.cizici?.etkin === oda3bOrnek) Uc.cizici.birak(oda3bOrnek); }
    async function sahneBagla() {
      const el = $("#mekan-sahne", yer);
      if (!el || mod !== "3b") { sahneBirak(); return; }
      try {
        const { THREE, cizici } = await Uc.yukle();
        if (kapandi || mod !== "3b" || $("#mekan-sahne", yer) !== el || !el.isConnected) return;
        oda3bOrnek ??= oda3bKur(THREE, cizici);
        const a = oda3bOrnek;
        a.dinle("secim", (i) => { if (duzen) { secili = i; uyari = ""; guncelle(); } });
        a.dinle("tasi", (i, x, z) => { if (duzen) tasi(i, x, z); });
        a.dinle("ye", () => {});
        a.dinle("kisi", (p) => kisiKart(p));
        a.dinle("zemin", (x, z) => zeminDokun(x, z));
        a.dinle("oturak", (i) => oturakDokun(i));
        a.kapBagla(el, $("#mekan-etiketler", el));
        a.durumYaz(durum3b());
        if (!cizici.bagla(a, el)) throw new Error("webgl-bagla");
        $("#mekan-yukleniyor", el)?.classList.add("bitti");
      } catch (e) {
        console.warn("3B mekân açılamadı:", e);
        if (kapandi) return;
        hata3b = true; mod = "2b";
        tost(ç("3B mekân bu cihazda açılamadı; hafif görünüm gösteriliyor."), "layers");
        ciz();
      }
    }

    if (secenek.duzenle && staff() && salon() && yonetim()) { items = (yonetim().items ?? []).map((p) => ({ ...p })); duzen = true; }
    ciz();
    const b1 = Gorunum.dinle(() => {
      const yeni = Gorunum.uc() && !hata3b ? "3b" : "2b";
      if (yeni !== mod) { mod = yeni; ciz(); }
    });
    // Gökyüzü ve lambalar gerçek saate göre (dakikada bir); ısmarlananlar süresi dolunca masadan kalkar
    const saat = setInterval(() => { if (!document.hidden && !kapandi) { if (!duzen) akisYaz(); guncelle(); } }, 60000);
    return () => { kapandi = true; b1(); zyBirak?.(); clearInterval(saat); sahneBirak(); };
  }
  return { ac };
})();

// ---------- Ekran: mekânın içi ----------
Kabuk.kaydet("sehir/mekan", {
  async ac(kap) {
    let kapandi = false, zy = null, panelBirak = null, burada = null;
    const [harita] = await Promise.all([Durum.harita().catch(() => null), Durum.kurallar().catch(() => null)]);
    const birak = () => { panelBirak?.(); panelBirak = null; zy?.kapat(); zy = null; };
    const listeye = (bildiri = null) => {
      if (kapandi) return;
      birak();
      MekanYolu.hedefUnut();
      mekanBildiri = bildiri;
      Kabuk.git("sehir/mekanlar");
    };
    // Bu otelde kaldığın oda (konaklaman): "Odana çık"
    const kalis = () => (burada?.stay && burada.stay.venue_id === zy?.s?.venue?.venue_id ? burada.stay : null);

    async function gir(mekan, yer = "main", { duzenle = false } = {}) {
      birak();
      kap.innerHTML = `<div class="sayfa"><div class="kart yuk-kart">${esc(yer === "main" ? ç("Mekâna giriliyor…") : ç("Odaya çıkılıyor…"))}</div></div>`;
      const z = MekanZiyareti.ac(mekan, yer);
      zy = z;
      let hata = null, neden = null;
      z.bagla({ bitti: (n, e) => { neden = n; hata = e ?? null; } });
      // Konaklaman ("Odana çık") ve şehrin bilgisi girişle birlikte okunur
      const [s, r] = await Promise.all([z.gir(), MekanYolu.burada().catch(() => null)]);
      if (kapandi || zy !== z || !kap.isConnected) return;
      burada = r ?? burada;
      if (!s) { listeye(hata ? hataMetni(hata) : MEKAN_NEDEN[neden] ?? ç("Bu mekâna şu an girilemiyor.")); return; }
      try { sessionStorage.setItem("civora.mekan", JSON.stringify({ mekan, yer })); } catch { /* yok */ }
      ciz(s, duzenle);
    }
    function ciz(s, duzenle) {
      const v = s.venue, salon = s.space === "main";
      kap.innerHTML = `<div class="sayfa"><div id="mekan-yer"></div></div>`;
      panelBirak = MekanPaneli.ac($("#mekan-yer", kap), zy, { sehir: Number(harita?.cities?.[v.region_id] ?? 1), duzenle, kalis,
        cik: () => listeye(salon ? ç("Mekândan çıktın.") : ç("Odadan çıktın.")),
        bitti: (n, e) => dustu(n, e),
        yonet: () => mekanimGit(v.venue_id),
        oda: (n) => gir(v.venue_id, "room:" + n),
        lobi: () => gir(v.venue_id, "main") });
    }
    function dustu(neden, e) {
      if (kapandi) return;
      const metin = e ? hataMetni(e) : MEKAN_NEDEN[neden] ?? MEKAN_NEDEN.giris;
      tost(metin, "door-open");
      listeye(metin);
    }

    const h = MekanYolu.hedefAl();
    if (h) await gir(h.mekan, h.yer ?? "main", { duzenle: !!h.duzenle });
    else {
      // Doğrudan adresle (ya da hedefsiz) gelindiyse: içerideysen oraya, değilse mekânların listesi
      const d = await MekanYolu.durum().catch(() => null);
      if (!kap.isConnected) return () => {};
      if (d?.in_venue && d.venue?.venue_id) await gir(d.venue.venue_id, d.space ?? "main");
      else setTimeout(() => listeye(null));
    }
    return () => { kapandi = true; birak(); MekanYolu.hedefUnut(); };
  },
});

// ===== 98zi_ev_partisi.js =====
// ---------- Ev partisi (D-142; C-7): Evim'deki parti kartı, parti kurma, davet ve plak pencereleri, Arkadaşlar'daki
// "Davetlerin", evin içindeki parti bandı (plak ve ikram), plağın çalınması ----------
// Ev sahibi evinde (ya da pansiyon odasında) parti kurar: tema, başlangıç (şimdi ya da ileri bir saat), süre, davetliler
// (arkadaşlar ve tanıdıklar; kişinin tercihi izin veriyorsa), plak (koleksiyonundaki ya da grubunun EP'si). Parti sürerken
// davetli kapı ne olursa olsun girer; evin 3B ve 2B görünümünde temanın süsleri (44_oda3b.js, 33_oda.js), ikram tepsisi,
// pay alanın elinde tabak, alkışta konfeti. Bütün kararlar sunucuda (home_party_*); ekran sunucunun durumunu gösterir.

const PARTI_TEMA = { sohbet: ç("Çay ve sohbet"), muzik: ç("Müzik gecesi"), kutlama: ç("Kutlama"), sofra: ç("Akşam sofrası") };
const PARTI_TEMA_IK = { sohbet: "message-circle", muzik: "disc-3", kutlama: "party-popper", sofra: "croissant" };
const PARTI_TEMA_SUS = {
  sohbet: ç("Semaver, ince belli bardaklar ve ışık zinciri."),
  muzik: ç("Pikap, hoparlörler ve renkli ışıklar; seçtiğin plak evdekilere çalar."),
  kutlama: ç("Balonlar, flamalar, pasta ve konfeti."),
  sofra: ç("Örtülü sofra, tabaklar ve mumlar."),
};
// İkramın kalemi (3B'de tepside ve pay alanın elinde; mekânın ikram kalıpları ve pasta, 44_oda3b.js)
const PARTI_IKRAM = { sohbet: "cay", muzik: "atistirmalik", kutlama: "pasta", sofra: "kahvalti" };
const PARTI_IKRAM_AD = { sohbet: ç("çay ve simit"), muzik: ç("çerez"), kutlama: ç("pasta"), sofra: ç("sofra tabağı") };
// Temanın renkleri (flama, ışık, balon; 2B ve 3B)
const PARTI_RENK = { sohbet: ["#E2B54A", "#C0663E", "#F1E6D2"], muzik: ["#9B6BFF", "#3FD0FF", "#FF4FA3", "#FFD24F"],
  kutlama: ["#E5577A", "#F2C94C", "#5FB0D2", "#6F9B6A"], sofra: ["#C9A227", "#9C3F33", "#F1E6D2"] };
const PARTI_YANIT = { yes: ç("Geliyor"), no: ç("Gelemiyor") };
const PARTI_TERCIH = { everyone: ç("Arkadaşlarım ve tanıdıklarım"), friends: ç("Yalnız arkadaşlarım"), nobody: ç("Kimse") };
const partiTemaAdi = (t) => PARTI_TEMA[t] ?? String(t ?? "");

// Partinin masası: ikram tepsisi ve temanın süsü ilk uygun masanın üstünde; masa yoksa pencerenin denizliğinde (null)
const PARTI_MASA_SIRA = ["yemek_masasi", "sehpa", "kahve_masasi", "bar_masasi", "tavla_masasi", "calisma_masasi"];
function partiMasasi(items, catalog) {
  const k = new Map((catalog ?? []).map((c) => [c.id, c]));
  for (const id of PARTI_MASA_SIRA) {
    const i = (items ?? []).findIndex((p) => p.i === id);
    const c = i >= 0 ? k.get(id) : null;
    if (!c) continue;
    const p = items[i], tek = p.r % 2 === 1, w = tek ? c.d : c.w, d = tek ? c.w : c.d;
    return { i, id, x: p.x + w / 2, z: p.z + d / 2, w, d };
  }
  return null;
}

const EvPartisi = (() => {
  const durum = () => Sunucu.cagir("home_parties");
  const kur = (tema, bas, saat, davetli, plak) => Sunucu.yap("home_party_create", { p_theme: tema, p_starts_at: bas, p_hours: saat,
    p_invitees: davetli, p_ep: plak });
  const davet = (parti, kisiler) => Sunucu.yap("home_party_invite", { p_party: parti, p_invitees: kisiler });
  const davetGeri = (parti, kisi) => Sunucu.yap("home_party_uninvite", { p_party: parti, p_character: kisi });
  const yanit = (parti, evet) => Sunucu.yap("home_party_reply", { p_party: parti, p_yes: evet });
  const simdi = (parti) => Sunucu.yap("home_party_start_now", { p_party: parti });
  const bitir = (parti) => Sunucu.yap("home_party_cancel", { p_party: parti });
  const plak = (parti, ep) => Sunucu.yap("home_party_music", { p_party: parti, p_ep: ep });
  const tepsi = (parti) => Sunucu.yap("home_party_tray", { p_party: parti });
  const al = () => Sunucu.yap("home_party_take");
  const tercih = (p) => Sunucu.cagir("party_invite_settings_set", { p_policy: p });
  return { durum, kur, davet, davetGeri, yanit, simdi, bitir, plak, tepsi, al, tercih };
})();

// ---------- Plak: evdekilere çalan EP (ezgi; C-2). Tarayıcı sesi ancak dokununca açar: "Müziği dinle"den sonra ev sahibi
// plağı değiştirince yenisi kendiliğinden çalar; plak durunca ya da parti bitince susar. ----------
const PartiMuzik = (() => {
  let istek = null;   // dinlenen partinin kimliği (kişi "dinle" dedi)
  const kimlik = (p) => `parti:${p.party_id}:${p.music?.ep_id ?? ""}:`;
  function cal(p, sira) {
    const l = p.music?.tracks_list ?? [];
    if (!l.length) return;
    const n = sira % l.length, t = l[n].play ?? {};
    Ezgi.cal({ kimlik: kimlik(p) + n, seed: Number(t.seed), genre: t.genre, tempo: Number(t.tempo), key_no: Number(t.key_no),
      sonra: () => { if (istek === p.party_id) cal(p, n + 1); } }).catch(() => {});
  }
  const caliyor = (p) => !!p?.music && String(Ezgi.calan ?? "").startsWith(kimlik(p));
  function durdur() {
    istek = null;
    if (String(Ezgi.calan ?? "").startsWith("parti:")) Ezgi.durdur();
  }
  return {
    caliyor,
    dinliyor: (p) => !!p && istek === p.party_id,
    dinle(p) { if (!p?.music) return; istek = p.party_id; cal(p, 0); },
    durdur,
    // Partinin durumu değişti (plak değişti, durdu, parti bitti ya da evden çıkıldı: p boş)
    guncelle(p) {
      if (!istek) return;
      if (!p || p.party_id !== istek) { durdur(); return; }
      if (!p.music) { if (String(Ezgi.calan ?? "").startsWith("parti:")) Ezgi.durdur(); return; }
      if (!caliyor(p)) cal(p, 0);
    },
  };
})();

// Partinin zamanı: bekleyende başlangıç, sürende bitişe kalan (geri sayım), kapananda tarih
function partiZamanHtml(p) {
  if (p.status === "live") return `${esc(ç("Sürüyor"))} · ${esc(ç("bitişe"))} <span data-bitis="${esc(p.ends_at)}"></span>`;
  if (p.status === "scheduled") return esc(ç("{zaman} başlıyor", { zaman: saatYaz(p.starts_at) }));
  return esc(saatYaz(p.started_at ?? p.starts_at));
}
const partiYanitCip = (x) => x.reply === "yes" ? `<span class="cip yesil" data-yanit="yes">${ikon("check")}${esc(PARTI_YANIT.yes)}</span>`
  : x.reply === "no" ? `<span class="cip" data-yanit="no">${ikon("x")}${esc(PARTI_YANIT.no)}</span>`
  : `<span class="cip" data-yanit="">${ikon("clock")}${esc(ç("Yanıt bekleniyor"))}</span>`;

// ---------- Parti kurma, davet ve plak pencereleri (Evim) ----------
// Davet edilebilenlerin listesi (onay kutuları): arkadaşlar önce, sonra tanıdıklar (yakınlık)
function partiAdayHtml(adaylar, secili = new Set()) {
  if (!adaylar.length) return `<p class="bos">${ç("Davet edebileceğin kimse yok: önce arkadaş edin ya da mekânlarda tanış.")}</p>`;
  return `<div class="koltuk-liste parti-adaylar">${adaylar.map((x) => `<label class="radyo parti-aday"><input type="checkbox" name="davetli" value="${esc(x.character_id)}" ${secili.has(x.character_id) ? "checked" : ""}>
      <span><b>${esc(x.name)}</b><span class="kucuk">${x.friend ? esc(ç("Arkadaşın")) : esc(ç("Tanıdık · yakınlık {n}", { n: sayi(x.points ?? 0) }))}</span></span></label>`).join("")}</div>`;
}
const partiSecilenler = (f) => $$("input[name=davetli]:checked", f).map((x) => x.value);

function partiKurPenceresi(v, sonra) {
  const R = v.rule ?? {};
  const yerel = (t) => { const z = new Date(t); z.setMinutes(z.getMinutes() - z.getTimezoneOffset()); return z.toISOString().slice(0, 16); };
  const en = Date.now() + 2 * 60000, son = Date.now() + Number(R.horizonDays ?? 7) * 86400e3 - 60000;
  const oneri = new Date(Date.now() + 3600e3);
  oneri.setMinutes(oneri.getMinutes() < 30 ? 30 : 60, 0, 0);
  const temalar = R.themes ?? Object.keys(PARTI_TEMA);
  const enCok = Number(R.maxInvites ?? 20);
  const pf = pencereForm({ ust: ç("Ev partisi"), baslik: ç("Parti kur"), onayAd: ç("Partiyi kur"), onayIkon: "party-popper",
    govde: `<fieldset class="alan"><legend>${ç("Tema")}</legend><div class="radyo-liste">${temalar.map((t, i) => `<label class="radyo"><input type="radio" name="tema" value="${esc(t)}" ${i === 0 ? "checked" : ""}>
          <span><b>${ikon(PARTI_TEMA_IK[t] ?? "party-popper")} ${esc(partiTemaAdi(t))}</b><span class="kucuk">${esc(PARTI_TEMA_SUS[t] ?? "")}</span></span></label>`).join("")}</div></fieldset>
      <fieldset class="alan"><legend>${ç("Ne zaman")}</legend><div class="radyo-liste birlik-yatay">
          <label class="radyo"><input type="radio" name="ne_zaman" value="simdi" checked><span><b>${ç("Şimdi")}</b></span></label>
          <label class="radyo"><input type="radio" name="ne_zaman" value="ileri"><span><b>${ç("İleri bir saatte")}</b></span></label></div>
        <input name="zaman" type="datetime-local" min="${yerel(en)}" max="${yerel(son)}" value="${yerel(oneri)}" aria-label="${ç("Başlangıç")}" style="margin-top:8px" disabled>
        <span class="kucuk">${esc(ç("En geç {n} gün sonrası.", { n: Number(R.horizonDays ?? 7) }))}</span></fieldset>
      <fieldset class="alan"><legend>${ç("Süre")}</legend><div class="radyo-liste birlik-yatay">${(R.hours ?? [1, 2, 3]).map((h, i) => `<label class="radyo"><input type="radio" name="saat" value="${Number(h)}" ${i === 1 ? "checked" : ""}><span><b>${esc(ç("{n} saat", { n: Number(h) }))}</b></span></label>`).join("")}</div></fieldset>
      <fieldset class="alan"><legend>${ç("Davetliler")}</legend>${partiAdayHtml(v.candidates ?? [])}
        <p class="kucuk" id="parti-secim">${esc(ç("{n} / {m} kişi seçildi", { n: 0, m: enCok }))}</p></fieldset>
      ${(v.eps ?? []).length ? `<label class="alan"><span>${ç("Plak")}</span><select name="plak"><option value="">${ç("Plak yok")}</option>${v.eps.map((e) => `<option value="${esc(e.ep_id)}">${esc(e.name)} — ${esc(e.band)}</option>`).join("")}</select></label>`
        : `<p class="kucuk">${ç("Koleksiyonunda plak yok; Sahne'deki Plak rafından EP alabilirsin. Partiyi plaksız da kurarsın.")}</p>`}
      <p class="kucuk">${esc(ç("Davetliye bildirim gider; parti sürerken davetlin kapın ne olursa olsun gelir. Süs, plak ve ikram güç vermez."))}</p>`,
    is: async (d, f) => {
      const ileri = d.get("ne_zaman") === "ileri";
      let bas = null;
      if (ileri) {
        const t = Date.parse(String(d.get("zaman") ?? ""));
        if (!Number.isFinite(t)) throw new Error(ç("Başlangıç saatini seç."));
        bas = new Date(t).toISOString();
      }
      const davetli = partiSecilenler(f);
      if (davetli.length > enCok) throw new Error(ç("En çok {n} kişi davet edebilirsin.", { n: enCok }));
      const r = await EvPartisi.kur(d.get("tema"), bas, Number(d.get("saat")), davetli, d.get("plak") || null);
      tost(r.status === "live" ? ç("Parti başladı: {tema}.", { tema: partiTemaAdi(r.theme) })
        : ç("Parti kuruldu: {tema}, {zaman}.", { tema: partiTemaAdi(r.theme), zaman: saatYaz(r.starts_at) }), "party-popper");
      await sonra?.();
    } });
  const f = pf.form;
  const zaman = $("input[name=zaman]", f);
  for (const r of $$("input[name=ne_zaman]", f)) r.onchange = () => { zaman.disabled = $("input[name=ne_zaman]:checked", f)?.value !== "ileri"; };
  const say = () => { const n = partiSecilenler(f).length; $("#parti-secim", f).textContent = ç("{n} / {m} kişi seçildi", { n, m: enCok }); };
  for (const k of $$("input[name=davetli]", f)) k.onchange = say;
  return pf;
}

function partiDavetPenceresi(v, p, sonra) {
  const davetli = new Set((p.invites ?? []).map((x) => x.character_id));
  const adaylar = (v.candidates ?? []).filter((x) => !davetli.has(x.character_id));
  const kalan = Math.max(0, Number(v.rule?.maxInvites ?? 20) - Number(p.invited ?? 0));
  return pencereForm({ ust: partiTemaAdi(p.theme), baslik: ç("Davet et"), onayAd: ç("Davet et"), onayIkon: "user-round-plus",
    govde: `${partiAdayHtml(adaylar)}<p class="kucuk">${esc(ç("{n} kişi daha davet edebilirsin.", { n: kalan }))}</p>`,
    is: async (d, f) => {
      const l = partiSecilenler(f);
      if (!l.length) throw new Error(ç("Davet edeceğin kişiyi seç."));
      const r = await EvPartisi.davet(p.party_id, l);
      tost(ç("{n} kişi davet edildi.", { n: Number(r.added ?? l.length) }), "user-round-plus");
      await sonra?.();
    } });
}

function partiPlakPenceresi(v, p, sonra) {
  const l = v.eps ?? [];
  return pencereForm({ ust: partiTemaAdi(p.theme), baslik: ç("Plak"), onayAd: ç("Çal"), onayIkon: "disc-3",
    govde: `<div class="radyo-liste">${[{ ep_id: "", name: ç("Plağı durdur"), band: "" }, ...l].map((e) => `<label class="radyo"><input type="radio" name="plak" value="${esc(e.ep_id)}" ${(p.music?.ep_id ?? "") === e.ep_id ? "checked" : ""}>
        <span><b>${ikon(e.ep_id ? "disc-3" : "x")} ${esc(e.name)}</b>${e.band ? `<span class="kucuk">${esc(e.band)}${e.own_band ? " · " + esc(ç("grubunun")) : ""}</span>` : ""}</span></label>`).join("")}</div>
      ${l.length ? "" : `<p class="kucuk">${ç("Koleksiyonunda plak yok; Sahne'deki Plak rafından EP alabilirsin.")}</p>`}`,
    is: async (d) => {
      const ep = d.get("plak") || null;
      await EvPartisi.plak(p.party_id, ep);
      tost(ep ? ç("Plak çalıyor: {ad}.", { ad: l.find((e) => e.ep_id === ep)?.name ?? "" }) : ç("Plak durdu."), "disc-3");
      await sonra?.();
    } });
}

// ---------- Evim: parti kartı ----------
// EvPartisiKart.ac(yer): kart çizilir; partinin olaylarında (homeparty.*) ve dakikada bir tazelenir. Dönen işlev bırakır.
const EvPartisiKart = (() => {
  function ac(yer) {
    let v = null, kapandi = false, sayac = null, hata = null;
    async function yukle() {
      try { v = await EvPartisi.durum(); hata = null; } catch (e) { hata = e; }
    }
    function davetliler(p) {
      const l = p.invites ?? [];
      if (!l.length) return `<p class="kucuk" id="parti-davetliler" data-n="0">${ç("Henüz davetli yok.")}</p>`;
      return `<div class="koltuk-liste" id="parti-davetliler" data-n="${l.length}">${l.map((x) => `<div class="koltuk" data-parti-davetli="${esc(x.character_id)}" data-yanit="${esc(x.reply ?? "")}">${avatarKutu(x.name, x.character_id)}
          <div><button class="baglanti" data-profil="${esc(x.character_id)}"><b>${esc(x.name)}</b></button>
            <div class="kucuk">${esc(x.friend ? ç("Arkadaşın") : ç("Tanıdık"))}${x.came ? " · " + esc(ç("geldi")) : ""}</div></div>
          <span class="satir" style="gap:6px;flex-wrap:wrap;justify-content:flex-end">${partiYanitCip(x)}
            <button class="dugme sade kucuk-d" data-parti-geri="${esc(x.character_id)}" aria-label="${esc(ç("Daveti geri al: {ad}", { ad: x.name }))}" title="${esc(ç("Daveti geri al"))}">${ikon("x")}</button></span></div>`).join("")}</div>`;
    }
    function ciz() {
      if (kapandi) return;
      sayac?.();
      sayac = null;
      if (!v) {
        yer.innerHTML = hata ? `<section class="kart"><div class="hata-kutusu">${ikon("circle-alert")}<span>${esc(hataMetni(hata))}</span></div></section>` : "";
        return;
      }
      const R = v.rule ?? {}, p = v.mine;
      const tepsiErzak = Number(R.tray?.erzak ?? 2);
      let govde;
      if (!p) {
        const son = (v.recent ?? []).slice(0, 3);
        const dolu = Number(v.week ?? 0) >= Number(R.perWeek ?? 3);
        govde = `<p class="aciklama">${ç("Arkadaşlarını ve tanıdıklarını evine çağır: temaya göre süsler, plak ve ikram. Parti sürerken davetlilerin kapın kapalı olsa da gelir.")}</p>
          <div class="oneri-dugmeler" style="margin-top:12px"><button class="dugme altin kucuk-d" id="parti-kur" ${dolu ? "disabled" : ""}>${ikon("party-popper")}${ç("Parti kur")}</button></div>
          <p class="kucuk" style="margin-top:8px">${esc(ç("Son 7 günde {n} / {m} parti.", { n: Number(v.week ?? 0), m: Number(R.perWeek ?? 3) }))}${dolu ? " " + esc(ç("Haftanın sınırı doldu; biraz sonra yeniden kurabilirsin.")) : ""}</p>
          ${son.length ? `<div class="liste" id="parti-gecmis" style="margin-top:10px">${son.map((x) => `<div class="liste-satir" data-parti-gecmis="${esc(x.status)}"><span class="liste-ikon">${ikon(PARTI_TEMA_IK[x.theme] ?? "party-popper")}</span>
              <div><span class="tur">${esc(saatYaz(x.started_at ?? x.starts_at))}</span><b>${esc(partiTemaAdi(x.theme))}</b>
                <div class="alt">${esc(x.status === "cancelled" ? ç("İptal edildi") : ç("{n} misafir geldi · {p} pay ikram edildi", { n: sayi(x.guests ?? 0), p: sayi(x.portions_taken ?? 0) }))}</div></div><span></span></div>`).join("")}</div>` : ""}`;
      } else {
        const canli = p.status === "live";
        govde = `<p class="parti-zaman" data-parti-durum="${esc(p.status)}">${ikon(canli ? "party-popper" : "calendar")}<span>${partiZamanHtml(p)}</span></p>
          <div class="bilgi-izgara">
            <div><small>${ç("Süre")}</small><b>${esc(ç("{n} saat", { n: Number(p.hours) }))}</b></div>
            <div><small>${ç("Davetli")}</small><b id="parti-sayilar">${esc(ç("{n} kişi · {m} geliyor", { n: sayi(p.invited ?? 0), m: sayi(p.coming ?? 0) }))}</b></div>
            ${canli ? `<div><small>${ç("Evde")}</small><b>${esc(ç("{n} kişi", { n: sayi(p.inside ?? 0) }))}</b></div>
              <div><small>${ç("İkram")}</small><b id="parti-ikram" data-kalan="${Number(p.portions_left ?? 0)}">${esc(ç("{n} pay · {t} / {m} tepsi", { n: sayi(p.portions_left ?? 0), t: Number(p.trays ?? 0), m: Number(R.tray?.maxTrays ?? 4) }))}</b></div>` : ""}
          </div>
          <p class="kucuk" id="parti-plak">${ikon("disc-3")} ${p.music ? esc(ç("Plak: {ad} — {grup}", { ad: p.music.name, grup: p.music.band })) : esc(ç("Plak yok"))}</p>
          <div class="oneri-dugmeler" style="margin-top:12px">
            ${p.status === "scheduled" ? `<button class="dugme altin kucuk-d" id="parti-simdi">${ikon("play")}${ç("Şimdi başlat")}</button>` : ""}
            ${canli ? `<button class="dugme altin kucuk-d" id="parti-tepsi" ${Number(p.trays ?? 0) >= Number(R.tray?.maxTrays ?? 4) ? "disabled" : ""}>${ikon("croissant")}${esc(ç("İkram koy ({n} erzak)", { n: tepsiErzak }))}</button>` : ""}
            <button class="dugme ikincil kucuk-d" id="parti-plak-sec">${ikon("disc-3")}${ç("Plak")}</button>
            <button class="dugme ikincil kucuk-d" id="parti-davet">${ikon("user-round-plus")}${ç("Davet et")}</button>
            <button class="dugme sade kucuk-d" id="parti-bitir">${ikon("x")}${canli ? ç("Partiyi bitir") : ç("İptal et")}</button></div>
          ${canli ? `<p class="kucuk" style="margin-top:8px">${esc(ç("Çantanda {n} erzak. Bir tepsi {p} pay; misafir tepsiden en çok {k} pay alır.", { n: sayi(v.erzak ?? 0), p: Number(R.tray?.portions ?? 6), k: Number(R.tray?.perGuest ?? 2) }))}</p>` : ""}
          <p class="ust-yazi" style="margin-top:14px">${ç("Davetliler")}</p>${davetliler(p)}`;
      }
      yer.innerHTML = `<section class="kart parti-kart" id="parti-kart" data-parti="${esc(p?.status ?? "")}" data-tema="${esc(p?.theme ?? "")}">
        <div class="kart-bas"><div><p class="ust-yazi">${ç("Ev partisi")}</p><h2 class="b2">${p ? esc(partiTemaAdi(p.theme)) : ç("Parti ver")}</h2></div>
          <span class="ik-kutu">${ikon(p ? PARTI_TEMA_IK[p.theme] ?? "party-popper" : "party-popper")}</span></div>
        ${govde}
        <p class="kucuk" style="margin-top:10px">${esc(ç("Parti süstür: güç, gelir ya da oy vermez. Aynı evde en az {n} dakika birlikte kalanların yakınlığı artar.", { n: Number(v.party_minutes ?? 15) }))}</p>
      </section>`;
      bagla(p);
      if (p?.status === "live") sayac = geriSay(yer, () => tazele());
    }
    function isle(dugme, fn) {
      return async () => {
        if (dugme) dugme.disabled = true;
        try { await fn(); } catch (e) { tost(hataMetni(e), "circle-alert"); }
        await tazele();
      };
    }
    function bagla(p) {
      $("#parti-kur", yer)?.addEventListener("click", () => partiKurPenceresi(v, tazele));
      for (const b of $$("[data-profil]", yer)) b.onclick = () => profilAc(b.dataset.profil, tazele);
      if (!p) return;
      const sm = $("#parti-simdi", yer);
      sm?.addEventListener("click", isle(sm, async () => { await EvPartisi.simdi(p.party_id); tost(ç("Parti başladı: {tema}.", { tema: partiTemaAdi(p.theme) }), "party-popper"); }));
      const tp = $("#parti-tepsi", yer);
      tp?.addEventListener("click", isle(tp, async () => {
        const r = await EvPartisi.tepsi(p.party_id);
        tost(ç("İkram tepsisi kondu: tepside {n} pay.", { n: sayi(r.portions_left ?? 0) }), "croissant");
        Durum.ozet().catch(() => {});
      }));
      $("#parti-plak-sec", yer)?.addEventListener("click", () => partiPlakPenceresi(v, p, tazele));
      $("#parti-davet", yer)?.addEventListener("click", () => partiDavetPenceresi(v, p, tazele));
      $("#parti-bitir", yer)?.addEventListener("click", () => {
        const canli = p.status === "live";
        pencere({ ust: partiTemaAdi(p.theme), baslik: canli ? ç("Partiyi bitir") : ç("Partiyi iptal et"),
          govde: `<p class="aciklama">${esc(canli ? ç("Parti şimdi biter; davetli olup kapının izin vermediği misafirler evden çıkar. Tepside kalan ikram geri gelmez.")
            : ç("Davetlilere iptal bildirimi gider. İptal edilen parti de haftanın sayısına girer."))}</p>`,
          dugmeler: [{ ad: ç("Vazgeç") }, { ad: canli ? ç("Partiyi bitir") : ç("İptal et"), sinif: "mercan", ikon: "x", is: isle(null, async () => {
            await EvPartisi.bitir(p.party_id);
            tost(canli ? ç("Parti bitti.") : ç("Parti iptal edildi."), "party-popper");
          }) }] });
      });
      for (const b of $$("[data-parti-geri]", yer)) b.onclick = isle(b, async () => {
        await EvPartisi.davetGeri(p.party_id, b.dataset.partiGeri);
        tost(ç("Davet geri alındı."), "x");
      });
    }
    const tazele = tazeleyici(async () => { await yukle(); ciz(); });
    tazele();
    const b1 = Durum.dinle("olay", ({ olay }) => { if (/^(homeparty\.|house\.|bond\.)/.test(olay)) tazele(); });
    const saat = setInterval(() => { if (!document.hidden && !kapandi) tazele(); }, 60000);
    return () => { kapandi = true; b1(); clearInterval(saat); sayac?.(); };
  }
  return { ac };
})();

// ---------- Arkadaşlar: Davetlerin ----------
function partiDavetlerHtml(l) {
  if (!l?.length) return "";
  return `<section class="kart" id="ark-davetler"><div class="kart-bas"><div><p class="ust-yazi">${ç("Ev partileri")}</p><h2 class="b2">${ç("Davetlerin")}</h2></div><span class="ik-kutu">${ikon("party-popper")}</span></div>
    <div class="liste">${l.map((p) => {
      const burada = (Durum.v.ozet?.character?.location ?? null) === p.region_id;
      const canli = p.status === "live";
      return `<div class="liste-satir parti-davet" data-parti-davet="${esc(p.party_id)}" data-durum="${esc(p.status)}" data-yanit="${esc(p.reply ?? "")}">
        <span class="liste-ikon ${canli ? "mercan" : "altin"}">${ikon(PARTI_TEMA_IK[p.theme] ?? "party-popper")}</span>
        <div><span class="tur">${esc(partiTemaAdi(p.theme))} · ${esc(bolgeAdi(p.region_id))}</span><b>${esc(ç("{ad} partisi", { ad: p.host_name ?? "" }))}</b>
          <div class="alt">${partiZamanHtml(p)} · ${esc(ç("{n} kişi geliyor", { n: sayi(p.coming ?? 0) }))}</div>
          <div class="satir" style="gap:6px;flex-wrap:wrap;margin-top:6px">
            <button class="dugme ${p.reply === "yes" ? "" : "ikincil"} kucuk-d" data-parti-evet="${esc(p.party_id)}" aria-pressed="${p.reply === "yes"}">${ikon("check")}${ç("Geliyorum")}</button>
            <button class="dugme ${p.reply === "no" ? "" : "ikincil"} kucuk-d" data-parti-hayir="${esc(p.party_id)}" aria-pressed="${p.reply === "no"}">${ikon("x")}${ç("Gelemem")}</button>
            ${canli ? (burada ? `<button class="dugme altin kucuk-d" data-parti-git="${esc(p.party_id)}">${ikon("door-open")}${ç("Partiye git")}</button>`
              : `<button class="dugme sade kucuk-d" data-parti-yol="${esc(p.region_id)}">${ikon("route")}${esc(ç("{sehir} şehrine git", { sehir: bolgeAdi(p.region_id) }))}</button>`) : ""}</div></div>
        <span></span></div>`;
    }).join("")}</div>
    <p class="kucuk">${ç("Parti sürerken davetlisi olduğun evin kapısı sana açıktır; partinin şehrinde olmalısın.")}</p></section>`;
}
function partiDavetlerBagla(kap, l, sonra) {
  const bul = (id) => (l ?? []).find((x) => x.party_id === id);
  const yanitla = (b, evet) => async () => {
    b.disabled = true;
    try {
      await EvPartisi.yanit(b.dataset.partiEvet ?? b.dataset.partiHayir, evet);
      tost(evet ? ç("Geleceğini bildirdin.") : ç("Gelemeyeceğini bildirdin."), "party-popper");
    } catch (e) { tost(hataMetni(e), "circle-alert"); }
    await sonra?.();
  };
  for (const b of $$("[data-parti-evet]", kap)) b.onclick = yanitla(b, true);
  for (const b of $$("[data-parti-hayir]", kap)) b.onclick = yanitla(b, false);
  for (const b of $$("[data-parti-git]", kap)) b.onclick = () => { const p = bul(b.dataset.partiGit); if (p) EvYolu.git(p.host_id, p.host_name); };
  for (const b of $$("[data-parti-yol]", kap)) b.onclick = () => seyahatSor(b.dataset.partiYol, sonra);
  const el = $("#ark-davetler", kap);
  return el ? geriSay(el) : () => {};
}

// ---------- Evin içi: parti bandı (OdaPaneli'nin ziyaret bloğunun başında; 33_oda.js) ----------
function partiBandHtml(p) {
  if (!p) return "";
  const mine = !!p.mine;
  const kalan = Number(p.portions_left ?? 0), benim = Number(p.my_portions ?? 0), enCok = Number(p.rule?.tray?.perGuest ?? 2);
  const c = PartiMuzik.caliyor(p);
  const muzik = p.music ? `<button class="dugme ${c ? "" : "ikincil"} kucuk-d" data-parti-muzik aria-pressed="${c}">${ikon(c ? "pause" : "play")}${c ? ç("Müziği durdur") : ç("Müziği dinle")}</button>` : "";
  const ikram = mine ? ""
    : kalan > 0 && benim < enCok ? `<button class="dugme altin kucuk-d" data-parti-al>${ikon("croissant")}${esc(ç("İkram al ({n} pay)", { n: sayi(kalan) }))}</button>`
    : Number(p.trays ?? 0) > 0 ? `<span class="kucuk" data-parti-pay="${benim >= enCok ? "aldin" : "bitti"}">${esc(benim >= enCok ? ç("Payını aldın.") : ç("Tepside pay kalmadı."))}</span>` : "";
  return `<div class="parti-bant" id="oda-parti" data-parti-tema="${esc(p.theme)}" data-muzik="${p.music ? "1" : "0"}" data-kalan="${kalan}" data-benim="${benim}">
    <span class="ik-kutu">${ikon(PARTI_TEMA_IK[p.theme] ?? "party-popper")}</span>
    <div class="parti-bant-yazi"><b>${esc(partiTemaAdi(p.theme))} · ${esc(mine ? ç("Partin sürüyor") : ç("{ad} partisi", { ad: p.host_name ?? "" }))}</b>
      <span class="kucuk">${esc(ç("bitişe"))} <span data-bitis="${esc(p.ends_at)}"></span>${p.music ? " · " + esc(ç("Plak: {ad}", { ad: p.music.name ?? "" })) : ""}${Number(p.trays ?? 0) > 0 ? " · " + esc(ç("İkram: {n} pay", { n: sayi(kalan) })) : ""}</span></div>
    <div class="parti-bant-dugmeler">${muzik}${ikram}</div></div>`;
}
// Bandın düğmeleri: müzik (dinle ya da durdur), ikram al. yenile: durumu yeniden ister (EvZiyareti.durumIste)
function partiBandBagla(kok, p, yenile) {
  const m = $("[data-parti-muzik]", kok);
  if (m) m.onclick = () => { if (PartiMuzik.caliyor(p)) PartiMuzik.durdur(); else PartiMuzik.dinle(p); };
  const a = $("[data-parti-al]", kok);
  if (a) a.onclick = async () => {
    a.disabled = true;
    try {
      const r = await EvPartisi.al();
      tost(ç("Bir pay aldın: {kalem}.", { kalem: PARTI_IKRAM_AD[p.theme] ?? "" }) + keyifEki(r, "portion"), "croissant");
    } catch (e) { tost(hataMetni(e), "circle-alert"); }
    yenile?.();
  };
}

// ===== 98zj_saglik3b.js =====
// ---------- Şehrin sağlık ocağı (D-143): 3B yaşayan sahne ya da hafif 2B ----------
// Arkada üç muayene odası (bölmeli): masa ve ekran, doktorun koltuğu, muayene sedyesi, kalp ekranı ve perde. Nöbetteki doktor
// (kendi görünümüyle, beyaz önlük ve steteskopla) masasında oturur; muayene saati gelmiş hastası varsa sedyenin yanında ayakta
// muayene eder, hasta sedyede oturur, kalp ekranının çizgisi atar. Önde bekleme salonu: iki sıra sandalye; sıradakiler
// (kimliksiz) oturup bekler, sıran bu şehirdeyse sen de (kendi görünümünle) ön sırada; muayene saatin gelince sedyedesin. Sağ
// duvarda sıra ekranı (bekleyen sayısı, sıradaki muayene saati), sol duvarda yorgunluk panosu (yorgunluğun ve kendiliğinden
// düşüşü). Nöbetçi yoksa odaların ışığı loş, tabelalar "Nöbetçi yok". Doktora dokununca profili, odaya dokununca o nöbetin
// kartı, sandalyelere ya da sıra ekranına dokununca sıra, panoya dokununca yorgunluk kartı. Yaşayan sahne (D-110): yalnız
// ekrandayken; masaüstünde 30, telefonda 20 kare/sn; hareket azaltılmışsa duruk. Gece ve gündüz şehrin gerçek güneşiyle.

const SAGLIK_ODA_X = [-3.05, 0, 3.05];   // üç muayene odası (fazlası tabelada sayıyla)
const SAGLIK_OLCEK = 0.66;               // tam figür (doktor, sen)
const SAGLIK_KALABALIK = 0.92;           // sıradakiler (kimliksiz)
// Bekleme salonunun sandalyeleri (iki sıra, kameraya dönük); ilki senin yerin
const SAGLIK_SANDALYE = [[-1.2, 0.55], [0, 0.55], [1.2, 0.55], [-2.4, 0.55], [2.4, 0.55], [-1.8, 1.75], [-0.6, 1.75], [0.6, 1.75], [1.8, 1.75], [-3.0, 1.75]];
const SAGLIK_OTURAK = 0.26, SAGLIK_SEDYE = 0.44;

// api.clinic ve kişinin kendisinden sahnenin verisi (3B ve 2B aynı veriyi çizer)
function saglikVerisi(c, ben) {
  const nobetler = c?.shifts ?? [];
  const simdi = Date.now();
  const benim = c?.my_visit && c.my_visit.region_id === c.region_id ? c.my_visit : null;
  const sedyede = !!benim && Date.parse(benim.slot_starts_at) <= simdi;
  const doktorlar = nobetler.slice(0, SAGLIK_ODA_X.length).map((s) => ({
    id: s.shift_id, kisi: s.doctor_id, ad: s.doctor ?? "", gorunus: s.doctor_look?.look ?? null, ulke: s.doctor_look?.country_id ?? null,
    tip: Number(s.skill ?? 0), etki: Number(s.relief ?? 0), sira: Number(s.queue ?? 0), ucret: Number(s.fee_cr ?? 0),
    // Muayene sürüyor: saati gelmiş hasta (sunucu dakikalık işte yapar); benimse sedyedeki benim
    muayene: !!s.treating || (sedyede && benim?.shift_id === s.shift_id), ben: !!s.mine, benimSiram: benim?.shift_id === s.shift_id,
  }));
  const muayenede = doktorlar.filter((x) => x.muayene).length;
  const bekleyen = nobetler.reduce((a, s) => a + Number(s.queue ?? 0), 0);
  // Sıradaki muayene saati: nöbetlerin sıradaki boş saatlerinin en erkeni ya da benim saatim
  const saatler = nobetler.map((s) => s.next_slot?.starts_at).filter(Boolean).map(Date.parse);
  return {
    anahtar: c?.region_id ?? "", sehir: c?.region_id ? bolgeAdi(c.region_id) : "", gece: c?.region_id ? bolgeGecesi(c.region_id) : 0,
    doktorlar, fazla: Math.max(0, nobetler.length - SAGLIK_ODA_X.length), bekleyen, muayenede,
    // Salonda oturanlar: sıradakiler (sedyedekiler ve ben düşülür)
    salon: Math.max(0, bekleyen - muayenede - (benim && !sedyede ? 1 : 0)),
    ben: { id: ben?.id ?? "", ad: ben?.ad ?? "", gorunus: ben?.gorunus ?? null, ulke: ben?.ulke ?? null, sirada: !!benim && !sedyede, sedyede,
      doktor: doktorlar.some((x) => x.ben), saat: benim?.slot_starts_at ?? null },
    siradaki: benim?.slot_starts_at ?? (saatler.length ? new Date(Math.min(...saatler)).toISOString() : null),
    yorgunluk: Number(c?.fatigue?.points ?? 0), tavan: Number(c?.fatigue?.max ?? 100), esik: Number(c?.fatigue?.tired_at ?? 60),
    donem: Number(c?.fatigue?.period_ms ?? 900000),
  };
}

// ---------- 2B: sağlık ocağının önden görünüşü (SVG) ----------
// Arka duvar boyunca üç muayene odası (tabela, masa ve ekran, sedye, kalp ekranı, perde); önde bekleme salonu (kameraya dönük iki
// sıra sandalye), solda yorgunluk panosu, sağda sıra ekranı ve danışma. Figürün konumu dış grupta, CSS kıpırtısı iç grupta
// (CSS dönüşümü SVG'nin konumunu ezmesin).
const SAGLIK2B_SANDALYE = [[340, 286], [270, 286], [410, 286], [200, 286], [480, 286], [235, 348], [305, 348], [375, 348], [445, 348], [515, 348]];
function saglik2b(d) {
  const g0 = Math.round((d.gece ?? 0) * 20) / 20;
  const karis = (a, b, t) => epRenkKaris(a, b, t);
  const acik = d.doktorlar.length > 0;
  // Ayakta kişi (ayakları y'de); önlüklü doktor
  const kisi = (x, y, giysi, ten, sinif = "", veri = "", olcek = 1, onluk = false) => `<g transform="translate(${x.toFixed(1)} ${y.toFixed(1)}) scale(${olcek})" ${veri}>
      <g class="saglik2b-kisi ${sinif}"><rect x="-6.5" y="-11" width="5" height="11" rx="2" fill="#3B3B44"/><rect x="1.5" y="-11" width="5" height="11" rx="2" fill="#3B3B44"/>
      <rect class="govde" x="-9" y="-34" width="18" height="25" rx="6" fill="${onluk ? "#F6F7F3" : giysi}"${onluk ? ' stroke="#C9D4D0" stroke-width="1"' : ""}/>
      ${onluk ? `<rect x="-2.5" y="-33" width="5" height="17" fill="${giysi}"/><path d="M-5.5 -32 q5.5 10 11 0" stroke="#33383E" stroke-width="1.6" fill="none"/><circle cx="4" cy="-22" r="2" fill="#C9CED6"/>` : ""}
      <circle cy="-43" r="9" fill="${ten}"/></g></g>`;
  // Oturan kişi (oturağın üstü y'de; kameraya dönük): gövde, sarkan bacaklar, baş
  const oturan = (x, y, giysi, ten, sinif = "", veri = "", olcek = 1) => `<g transform="translate(${x.toFixed(1)} ${y.toFixed(1)}) scale(${olcek})" ${veri}>
      <g class="saglik2b-kisi ${sinif}"><rect x="-7" y="-2" width="6" height="16" rx="2" fill="#3B3B44"/><rect x="1" y="-2" width="6" height="16" rx="2" fill="#3B3B44"/>
      <rect class="govde" x="-9" y="-27" width="18" height="25" rx="6" fill="${giysi}"/><circle cy="-36" r="9" fill="${ten}"/></g></g>`;
  const odalar = [0, 1, 2].map((i) => {
    const k = d.doktorlar[i];
    const x0 = 30 + i * 216;
    const r = k ? meydanKisiRenk(k.gorunus, k.ad) : null;
    const tabela = k ? esc(String(k.ad).slice(0, 20)) : esc(ç("Nöbetçi yok"));
    const yatan = !k?.muayene ? "" : k.benimSiram && d.ben.sedyede
      ? (() => { const b = meydanKisiRenk(d.ben.gorunus, d.ben.ad); return oturan(x0 + 150, 160, b.giysi, b.ten, "hasta ben", 'data-saglik-sec="ben"', 0.95); })()
      : oturan(x0 + 150, 160, KALABALIK_GIYSI[(i * 3 + 2) % KALABALIK_GIYSI.length], KALABALIK_TEN[(i * 2 + 1) % KALABALIK_TEN.length], "hasta", "", 0.9);
    const doktor = !k ? "" : k.muayene ? kisi(x0 + 112, 198, r.giysi, r.ten, "doktor muayene" + (k.ben ? " ben" : ""), `data-saglik-kisi="${esc(k.kisi)}"`, 1.1, true)
      : kisi(x0 + 48, 186, r.giysi, r.ten, "doktor" + (k.ben ? " ben" : ""), `data-saglik-kisi="${esc(k.kisi)}"`, 1.05, true);
    return `<g class="saglik2b-oda saglik2b-tik${k ? " dolu" : ""}" data-saglik-oda="${esc(k?.id ?? "")}" data-saglik-sec="${k ? "doktor" : "oda"}">
      <rect x="${x0}" y="36" width="208" height="164" fill="${karis(k ? "#EEF5F2" : "#DCE3E0", "#2C3438", g0 * 0.55)}"/>
      <rect x="${x0 + 18}" y="44" width="172" height="24" rx="5" fill="${k ? "#2E8C83" : "#8A9894"}"/>
      <text x="${x0 + 104}" y="60" text-anchor="middle" font-size="11" font-weight="800" fill="#FFFFFF">${tabela}</text>
      ${k ? `<text x="${x0 + 104}" y="84" text-anchor="middle" font-size="9.5" fill="${karis("#35524C", "#B9CBC6", g0)}">${esc(ç("Tıp {n} · −{e} yorgunluk", { n: k.tip, e: k.etki }))}</text>` : ""}
      <rect x="${x0 + 180}" y="98" width="24" height="17" rx="2" fill="#1E2A30"/><rect x="${x0 + 191}" y="115" width="2.5" height="83" fill="#AEB6BC"/>
      <path d="M${x0 + 182} 107 h4 l2 -5 l2 10 l2 -5 h10" stroke="${k?.muayene ? "#7FE0A8" : "#3D5560"}" stroke-width="1.5" fill="none" class="${k?.muayene ? "saglik2b-nabiz" : ""}"/>
      <rect x="${x0 + 104}" y="170" width="74" height="4" fill="#8C9AA3"/><rect x="${x0 + 108}" y="174" width="3" height="24" fill="#AEB6BC"/><rect x="${x0 + 171}" y="174" width="3" height="24" fill="#AEB6BC"/>
      <rect x="${x0 + 104}" y="160" width="74" height="10" rx="3" fill="#C9D9E3"/><rect x="${x0 + 160}" y="154" width="18" height="8" rx="3" fill="#FFFFFF"/>
      ${yatan}
      ${!k?.muayene ? doktor : ""}
      <rect x="${x0 + 10}" y="172" width="76" height="7" rx="2" fill="#B9A58A"/><rect x="${x0 + 14}" y="179" width="4" height="19" fill="#8A7660"/><rect x="${x0 + 78}" y="179" width="4" height="19" fill="#8A7660"/>
      <rect x="${x0 + 22}" y="156" width="22" height="15" rx="1.5" fill="#2B3540"/><rect x="${x0 + 25}" y="159" width="16" height="9" fill="${k ? "#2F8FB5" : "#1B3A4A"}"/>
      ${k?.muayene ? doktor : ""}
      <rect x="${x0 + 196}" y="58" width="9" height="140" rx="2" fill="#9FC6D9"/></g>`;
  }).join("");
  // Bölmeler
  const bolme = [238, 454].map((x) => `<rect x="${x}" y="30" width="8" height="170" fill="${karis("#C7D3CF", "#3A4448", g0 * 0.55)}"/>`).join("");
  // Bekleme salonu: sandalye arkalığı, oturan, oturağın önü (önden görünüş)
  const salon = Math.min(SAGLIK2B_SANDALYE.length - 1, d.salon);
  const br = meydanKisiRenk(d.ben.gorunus, d.ben.ad);
  const sandalyeler = SAGLIK2B_SANDALYE.map(([x, y], i) => {
    let kisiYaz = "";
    if (i === 0 && d.ben.sirada && !d.ben.doktor) kisiYaz = oturan(x, y - 2, br.giysi, br.ten, "ben bekler", 'data-saglik-sec="ben"', 1);
    else if (i >= 1 && i <= salon) kisiYaz = oturan(x, y - 2, KALABALIK_GIYSI[(i * 3 + 1) % KALABALIK_GIYSI.length], KALABALIK_TEN[(i * 5 + 2) % KALABALIK_TEN.length], "bekler", "", 0.95);
    return `<rect x="${x - 15}" y="${y - 34}" width="30" height="28" rx="4" fill="#256F68"/>${kisiYaz}<rect x="${x - 17}" y="${y - 4}" width="34" height="7" rx="2" fill="#2E8C83"/>
      <rect x="${x - 14}" y="${y + 3}" width="3" height="16" fill="#AEB6BC"/><rect x="${x + 11}" y="${y + 3}" width="3" height="16" fill="#AEB6BC"/>`;
  }).join("");
  const benKapi = d.ben.doktor || d.ben.sedyede || d.ben.sirada || !d.ben.id ? "" : kisi(350, 374, br.giysi, br.ten, "ben", 'data-saglik-sec="ben"', 1.1);
  const yuzde = Math.max(0, Math.min(1, d.yorgunluk / Math.max(1, d.tavan)));
  const yorgun = d.yorgunluk >= d.esik;
  const siraYazi = d.siradaki ? ç("Sıradaki {saat}", { saat: saatKisa(d.siradaki) }) : ç("Sıra boş");
  return `<svg viewBox="0 0 700 380" role="img" aria-label="${esc(ç("Sağlık ocağı (2B): muayene odaları, bekleme salonu, sıra ekranı"))}"
      data-doktor="${d.doktorlar.length}" data-muayene="${d.muayenede}" data-salon="${salon}" data-ben="${d.ben.doktor ? "doktor" : d.ben.sedyede ? "sedye" : d.ben.sirada ? "sira" : "kapi"}">
    <rect x="-600" y="-400" width="1900" height="1180" fill="${karis("#DCE6E2", "#18202A", g0 * 0.85)}"/>
    <rect x="20" y="14" width="660" height="192" fill="${karis("#D5E4DF", "#26303A", g0 * 0.6)}"/>
    <rect x="20" y="206" width="660" height="168" fill="${karis("#C9D6D0", "#2A3236", g0 * 0.55)}"/>
    <rect x="20" y="200" width="660" height="7" fill="${karis("#2E8C83", "#1F5A55", g0 * 0.4)}"/>
    ${odalar}${bolme}
    <g data-saglik-sec="yorgunluk" class="saglik2b-tik"><rect x="34" y="218" width="78" height="80" rx="5" fill="#F4F1E8" stroke="#C9C2B0" stroke-width="2"/>
      <rect x="44" y="298" width="4" height="40" fill="#6B4E36"/><rect x="98" y="298" width="4" height="40" fill="#6B4E36"/>
      <text x="73" y="234" text-anchor="middle" font-size="9" font-weight="800" fill="#2B2724">${esc(ç("YORGUNLUK"))}</text>
      <text x="73" y="261" text-anchor="middle" font-size="20" font-weight="800" fill="${yorgun ? "#B5462F" : "#2E8C83"}">${esc(sayi(d.yorgunluk))}</text>
      <rect x="44" y="270" width="58" height="6" rx="3" fill="#D9D2C2"/><rect x="44" y="270" width="${(58 * yuzde).toFixed(1)}" height="6" rx="3" fill="${yorgun ? "#C65A3B" : "#2E8C83"}"/>
      <text x="73" y="290" text-anchor="middle" font-size="8" fill="#5A5046">${esc(ç("−1 / {n} dk", { n: Math.round(d.donem / 60000) }))}</text></g>
    <g data-saglik-sec="sira" class="saglik2b-tik"><rect x="586" y="216" width="84" height="46" rx="4" fill="#1E2A30"/><rect x="626" y="262" width="4" height="40" fill="#AEB6BC"/>
      <text x="628" y="235" text-anchor="middle" font-size="10" font-weight="800" fill="#7FE0A8">${esc(ç("SIRADA {n}", { n: d.bekleyen }))}</text>
      <text x="628" y="252" text-anchor="middle" font-size="8.5" fill="#CFE9DD">${esc(siraYazi)}</text></g>
    <rect x="566" y="316" width="104" height="44" rx="4" fill="#B9A58A"/><rect x="560" y="310" width="116" height="9" rx="3" fill="#D8C6A6"/><circle cx="650" cy="307" r="4" fill="#D9B54A"/>
    <rect x="132" y="322" width="18" height="36" rx="3" fill="#E8ECEC"/><rect x="134" y="306" width="14" height="18" rx="4" fill="#9FD3E8"/>
    <g data-saglik-sec="sira" class="saglik2b-tik">${sandalyeler}</g>
    ${benKapi}
    ${acik ? "" : `<text x="350" y="130" text-anchor="middle" font-size="13" font-weight="700" fill="${karis("#5A6A66", "#9FB3AE", g0)}">${esc(ç("Şu an nöbette doktor yok"))}</text>`}
    ${d.fazla > 0 ? `<text x="676" y="28" text-anchor="end" font-size="9" font-weight="700" fill="#2E8C83">${esc(ç("+{n} doktor daha", { n: d.fazla }))}</text>` : ""}
  </svg>`;
}

// ---------- 3B ----------
function saglik3bKur(THREE, cizici) {
  if (!cizici.kur()) throw new Error("webgl-yok");
  const tuval = cizici.renderer.domElement;
  const sahne = new THREE.Scene();
  const kamera = new THREE.PerspectiveCamera(32, 1, 0.1, 120);
  let w = 1, h = 1, kirli = true, kapEl = null, gorunur = true, gozcu = null;
  let d = { anahtar: "", sehir: "", gece: 0, doktorlar: [], fazla: 0, bekleyen: 0, muayenede: 0, salon: 0,
    ben: { id: "", ad: "", gorunus: null, ulke: null, sirada: false, sedyede: false, doktor: false, saat: null }, siradaki: null,
    yorgunluk: 0, tavan: 100, esik: 60, donem: 900000 };
  const dinleyici = {};
  const etkinMi = () => cizici.etkin === api;
  const malzeme = new Map();
  const M = (renk, ek = {}) => {
    const k = renk + JSON.stringify(ek);
    if (!malzeme.has(k)) malzeme.set(k, new THREE.MeshStandardMaterial({ color: renk, roughness: 0.8, ...ek }));
    return malzeme.get(k);
  };
  const golgeli = (m) => { m.castShadow = true; m.receiveShadow = true; return m; };
  const kutu = (g, gx, gy, gz, renk, x = 0, y = 0, z = 0) => {
    const m = golgeli(new THREE.Mesh(new THREE.BoxGeometry(gx, gy, gz), typeof renk === "string" ? M(renk) : renk));
    m.position.set(x, y + gy / 2, z);
    g.add(m);
    return m;
  };
  const silindir = (g, r1, r2, yuk, renk, x = 0, y = 0, z = 0, seg = 16) => {
    const m = golgeli(new THREE.Mesh(new THREE.CylinderGeometry(r1, r2, yuk, seg), typeof renk === "string" ? M(renk) : renk));
    m.position.set(x, y + yuk / 2, z);
    g.add(m);
    return m;
  };
  const tuvalDoku = (gen, yuk) => {
    const c = document.createElement("canvas");
    c.width = gen; c.height = yuk;
    const t = new THREE.CanvasTexture(c);
    t.colorSpace = THREE.SRGBColorSpace;
    return { c, t, g: c.getContext("2d") };
  };
  const W = 9.6, D = 6.6, ODA_ON = -1.1;     // odaların önü (bölmelerin ucu); arkası duvar
  const tiklanir = [];
  const metal = M("#AEB6BC", { metalness: 0.55, roughness: 0.35 });

  // ---------- Işık ----------
  const yari = new THREE.HemisphereLight("#F1F6F4", "#5A6460", 1.2);
  const gunes = new THREE.DirectionalLight("#FFF6E8", 1.3);
  gunes.position.set(-4, 10, 7);
  gunes.castShadow = true;
  gunes.shadow.mapSize.set(1024, 1024);
  Object.assign(gunes.shadow.camera, { left: -6.5, right: 6.5, top: 5, bottom: -5, near: 1, far: 40 });
  gunes.shadow.camera.updateProjectionMatrix();
  gunes.shadow.bias = -0.0005;
  sahne.add(yari, gunes, gunes.target);
  sahne.background = new THREE.Color("#DCE6E2");
  // Odaların tavan lambaları (doktor varsa yanar)
  const odaIsik = SAGLIK_ODA_X.map((x) => {
    const l = new THREE.PointLight("#F4FFF8", 0, 5, 1.6);
    l.position.set(x, 2.6, -2.2);
    sahne.add(l);
    return l;
  });

  // ---------- Döşeme ve duvarlar ----------
  kutu(sahne, W + 0.6, 0.4, D + 0.6, "#5A5E5A", 0, -0.52, 0);
  kutu(sahne, W, 0.12, D, M("#CBD8D2", { roughness: 0.6 }), 0, -0.12, 0);                    // muşamba
  const duvarMat = M("#E2EEEA", { roughness: 0.95 });
  kutu(sahne, W, 3.0, 0.12, duvarMat, 0, 0, -D / 2);
  kutu(sahne, 0.12, 3.0, D, duvarMat, -W / 2, 0, 0);
  kutu(sahne, 0.12, 3.0, D, duvarMat, W / 2, 0, 0);
  // Duvarlarda yeşil şerit (bel hizasında) ve süpürgelik
  const serit = M("#2E8C83", { roughness: 0.7 });
  kutu(sahne, W, 0.16, 0.02, serit, 0, 0.92, -D / 2 + 0.07);
  for (const s of [-1, 1]) kutu(sahne, 0.02, 0.16, D, serit, s * (W / 2 - 0.07), 0.92, 0);

  // ---------- Muayene odaları ----------
  const bolmeMat = M("#F4F8F6", { roughness: 0.9 }), bolmeCerceve = M("#B8C9C3", { roughness: 0.7 });
  for (const x of [-1.52, 1.52]) {
    kutu(sahne, 0.1, 2.1, D / 2 + ODA_ON, bolmeMat, x, 0, (ODA_ON - D / 2) / 2);
    kutu(sahne, 0.14, 0.08, D / 2 + ODA_ON, bolmeCerceve, x, 2.1, (ODA_ON - D / 2) / 2);
  }
  const odalar = SAGLIK_ODA_X.map((ox, i) => {
    const g = new THREE.Group();
    g.position.x = ox;
    sahne.add(g);
    // Masa (önde solda), ekran, kâğıtlar; masanın ardında koltuk
    kutu(g, 1.05, 0.06, 0.56, "#B9A58A", -0.6, 0.5, -1.75);
    for (const [a, b] of [[-1.08, -1.98], [-0.12, -1.98], [-1.08, -1.52], [-0.12, -1.52]]) kutu(g, 0.05, 0.5, 0.05, "#8A7660", a, 0, b);
    kutu(g, 0.34, 0.24, 0.03, "#2B3540", -0.72, 0.6, -1.9);
    const ekran = new THREE.Mesh(new THREE.PlaneGeometry(0.3, 0.2), new THREE.MeshStandardMaterial({ color: "#1B3A4A", emissive: new THREE.Color("#2F8FB5"), emissiveIntensity: 0 }));
    ekran.position.set(-0.72, 0.72, -1.883);
    g.add(ekran);
    kutu(g, 0.22, 0.012, 0.16, "#F7F4EC", -0.3, 0.56, -1.7);
    const koltuk = new THREE.Group();
    kutu(koltuk, 0.42, 0.06, 0.4, "#3D5A80", 0, SAGLIK_OTURAK - 0.06, 0);
    kutu(koltuk, 0.42, 0.44, 0.06, "#3D5A80", 0, SAGLIK_OTURAK, -0.2);
    silindir(koltuk, 0.025, 0.025, SAGLIK_OTURAK - 0.06, metal, 0, 0, 0, 8);
    koltuk.position.set(-0.6, 0, -2.3);
    g.add(koltuk);
    // Sedye (arkada sağda, duvar boyunca): ayaklar, döşek, çarşaf, yastık
    const sedye = new THREE.Group();
    for (const [a, b] of [[-0.62, -0.22], [0.62, -0.22], [-0.62, 0.22], [0.62, 0.22]]) silindir(sedye, 0.025, 0.025, SAGLIK_SEDYE - 0.1, metal, a, 0, b, 8);
    kutu(sedye, 1.4, 0.1, 0.56, "#6E8FA3", 0, SAGLIK_SEDYE - 0.1, 0);
    kutu(sedye, 1.3, 0.02, 0.5, "#F4F7F8", 0, SAGLIK_SEDYE, 0);
    kutu(sedye, 0.3, 0.08, 0.4, "#FFFFFF", 0.5, SAGLIK_SEDYE, 0);
    sedye.position.set(0.62, 0, -2.85);
    g.add(sedye);
    // Kalp ekranı (sedyenin başında, ayaklı): muayene sürerken çizgi atar
    silindir(g, 0.02, 0.025, 1.0, metal, 1.38, 0, -2.4, 8);
    const kalpDoku = tuvalDoku(128, 64);
    const kalp = new THREE.Mesh(new THREE.PlaneGeometry(0.34, 0.2), new THREE.MeshStandardMaterial({ map: kalpDoku.t, emissiveMap: kalpDoku.t, emissive: new THREE.Color("#FFFFFF"), emissiveIntensity: 0.4, roughness: 0.4 }));
    kutu(g, 0.38, 0.24, 0.06, "#1E2A30", 1.38, 0.98, -2.42);
    kalp.position.set(1.38, 1.1, -2.385);
    g.add(kalp);
    // Dolap (köşede): beyaz gövde, yeşil kapak çizgisi, üstünde ilaç şişeleri
    kutu(g, 0.42, 1.1, 0.34, "#F2F4F2", -1.18, 0, -3.05);
    kutu(g, 0.4, 0.04, 0.02, "#2E8C83", -1.18, 0.62, -2.875);
    for (const [a, r] of [[-1.3, "#C65A3B"], [-1.18, "#D9A548"], [-1.06, "#367F70"]]) silindir(g, 0.035, 0.035, 0.12, r, a, 1.1, -3.05, 10);
    // Perde (odanın önünde, sağda toplanmış) ve korniş
    kutu(g, 2.9, 0.03, 0.03, metal, 0, 2.05, ODA_ON + 0.05);
    const perde = kutu(g, 0.42, 1.45, 0.03, M("#C4DDEA", { roughness: 0.95 }), 1.22, 0.55, ODA_ON + 0.05);
    perde.castShadow = false;
    // Odanın tabelası (arka duvarda, kapı üstünde): doktorun adı ya da "Nöbetçi yok"
    const tabelaDoku = tuvalDoku(384, 112);
    const tabela = new THREE.Mesh(new THREE.PlaneGeometry(1.9, 0.55), new THREE.MeshStandardMaterial({ map: tabelaDoku.t, roughness: 0.6 }));
    tabela.position.set(0, 2.42, -D / 2 + 0.07);
    g.add(tabela);
    tiklanir.push({ nesne: g, ad: "oda", sira: i });
    return { g, ekran, kalpDoku, kalpFaz: -1, tabelaDoku, tabelaAnahtar: "" };
  });
  function tabelaYaz(o, k, i) {
    const a = JSON.stringify([k?.ad ?? null, k?.tip ?? null, k?.etki ?? null, k?.ben ?? false, DIL.kod]);
    if (a === o.tabelaAnahtar) return;
    o.tabelaAnahtar = a;
    const g = o.tabelaDoku.g;
    g.fillStyle = k ? "#2E8C83" : "#8A9894"; g.fillRect(0, 0, 384, 112);
    g.strokeStyle = "rgba(255,255,255,.85)"; g.lineWidth = 4; g.strokeRect(8, 8, 368, 96);
    g.fillStyle = "#FFFFFF"; g.textAlign = "center"; g.textBaseline = "middle";
    g.font = "700 22px Figtree, system-ui, sans-serif";
    g.fillText(ç("{n}. muayene odası", { n: i + 1 }), 192, 32, 350);
    g.font = "800 32px Figtree, system-ui, sans-serif";
    g.fillText(k ? String(k.ad) : ç("Nöbetçi yok"), 192, 74, 350);
    o.tabelaDoku.t.needsUpdate = true;
    kirli = true;
  }
  function kalpYaz(o, atiyor, t) {
    const faz = atiyor ? Math.floor((t ?? 0) * 12) : 0;
    if (faz === o.kalpFaz) return;
    o.kalpFaz = faz;
    const g = o.kalpDoku.g;
    g.fillStyle = "#0F1A1E"; g.fillRect(0, 0, 128, 64);
    g.strokeStyle = "#20363C"; g.lineWidth = 1;
    for (let x = 0; x < 128; x += 16) { g.beginPath(); g.moveTo(x, 0); g.lineTo(x, 64); g.stroke(); }
    g.strokeStyle = atiyor ? "#7FE0A8" : "#3D5560"; g.lineWidth = 2.5; g.beginPath();
    for (let x = 0; x <= 128; x += 2) {
      const u = ((x + faz * 4) % 64) / 64;
      const y = atiyor ? (u > 0.42 && u < 0.46 ? 14 : u > 0.46 && u < 0.5 ? 54 : u > 0.5 && u < 0.54 ? 26 : 36) : 36;
      if (x === 0) g.moveTo(x, y); else g.lineTo(x, y);
    }
    g.stroke();
    o.kalpDoku.t.needsUpdate = true;
    kirli = true;
  }

  // ---------- Bekleme salonu: sandalyeler (kameraya dönük), danışma, su sebili, saksı ----------
  const sandalyeGrup = new THREE.Group();
  sahne.add(sandalyeGrup);
  for (const [x, z] of SAGLIK_SANDALYE) {
    const s = new THREE.Group();
    kutu(s, 0.46, 0.05, 0.42, "#2E8C83", 0, SAGLIK_OTURAK - 0.05, 0);
    kutu(s, 0.46, 0.4, 0.05, "#256F68", 0, SAGLIK_OTURAK, -0.2);
    for (const a of [-0.19, 0.19]) for (const b of [-0.17, 0.17]) kutu(s, 0.03, SAGLIK_OTURAK - 0.05, 0.03, metal, a, 0, b);
    s.position.set(x, 0, z);
    sandalyeGrup.add(s);
  }
  tiklanir.push({ nesne: sandalyeGrup, ad: "sira" });
  {
    const danisma = new THREE.Group();
    kutu(danisma, 1.5, 0.72, 0.5, "#B9A58A", 0, 0, 0);
    kutu(danisma, 1.6, 0.05, 0.6, "#D8C6A6", 0, 0.72, 0);
    silindir(danisma, 0.05, 0.06, 0.04, "#D9B54A", 0.5, 0.77, 0.05, 12);    // zil
    kutu(danisma, 0.3, 0.012, 0.22, "#F7F4EC", -0.3, 0.77, 0.05);
    danisma.position.set(3.75, 0, 1.4);
    danisma.rotation.y = -0.35;
    sahne.add(danisma);
    // Su sebili ve saksı (solda)
    kutu(sahne, 0.32, 0.9, 0.32, "#E8ECEC", -4.35, 0, 2.5);
    silindir(sahne, 0.12, 0.12, 0.36, M("#9FD3E8", { transparent: true, opacity: 0.75, roughness: 0.2 }), -4.35, 0.9, 2.5, 14);
    silindir(sahne, 0.2, 0.16, 0.34, "#B5643B", -4.3, 0, -0.5, 14);
    for (let i = 0; i < 5; i++) {
      const y = new THREE.Mesh(new THREE.SphereGeometry(0.17, 10, 8), M("#4E8A5A"));
      y.position.set(-4.3 + Math.sin(i * 1.3) * 0.12, 0.48 + (i % 3) * 0.12, -0.5 + Math.cos(i * 1.3) * 0.12);
      y.castShadow = true;
      sahne.add(y);
    }
  }

  // ---------- Sağ duvarda sıra ekranı; sol duvarda yorgunluk panosu ----------
  const siraDoku = tuvalDoku(320, 180);
  const siraEkran = new THREE.Group();
  {
    kutu(siraEkran, 0.06, 0.82, 1.38, "#1E2A30", 0, -0.41, 0);
    const yuz = new THREE.Mesh(new THREE.PlaneGeometry(1.28, 0.72), new THREE.MeshBasicMaterial({ map: siraDoku.t, toneMapped: false }));
    yuz.rotation.y = -Math.PI / 2;
    yuz.position.x = -0.035;
    siraEkran.add(yuz);
    siraEkran.position.set(W / 2 - 0.1, 2.0, 0.2);
    sahne.add(siraEkran);
    tiklanir.push({ nesne: siraEkran, ad: "sira" });
  }
  let siraAnahtar = "";
  function siraYaz() {
    const a = `${d.bekleyen}|${d.siradaki}|${DIL.kod}`;
    if (a === siraAnahtar) return;
    siraAnahtar = a;
    const g = siraDoku.g;
    g.fillStyle = "#0F1A1E"; g.fillRect(0, 0, 320, 180);
    g.fillStyle = "#7FE0A8"; g.textAlign = "center"; g.textBaseline = "middle";
    g.font = "800 40px Figtree, system-ui, sans-serif";
    g.fillText(ç("SIRADA {n}", { n: d.bekleyen }), 160, 62, 300);
    g.fillStyle = "#CFE9DD"; g.font = "600 28px Figtree, system-ui, sans-serif";
    g.fillText(d.siradaki ? ç("Sıradaki {saat}", { saat: saatKisa(d.siradaki) }) : ç("Sıra boş"), 160, 124, 300);
    siraDoku.t.needsUpdate = true;
    kirli = true;
  }
  const panoDoku = tuvalDoku(300, 300);
  const pano = new THREE.Group();
  {
    kutu(pano, 0.05, 1.12, 1.12, "#6B4E36", 0, -0.56, 0);
    const yuz = new THREE.Mesh(new THREE.PlaneGeometry(1.02, 1.02), new THREE.MeshStandardMaterial({ map: panoDoku.t, roughness: 0.7 }));
    yuz.rotation.y = Math.PI / 2;
    yuz.position.x = 0.03;
    pano.add(yuz);
    pano.position.set(-W / 2 + 0.1, 1.85, 0.6);
    sahne.add(pano);
    tiklanir.push({ nesne: pano, ad: "yorgunluk" });
  }
  let panoAnahtar = "";
  function panoYaz() {
    const a = `${d.yorgunluk}|${d.tavan}|${d.esik}|${d.donem}|${DIL.kod}`;
    if (a === panoAnahtar) return;
    panoAnahtar = a;
    const g = panoDoku.g;
    const yorgun = d.yorgunluk >= d.esik;
    g.fillStyle = "#F4F1E8"; g.fillRect(0, 0, 300, 300);
    g.strokeStyle = "#C9C2B0"; g.lineWidth = 6; g.strokeRect(3, 3, 294, 294);
    g.fillStyle = "#2B2724"; g.textAlign = "center"; g.textBaseline = "middle";
    g.font = "800 30px Figtree, system-ui, sans-serif";
    g.fillText(ç("YORGUNLUK"), 150, 44, 270);
    g.fillStyle = yorgun ? "#B5462F" : "#2E8C83"; g.font = "800 84px Figtree, system-ui, sans-serif";
    g.fillText(sayi(d.yorgunluk), 150, 128, 270);
    const o = Math.max(0, Math.min(1, d.yorgunluk / Math.max(1, d.tavan)));
    g.fillStyle = "#D9D2C2"; g.fillRect(36, 186, 228, 18);
    g.fillStyle = yorgun ? "#C65A3B" : "#2E8C83"; g.fillRect(36, 186, 228 * o, 18);
    g.fillStyle = "#2B2724"; g.fillRect(36 + 228 * (d.esik / Math.max(1, d.tavan)) - 2, 180, 4, 30);
    g.fillStyle = "#5A5046"; g.font = "600 22px Figtree, system-ui, sans-serif";
    g.fillText(ç("−1 / {n} dk", { n: Math.round(d.donem / 60000) }), 150, 246, 270);
    panoDoku.t.needsUpdate = true;
    kirli = true;
  }

  // ---------- Kişiler: doktorlar ve sen (tam figür), sıradakiler (kalabalık) ----------
  const yuvaKur = () => {
    const fp = figurParcasi(THREE);
    fp.grup.scale.setScalar(SAGLIK_OLCEK);
    const kok = new THREE.Group();
    kok.add(fp.grup);
    kok.visible = false;
    sahne.add(kok);
    const y = { fp, kok, id: null, eylem: "bekle", faz: 0 };
    tiklanir.push({ nesne: kok, ad: "kisi", yuva: y });
    return y;
  };
  const doktorYuva = SAGLIK_ODA_X.map(yuvaKur);
  const benYuva = yuvaKur();
  const kalabalik = kalabalikKur(THREE, SAGLIK_SANDALYE.length + SAGLIK_ODA_X.length);
  sahne.add(kalabalik.grup);
  let kisiAnahtar = "";
  function kisileriYaz() {
    const anahtar = JSON.stringify([d.doktorlar.map((k) => [k.kisi, k.ad, k.gorunus, k.muayene, k.benimSiram]), d.salon, d.ben]);
    if (anahtar === kisiAnahtar) return;
    kisiAnahtar = anahtar;
    // Doktorlar: muayenedeyse sedyenin solunda ayakta (hastaya dönük), değilse masasında oturur
    doktorYuva.forEach((y, i) => {
      const k = d.doktorlar[i];
      y.kok.visible = !!k;
      if (!k) { y.id = null; return; }
      y.id = k.kisi;
      y.fp.kur({ anahtar: k.kisi, ad: k.ad, gorunus: k.gorunus, ulke: k.ulke, rutbe: { sira: 0, sayi: 12 }, ek: { onluk: true } });
      const ox = SAGLIK_ODA_X[i];
      if (k.muayene) { y.eylem = "muayene"; y.kok.position.set(ox + 0.02, 0.02, -2.42); y.kok.rotation.y = Math.PI / 2 - 0.25; }
      else { y.eylem = "otur"; y.kok.position.set(ox - 0.6, 0.02, -2.22); y.kok.rotation.y = 0; }
      y.faz = (ozet(String(k.kisi)) % 1000) / 1000;
    });
    // Sen: doktorsan odanda (yukarıda); sedyedeysen doktorunun sedyesinde; sıradaysan ön sırada; değilsen kapıda
    const b = d.ben;
    const benOda = d.doktorlar.findIndex((k) => k.benimSiram);
    benYuva.kok.visible = !b.doktor && !!b.id;
    if (benYuva.kok.visible) {
      benYuva.id = b.id;
      benYuva.fp.kur({ anahtar: b.id, ad: b.ad, gorunus: b.gorunus, ulke: b.ulke, rutbe: { sira: 0, sayi: 12 }, ek: null });
      if (b.sedyede && benOda >= 0) { benYuva.eylem = "otur"; benYuva.kok.position.set(SAGLIK_ODA_X[benOda] + 0.6, SAGLIK_SEDYE - 0.22, -2.78); benYuva.kok.rotation.y = 0; }
      else if (b.sirada) { benYuva.eylem = "otur"; benYuva.kok.position.set(SAGLIK_SANDALYE[0][0], 0.02, SAGLIK_SANDALYE[0][1] - 0.02); benYuva.kok.rotation.y = 0; }
      else { benYuva.eylem = "bekle"; benYuva.kok.position.set(0.25, 0.02, 2.75); benYuva.kok.rotation.y = -0.3; }
    }
    // Kalabalık: sedyedeki öteki hastalar ve salonda oturanlar (benim yerim boş kalır)
    const liste = [];
    d.doktorlar.forEach((k, i) => {
      if (!k.muayene || (k.benimSiram && b.sedyede)) return;
      liste.push({ x: SAGLIK_ODA_X[i] + 0.6, z: -2.8, y: SAGLIK_SEDYE - 0.3 * SAGLIK_KALABALIK, yon: 0, eylem: "otur", olcek: SAGLIK_KALABALIK,
        giysi: KALABALIK_GIYSI[(i * 3 + 2) % KALABALIK_GIYSI.length], ten: KALABALIK_TEN[(i * 2 + 1) % KALABALIK_TEN.length] });
    });
    const n = Math.min(SAGLIK_SANDALYE.length - 1, d.salon);
    for (let i = 0; i < n; i++) {
      const [x, z] = SAGLIK_SANDALYE[i + 1];
      liste.push({ x, z: z - 0.02, y: SAGLIK_OTURAK - 0.3 * SAGLIK_KALABALIK, yon: 0, eylem: i % 3 === 1 ? "otur_bekle" : "otur", olcek: SAGLIK_KALABALIK,
        giysi: KALABALIK_GIYSI[(i * 3 + 1) % KALABALIK_GIYSI.length], ten: KALABALIK_TEN[(i * 5 + 2) % KALABALIK_TEN.length], faz: i * 0.37 });
    }
    kalabalik.yaz(liste);
    kirli = true;
  }

  // ---------- Kamera ----------
  const YON = new THREE.Vector3(0, 0.82, 1).normalize(), YON_DAR = new THREE.Vector3(0, 1.08, 1).normalize();
  function kameraKur() {
    kamera.aspect = w / h;
    const dar = w / h < 1.3;
    const n = [[-W / 2, 0, D / 2], [W / 2, 0, D / 2], [-W / 2, 2.9, -D / 2], [W / 2, 2.9, -D / 2]].map(([a, b, c]) => new THREE.Vector3(a, b, c));
    kameraSigdir(THREE, kamera, n, dar ? YON_DAR : YON, { x: 0.99, ust: 0.95, alt: -0.97 });
    kirli = true;
  }

  // ---------- Etkileşim ----------
  const isin = new THREE.Raycaster(), imlec = new THREE.Vector2();
  tuval.addEventListener("pointerup", (e) => {
    if (!etkinMi()) return;
    const rr = tuval.getBoundingClientRect();
    imlec.set(((e.clientX - rr.left) / rr.width) * 2 - 1, -((e.clientY - rr.top) / rr.height) * 2 + 1);
    isin.setFromCamera(imlec, kamera);
    const adaylar = tiklanir.filter((x) => x.nesne.visible).map((x) => x.nesne);
    const vur = isin.intersectObjects(adaylar, true)[0];
    if (!vur) return;
    let o = vur.object;
    while (o && !tiklanir.some((x) => x.nesne === o)) o = o.parent;
    const t = tiklanir.find((x) => x.nesne === o);
    if (!t) return;
    if (t.ad === "kisi") {
      if (t.yuva === benYuva) dinleyici.sec?.("ben");
      else if (t.yuva.id) dinleyici.sec?.("kisi", t.yuva.id);
      return;
    }
    if (t.ad === "oda") { const k = d.doktorlar[t.sira]; dinleyici.sec?.(k ? "doktor" : "oda", k?.id ?? null); return; }
    dinleyici.sec?.(t.ad);
  });

  function isikUygula() {
    const g = d.gece ?? 0;
    sahne.background.set("#DCE6E2").lerp(new THREE.Color("#18202A"), g * 0.88);
    // İçerisi gece de aydınlık (tavan lambaları): gece yalnız dış ışık ve arka plan kararır
    yari.intensity = 1.25 - g * 0.25;
    gunes.intensity = 1.3 * (1 - g * 0.55);
    odaIsik.forEach((l, i) => { l.intensity = d.doktorlar[i] ? 3.2 + g * 2 : 0; });
    odalar.forEach((o, i) => { o.ekran.material.emissiveIntensity = d.doktorlar[i] ? 0.55 : 0; });
    kirli = true;
  }
  function yaz() {
    odalar.forEach((o, i) => { tabelaYaz(o, d.doktorlar[i], i); o.kalpFaz = -1; kalpYaz(o, !!d.doktorlar[i]?.muayene, 0); });
    siraYaz();
    panoYaz();
    kisileriYaz();
    isikUygula();
    if (kapEl) {
      const ds = kapEl.dataset;
      const yeni = { doktor: String(d.doktorlar.length), muayene: String(d.muayenede), salon: String(Math.min(SAGLIK_SANDALYE.length - 1, d.salon)),
        ben: d.ben.doktor ? "doktor" : d.ben.sedyede ? "sedye" : d.ben.sirada ? "sira" : "kapi" };
      for (const [k, v] of Object.entries(yeni)) if (ds[k] !== v) ds[k] = v;
    }
    kirli = true;
  }

  const api = {
    get etiket() { return ç("Sağlık ocağı (3B): muayene odaları, nöbetteki doktorlar, bekleme salonu ve sıra"); },
    sahne, kamera,
    get kareMs() { return !gorunur || hareketAzalt ? 1000 : telefon() ? 50 : 33; },
    dinle(ad, fn) { dinleyici[ad] = fn; },
    kapBagla(el) {
      kapEl = el ?? null;
      gozcu?.disconnect();
      gozcu = null;
      if (kapEl && typeof IntersectionObserver !== "undefined") {
        gozcu = new IntersectionObserver((g) => { gorunur = g.some((x) => x.isIntersecting); kirli = true; });
        gozcu.observe(kapEl);
      }
      kisiAnahtar = ""; siraAnahtar = ""; panoAnahtar = "";
      for (const o of odalar) o.tabelaAnahtar = "";
      yaz();
    },
    get cizimSayisi() { let n = 0; sahne.traverseVisible((o) => { if (o.isMesh) n++; }); return n; },
    durumYaz(y) { d = { ...d, ...y }; yaz(); },
    kalite(k) { gunes.castShadow = k !== "dusuk"; kirli = true; },
    boyut(gen, yuk) { w = gen; h = yuk; kameraKur(); },
    etkinlestir(acik) { if (acik) kirli = true; },
    guncelle(dt, t) {
      if (!gorunur) return;
      for (const y of [...doktorYuva, benYuva]) {
        if (!y.kok.visible) continue;
        const sure = y.fp.eylemSuresi(y.eylem) || 3;
        y.fp.pozla(y.eylem, ((t + y.faz * sure) % sure) / sure, t + y.faz * 7, hareketAzalt, true);
        if (!hareketAzalt) y.fp.canli(t + y.faz * 5);
      }
      if (!hareketAzalt) {
        kalabalik.guncelle(t);
        odalar.forEach((o, i) => { if (d.doktorlar[i]?.muayene) kalpYaz(o, true, t); });
      }
      kirli = true;
    },
    cizilmeli() { const c = kirli; kirli = false; return c; },
  };
  return api;
}

// ---------- Sağlık ocağının kartı (Şehrim → Sağlık): 3B ya da 2B, başlık ve özet yazı ----------
let saglik3bOrnek = null;
const SaglikSahnesi = (() => {
  function ac() {
    const el = document.createElement("section");
    el.className = "kart saglik-kart";
    el.id = "saglik-oda";
    let d = null, hata3b = false, kapandi = false;
    const mod3b = () => Gorunum.uc() && !hata3b;
    let mod = mod3b() ? "3b" : "2b";
    const dinleyici = {};
    const sec = (ad, id) => dinleyici.sec?.(ad, id);
    const ikiBBagla = (kok) => {
      for (const g of $$("[data-saglik-kisi]", kok)) g.addEventListener("click", (e) => { e.stopPropagation(); sec("kisi", g.dataset.saglikKisi); });
      for (const g of $$("[data-saglik-sec]", kok)) g.addEventListener("click", (e) => {
        e.stopPropagation();
        sec(g.dataset.saglikSec, g.dataset.saglikOda || null);
      });
    };
    const baslik = (x) => (x.muayenede ? ç("Muayene sürüyor") : x.doktorlar.length ? ç("{n} doktor nöbette", { n: x.doktorlar.length + x.fazla }) : ç("Nöbetçi yok"));
    const yazi = (x) => [
      x.doktorlar.length ? ç("Nöbette: {liste}.", { liste: x.doktorlar.map((k) => `${k.ad} (${ç("tıp {n}", { n: k.tip })})`).join(", ") })
        : ç("Şu an nöbette doktor yok."),
      x.bekleyen ? ç("Sırada {n} kişi.", { n: x.bekleyen }) : "",
      x.ben.sedyede ? ç("Muayene saatin geldi: sedyedesin.") : x.ben.sirada ? ç("Sıradasın: muayene saatin {saat}.", { saat: saatKisa(x.ben.saat) }) : "",
    ].filter(Boolean).join(" ");

    function ciz() {
      if (!d) return;
      el.innerHTML = `<div class="kart-bas"><div><p class="ust-yazi">${ç("Sağlık ocağı")}${d.sehir ? " · " + esc(d.sehir) : ""}</p>
          <h2 class="b2" id="saglik-oda-baslik">${esc(baslik(d))}</h2></div>
          ${Gorunum.webglVar() ? `<button class="dugme sade kucuk-d" id="saglik-mod" aria-pressed="${mod === "2b"}" title="${mod === "3b" ? ç("Hafif görünüme (2B) geç") : ç("3B görünüme geç")}">${ikon("layers")}${mod === "3b" ? ç("2B") : ç("3B")}</button>` : ""}</div>
        <div class="saglik-sahne sahne3b" id="saglik-sahne" data-mod="${mod}">
          ${mod === "3b" ? `<div class="yukleniyor saglik-on${saglik3bOrnek && Uc.cizici?.etkin === saglik3bOrnek ? " bitti" : ""}" id="saglik-yukleniyor" aria-label="${ç("Sağlık ocağı açılıyor…")}">${saglik2b(d)}</div>` : ""}
          <div class="saglik-2b" id="saglik-2b"${mod === "3b" ? " hidden" : ""}>${mod === "2b" ? saglik2b(d) : ""}</div>
        </div>
        <p class="kucuk" style="margin-top:8px" id="saglik-oda-yazi">${esc(yazi(d))}</p>`;
      $("#saglik-mod", el)?.addEventListener("click", () => {
        hata3b = false;
        const ikiB = mod === "3b";
        Gorunum.ayarla(ikiB ? "2b" : "3b");
        tost(ikiB ? ç("Hafif görünüm (2B) seçildi. Ayarlar'dan değiştirebilirsin.") : ç("3B görünüm seçildi."), "layers");
      });
      ikiBBagla($("#saglik-2b", el));
      sahneBagla();
    }
    const etkin3b = () => mod === "3b" && saglik3bOrnek && Uc.cizici?.etkin === saglik3bOrnek;
    function sahneBirak() { if (saglik3bOrnek && Uc.cizici?.etkin === saglik3bOrnek) Uc.cizici.birak(saglik3bOrnek); }
    async function sahneBagla() {
      const kutu = $("#saglik-sahne", el);
      if (!kutu || mod !== "3b") { sahneBirak(); return; }
      try {
        const { THREE, cizici } = await Uc.yukle();
        if (kapandi || mod !== "3b" || $("#saglik-sahne", el) !== kutu) return;
        saglik3bOrnek ??= saglik3bKur(THREE, cizici);
        const a = saglik3bOrnek;
        a.dinle("sec", sec);
        a.kapBagla(kutu);
        a.durumYaz(d);
        if (!cizici.bagla(a, kutu)) throw new Error("webgl-bagla");
        $("#saglik-yukleniyor", kutu)?.classList.add("bitti");
      } catch (e) {
        console.warn("3B sağlık ocağı açılamadı:", e);
        if (kapandi) return;
        hata3b = true; mod = "2b";
        tost(ç("3B sahne bu cihazda açılamadı; hafif görünüm gösteriliyor."), "layers");
        ciz();
      }
    }
    function tazeCiz() {
      const b = $("#saglik-oda-baslik", el);
      if (b) b.textContent = baslik(d);
      const y = $("#saglik-oda-yazi", el);
      if (y) y.textContent = yazi(d);
      if (etkin3b()) saglik3bOrnek.durumYaz(d);
      else if (mod === "2b") { const k = $("#saglik-2b", el); if (k) { k.innerHTML = saglik2b(d); ikiBBagla(k); } }
    }
    // veri: { c (api.clinic), ben: { id, ad, gorunus, ulke } }
    function yaz(veri) {
      d = saglikVerisi(veri.c, veri.ben);
      if (!el.isConnected || !el.childElementCount) { ciz(); return; }
      tazeCiz();
      if (mod === "3b" && !etkin3b()) sahneBagla();
    }
    const b1 = Gorunum.dinle(() => { const yeni = mod3b() ? "3b" : "2b"; if (yeni !== mod && d) { mod = yeni; ciz(); } });
    function kapat() { kapandi = true; b1(); sahneBirak(); }
    return { el, yaz, kapat, birak: sahneBirak, dinle(ad, fn) { dinleyici[ad] = fn; } };
  }
  return { ac };
})();

// ===== 98zk_saglik.js =====
// ---------- Şehrim → Sağlık (D-143): şehrin sağlık ocağı; meydanın "Sağlık ocağı" kapısından da girilir ----------
// Üstte sağlık ocağının sahnesi (98zj_saglik3b.js). Savaş yorgunluğun (cephede ve yönetime el koyma girişiminde her vuruş bir
// puan; kendiliğinden azalır; eşiğin üstünde yeni eğitimler uzun sürer), sıradaki muayenen (saati başlamadıysa vazgeçilir),
// nöbetteki doktorlar (ücret, etki, sıradaki boş saat, kalan yer; "Sıraya gir"), doktorluk (tıp becerisi yeterliyse nöbet aç:
// süre ve ücret; nöbetteyken sıran, kazancın, "Nöbeti bitir") ve geçmiş. Karar sunucuda (profession-1.0.0); ekran sınırları
// gösterir ve önceden denetler. Yarım dakikada bir ve olaylarda tazelenir.

const meslekKurali = () => Durum.v.kurallar?.data?.profession ?? {};
const yorgunlukTavan = () => Number(meslekKurali().fatigue?.max ?? 100);
// Yorgunken eğitimin uzama oranı (training kuralı)
const yorgunlukYavaslatma = () => Number(Durum.v.kurallar?.data?.training?.fatigueSlowPpm ?? 0);

// Yorgunluk satırı (Eğitim ve Sağlık): puan / tavan, eşik çizgisi, durum yazısı
function yorgunlukCubugu(f) {
  const p = Number(f?.points ?? 0), m = Math.max(1, Number(f?.max ?? yorgunlukTavan())), e = Number(f?.tired_at ?? 60);
  return `<div class="yorgunluk-cubuk${f?.tired ? " yorgun" : ""}" role="img" aria-label="${esc(ç("Yorgunluk {n} / {m}", { n: sayi(p), m: sayi(m) }))}">
    <i style="width:${Math.round((Math.min(p, m) / m) * 100)}%"></i><b style="left:${Math.round((e / m) * 100)}%"></b></div>`;
}
function yorgunlukDurumu(f) {
  if (!f) return "";
  const p = Number(f.points ?? 0);
  if (f.tired) return ç("Yorgunsun: yeni başlayan eğitimlerin {oran} uzun sürer. {zaman} eşiğin altına inersin; muayene hemen indirir.",
    { oran: ppmYuzde(yorgunlukYavaslatma()), zaman: saatYaz(f.below_at) });
  if (p > 0) return ç("Yorgunluğun eğitimini yavaşlatmıyor (eşik {e}). {zaman} tamamen geçer.", { e: sayi(f.tired_at ?? 60), zaman: saatYaz(f.zero_at) });
  return ç("Dinlenmişsin; yorgunluğun yok.");
}

// Cephede vuruşun yanıtındaki yorgunluk (D-143): askerlik özetine yazılır; eşik o vuruşla geçilince bir kez söylenir. Yorgunluk
// savaşta hiçbir şeyi değiştirmez (gücün, enerjin, sonucu aynı).
function yorgunlukVurus(f) {
  if (!f || f.points == null) return;
  const a = Durum.v.askerlik;
  if (a) a.fatigue = { ...(a.fatigue ?? {}), ...f };
  const once = Number(f.before ?? f.points), simdi = Number(f.points), esik = Number(f.tired_at ?? 60);
  if (once < esik && simdi >= esik) {
    tost(ç("Yoruldun (yorgunluk {n}): yeni eğitimlerin {oran} uzun sürer. Savaşa etkisi yok; Şehrim → Sağlık'ta muayene olabilirsin.",
      { n: sayi(simdi), oran: ppmYuzde(yorgunlukYavaslatma()) }), "heart-pulse");
  }
}

// Muayenenin iptal nedeni (geçmiş)
const MUAYENE_IPTAL = {
  patient: ç("vazgeçtin"), doctor: ç("doktor nöbeti bitirdi"), shift_ended: ç("nöbet bitti"), away: ç("saatinde şehirde değildin"),
  healthy: ç("yorgunluğun kalmamıştı"), deleted: ç("hesap silindi"),
};
const NOBET_SON = { time: ç("süresi doldu"), doctor: ç("sen bitirdin"), away: ç("şehirden ayrıldın"), deleted: ç("hesap silindi") };

Kabuk.kaydet("sehir/saglik", {
  async ac(kap) {
    let c = null;           // api.clinic
    let kapandi = false;
    let durdur = () => {};
    const sahne = SaglikSahnesi.ac();
    sahne.dinle("sec", (ad, id) => {
      if (ad === "kisi") { if (id) profilAc(id, () => tazele()); return; }
      const hedef = ad === "doktor" && id ? `[data-saglik-nobet="${CSS.escape(id)}"]`
        : { ben: c?.my_visit ? "#saglik-siram" : "#saglik-yorgunluk", sira: "#saglik-doktorlar", oda: "#saglik-doktorluk", yorgunluk: "#saglik-yorgunluk", doktor: "#saglik-doktorlar" }[ad];
      const el = hedef ? $(hedef, kap) : null;
      if (!el) return;
      el.scrollIntoView({ behavior: hareketAzalt ? "auto" : "smooth", block: "center" });
      el.classList.remove("vurgu-yan"); void el.offsetWidth; el.classList.add("vurgu-yan");
    });
    const ben = () => Durum.v.ozet?.character ?? {};
    let gorunus;
    let bekleyen = null;
    const yakinda = () => { clearTimeout(bekleyen); bekleyen = setTimeout(() => { if (!kapandi) tazeleIste(); }, 600); };
    // Nöbet formuna yazılan kaybolmasın: yazarken gelen tazeleme (canlı olay, dakikalık) formdan çıkınca yapılır; tazeleme
    // başladıktan sonra yazılmaya başlandıysa da yeniden çizilmez (27 Ekim 2026, Mekânım'daki hatayla aynı)
    let kirli = false, ertelendi = false;
    kap.addEventListener("input", (e) => { if (e.target.closest("#saglik-nobet-form")) kirli = true; });
    const tazeleIste = () => { if (kirli) ertelendi = true; else arkaTazele(); };

    async function yukle() {
      const [x, bak] = await Promise.all([Sunucu.cagir("clinic"), gorunus === undefined ? Sunucu.cagir("my_look").catch(() => null) : null]);
      c = x;
      if (gorunus === undefined) gorunus = bak?.look ?? null;
    }
    const R = () => c?.rule?.clinic ?? meslekKurali().clinic ?? {};

    function yorgunlukHtml() {
      const f = c.fatigue ?? {};
      const gunluk = Number(R().patientDaily ?? 3);
      return `<section class="kart" id="saglik-yorgunluk"><div class="kart-bas"><div><p class="ust-yazi">${ç("Savaş yorgunluğu")}</p>
          <h2 class="b2">${ç("{n} / {m}", { n: sayi(f.points ?? 0), m: sayi(f.max ?? yorgunlukTavan()) })}</h2></div><span class="ik-kutu">${ikon("heart-pulse")}</span></div>
        ${yorgunlukCubugu(f)}
        <p class="aciklama" style="margin-top:10px">${esc(yorgunlukDurumu(f))}</p>
        <p class="kucuk" style="margin-top:6px">${ç("Cephede ve yönetime el koyma girişiminde her vuruş {v} puan ekler; {dk} dakikada bir puan kendiliğinden azalır. Yorgunluk savaşta gücünü, enerjini ya da sonucu değiştirmez.",
          { v: sayi(c.rule?.fatigue?.perHit ?? 1), dk: sayi(c.rule?.fatigue?.recoverMinutesPerPoint ?? 15) })}</p>
        <p class="kucuk" style="margin-top:4px">${ç("Bugün {n} / {m} muayene.", { n: sayi(c.today ?? 0), m: sayi(gunluk) })}</p></section>`;
    }
    function siramHtml() {
      const v = c.my_visit;
      if (!v) return "";
      const basladi = Date.parse(v.slot_starts_at) <= Date.now();
      const baskaSehir = v.region_id !== c.region_id;
      return `<section class="kart" id="saglik-siram"><div class="kart-bas"><div><p class="ust-yazi">${ç("Sıradaki muayenen")}</p>
          <h2 class="b2">${esc(v.doctor ?? "")}</h2></div><span class="ik-kutu">${ikon("stethoscope")}</span></div>
        <div class="liste"><div class="liste-satir"><span class="liste-ikon yesil">${ikon("clock-3")}</span>
          <div><span class="tur">${basladi ? ç("Muayene sürüyor") : ç("Muayene saati")}</span><b>${esc(saatYaz(v.slot_starts_at))}</b>
            <div class="alt">${esc([basladi ? ç("bitiş {saat}", { saat: saatKisa(v.slot_ends_at) }) : null,
              ç("ücret {kr} kredi (ayrıldı; muayene olmazsa döner)", { kr: kr(v.fee_cr ?? 0) }), baskaSehir ? bolgeAdi(v.region_id) : null].filter(Boolean).join(" · "))}</div></div>
          <span class="cip">${ikon("hourglass")}<b data-bitis="${esc(basladi ? v.slot_ends_at : v.slot_starts_at)}"></b></span></div></div>
        ${baskaSehir ? `<div class="bilgi-kutusu" style="margin-top:10px">${ikon("map-pin")}<span>${ç("Muayenen {sehir} şehrinde; saatinde orada olmazsan ücret döner.", { sehir: esc(bolgeAdi(v.region_id)) })}</span></div>` : ""}
        <p class="kucuk" style="margin-top:8px">${basladi ? ç("Saati başlayan muayeneden vazgeçilmez; bitince yorgunluğun azalır.") : ç("Muayene saatinde bu şehirde olmalısın; değilsen ücret sana döner.")}</p>
        ${basladi ? "" : `<div class="oneri-dugmeler" style="margin-top:10px"><button class="dugme ikincil kucuk-d" id="saglik-vazgec">${ikon("x")}${ç("Sıradan çık")}</button></div>`}</section>`;
    }
    // Sıraya girmenin önündeki engel (sunucu da denetler): kısa yazı ya da boş
    function girisEngeli(s) {
      if (s.mine) return ç("Kendi nöbetin");
      if (c.on_road) return ç("Yoldasın");
      if (c.my_visit) return ç("Zaten sıradasın");
      if (Number(c.fatigue?.points ?? 0) <= 0) return ç("Yorgunluğun yok");
      if (Number(c.today ?? 0) >= Number(R().patientDaily ?? 3)) return ç("Bugünkü muayene hakkın doldu");
      if (s.blocked) return ç("Bu doktora sıra alamazsın");
      if (!s.next_slot || Number(s.free_slots ?? 0) <= 0) return ç("Yer yok");
      return null;
    }
    function doktorlarHtml() {
      const l = c.shifts ?? [];
      return `<section class="kart" id="saglik-doktorlar"><div class="kart-bas"><div><p class="ust-yazi">${ç("Nöbetteki doktorlar")}</p>
          <h2 class="b2">${l.length ? ç("{n} doktor", { n: sayi(l.length) }) : ç("Nöbetçi yok")}</h2></div><span class="ik-kutu">${ikon("stethoscope")}</span></div>
        ${l.length ? `<div class="liste">${l.map((s) => {
          const engel = girisEngeli(s);
          return `<div class="liste-satir saglik-nobet" data-saglik-nobet="${esc(s.shift_id)}"><span class="liste-ikon">${avatarKutu(s.doctor ?? "", s.doctor_id)}</span>
            <div><span class="tur">${esc([ç("tıp {n}", { n: sayi(s.skill ?? 0) }), ç("−{e} yorgunluk", { e: sayi(s.relief ?? 0) }), ç("{kr} kredi", { kr: kr(s.fee_cr ?? 0) })].join(" · "))}</span>
              <b><button class="baglanti" type="button" data-profil="${esc(s.doctor_id)}">${esc(s.doctor ?? "")}</button>${s.mine ? ` <span class="cip altin">${ç("Sen")}</span>` : ""}</b>
              <div class="alt">${esc([s.treating ? ç("şu an muayenede") : null,
                s.next_slot ? ç("sıradaki boş saat {saat}", { saat: saatKisa(s.next_slot.starts_at) }) : ç("yer kalmadı"),
                ç("{n} yer", { n: sayi(s.free_slots ?? 0) }), ç("sırada {n}", { n: sayi(s.queue ?? 0) }),
                ç("nöbetin bitişi {saat}", { saat: saatKisa(s.ends_at) })].filter(Boolean).join(" · "))}</div>
              ${engel && !s.mine ? `<div class="alt saglik-engel">${esc(engel)}</div>` : ""}</div>
            ${s.mine ? "<span></span>" : `<button class="dugme kucuk-d" data-saglik-gir="${esc(s.shift_id)}" ${engel ? "disabled" : ""}>${ikon("user-round-plus")}${ç("Sıraya gir")}</button>`}</div>`;
        }).join("")}</div>`
          : `<p class="bos">${c.on_road ? ç("Yoldasın; vardığın şehrin doktorları burada görünür.") : ç("Şu an bu şehirde nöbette doktor yok. Tıp becerin {n} olunca sen nöbet tutabilirsin.", { n: sayi(R().minSkill ?? 10) })}</p>`}
        <p class="kucuk" style="margin-top:8px">${ç("Muayene {dk} dakika sürer; saati gelince yorgunluğun doktorun etkisi kadar azalır. Ücret sıraya girerken ayrılır, muayeneden sonra doktora geçer (maaş vergisi düşülür).", { dk: sayi(R().treatMinutes ?? 10) })}</p></section>`;
    }
    function doktorlukHtml() {
      const x = c.my_shift, kur = R();
      const en = Number(kur.minSkill ?? 10), tip = Number(c.medicine ?? 0);
      if (x) {
        const visits = x.visits ?? [];
        return `<section class="kart" id="saglik-doktorluk"><div class="kart-bas"><div><p class="ust-yazi">${ç("Doktorluk")} · ${esc(bolgeAdi(x.region_id))}</p>
            <h2 class="b2">${ç("Nöbettesin")}</h2></div><span class="ik-kutu">${ikon("stethoscope")}</span></div>
          <div class="satir" style="justify-content:space-between;flex-wrap:wrap;gap:8px"><span class="kucuk">${esc([ç("{n} birim", { n: sayi(x.units) }), ç("ücret {kr} kredi", { kr: kr(x.fee_cr ?? 0) }), ç("etki −{e}", { e: sayi(x.relief ?? 0) })].join(" · "))}</span>
            <span class="cip">${ikon("hourglass")}${ç("bitişe")} <b data-bitis="${esc(x.ends_at)}"></b></span></div>
          <div class="cubuk" style="margin-top:8px"><i data-ilerleme="${esc(x.starts_at)}|${esc(x.ends_at)}" style="display:block;height:100%;background:var(--orman)"></i></div>
          <p class="kucuk" style="margin-top:8px">${ç("{n} hasta muayene ettin; kazancın {kr} kredi (vergiden sonra).", { n: sayi(x.treated ?? 0), kr: kr(x.earned_cr ?? 0) })}</p>
          ${visits.length ? `<div class="liste" style="margin-top:10px">${visits.map((v) => {
            const simdi = Date.now(), bas = Date.parse(v.slot_starts_at), son = Date.parse(v.slot_ends_at);
            const durum = v.status === "treated" ? ç("muayene edildi: {a} → {b}", { a: sayi(v.fatigue_before ?? 0), b: sayi(v.fatigue_after ?? 0) })
              : bas <= simdi && simdi < son ? ç("şu an muayenede") : ç("bekliyor");
            return `<div class="liste-satir"><span class="liste-ikon ${v.status === "treated" ? "yesil" : ""}">${avatarKutu(v.patient ?? "?", v.patient_id)}</span>
              <div><span class="tur">${esc(saatKisa(v.slot_starts_at))} · ${esc(durum)}</span><b>${v.patient_id ? `<button class="baglanti" type="button" data-profil="${esc(v.patient_id)}">${esc(v.patient ?? "")}</button>` : esc(v.patient ?? "")}</b></div><span></span></div>`;
          }).join("")}</div>` : `<p class="bos" style="margin-top:10px">${ç("Henüz sırana giren yok. Yorgun oyuncular nöbetteki doktorları burada görür.")}</p>`}
          <div class="oneri-dugmeler" style="margin-top:12px"><button class="dugme mercan kucuk-d" id="saglik-bitir">${ikon("square")}${ç("Nöbeti bitir")}</button></div>
          <p class="kucuk" style="margin-top:8px">${ç("Şehirden ayrılırsan nöbet biter. Bitirince sıradakilerin ücreti döner; saati dolmuş muayene yapılır.")}</p></section>`;
      }
      const sicil = c.record_until && Date.parse(c.record_until) > Date.now();
      const engel = tip < en ? `<div class="bilgi-kutusu">${ikon("graduation-cap")}<span>${ç("Tıp becerin {n}; nöbet tutmak için en az {m} gerekir. Hayatım → Eğitim'den tıp çalışabilirsin.", { n: sayi(tip), m: sayi(en) })}</span></div>
          <div class="oneri-dugmeler" style="margin-top:10px"><button class="dugme ikincil kucuk-d" data-git="hayat/egitim">${ikon("graduation-cap")}${ç("Eğitim")}</button></div>`
        : sicil ? `<div class="hata-kutusu">${ikon("scale")}<span>${ç("Sicil kaydın nedeniyle {zaman} tarihine kadar doktorluk yapamazsın.", { zaman: esc(saatYaz(c.record_until)) })}</span></div>`
        : c.on_road ? `<div class="bilgi-kutusu">${ikon("route")}<span>${ç("Yoldayken nöbet tutulmaz; vardığın şehrin sağlık ocağında tutarsın.")}</span></div>` : "";
      const birim = Number(kur.unitMinutes ?? 30), muayene = Number(kur.treatMinutes ?? 10);
      const kalan = Math.max(0, Number(c.daily_work_cap ?? 0) - Number(c.units_today ?? 0));
      const enCok = Math.max(1, Math.min(Number(kur.maxUnits ?? 4), kalan || 1));
      return `<section class="kart" id="saglik-doktorluk"><div class="kart-bas"><div><p class="ust-yazi">${ç("Doktorluk")}</p>
          <h2 class="b2">${ç("Nöbet tut")}</h2></div><span class="ik-kutu">${ikon("stethoscope")}</span></div>
        ${tip >= en ? `<p class="aciklama">${ç("Tıp becerin {n}. Muayenen yorgunluğu {e} puan indirir ({b} + tıp seviyen).", { n: sayi(tip), e: sayi(Math.min(yorgunlukTavan(), Number(kur.reliefBase ?? 40) + Number(kur.reliefPerLevel ?? 1) * tip)), b: sayi(kur.reliefBase ?? 40) })}</p>` : ""}
        ${engel || `<form class="form" id="saglik-nobet-form" novalidate style="margin-top:10px">
          <label class="alan"><span>${ç("Süre")}</span><select name="birim">${Array.from({ length: Number(kur.maxUnits ?? 4) }, (_, i) => i + 1).map((n) =>
            `<option value="${n}" ${n === Math.min(2, enCok) ? "selected" : ""} ${n > kalan ? "disabled" : ""}>${esc(ç("{n} birim · {dk} dakika · {h} hasta", { n, dk: n * birim, h: n * Math.floor(birim / muayene) }))}</option>`).join("")}</select></label>
          <label class="alan"><span>${ç("Muayene ücreti (kredi, en çok {kr})", { kr: kr(kur.feeMaxCr ?? 300) })}</span><input name="ucret" inputmode="decimal" required value="${esc(krediGirdi(kur.feeDefaultCr ?? 100))}"></label>
          <p class="kucuk">${ç("Bugün {n} / {m} birim çalıştın. Nöbet çizelgende yer tutar ve günlük çalışma sınırına sayılır.", { n: sayi(c.units_today ?? 0), m: sayi(c.daily_work_cap ?? 0) })}</p>
          <div class="form-mesaj" id="saglik-nobet-mesaj"></div>
          <div class="oneri-dugmeler"><button class="dugme altin" type="submit" ${kalan <= 0 ? "disabled" : ""}>${ikon("stethoscope")}${ç("Nöbet aç")}</button></div></form>`}</section>`;
    }
    function gecmisHtml() {
      const v = c.recent_visits ?? [], s = c.recent_shifts ?? [];
      if (!v.length && !s.length) return "";
      return `<section class="kart" id="saglik-gecmis"><div class="kart-bas"><div><p class="ust-yazi">${ç("Geçmiş")}</p><h2 class="b2">${ç("Son muayeneler ve nöbetler")}</h2></div><span class="ik-kutu">${ikon("scroll-text")}</span></div>
        <div class="liste">${v.map((x) => `<div class="liste-satir"><span class="liste-ikon ${x.status === "treated" ? "yesil" : ""}">${ikon(x.status === "treated" ? "heart-pulse" : "undo-2")}</span>
            <div><span class="tur">${esc(zamanOnce(x.done_at ?? x.created_at))} · ${esc(bolgeAdi(x.region_id))}</span><b>${esc(x.doctor ?? ç("Silinmiş doktor"))}</b>
              <div class="alt">${esc(x.status === "treated" ? ç("yorgunluk {a} → {b} · {kr} kredi", { a: sayi(x.fatigue_before ?? 0), b: sayi(x.fatigue_after ?? 0), kr: kr(x.fee_cr ?? 0) })
                : ç("yapılmadı: {neden}", { neden: MUAYENE_IPTAL[x.cancel_reason] ?? "" }))}</div></div><span></span></div>`).join("")}
          ${s.map((x) => `<div class="liste-satir"><span class="liste-ikon altin">${ikon("stethoscope")}</span>
            <div><span class="tur">${esc(zamanOnce(x.ended_at ?? x.starts_at))} · ${esc(bolgeAdi(x.region_id))}</span><b>${esc(ç("Nöbetin: {n} hasta", { n: sayi(x.treated ?? 0) }))}</b>
              <div class="alt">${esc([ç("{n} birim", { n: sayi(x.units ?? 0) }), ç("{kr} kredi kazandın", { kr: kr(x.earned_cr ?? 0) }), NOBET_SON[x.end_reason] ?? null].filter(Boolean).join(" · "))}</div></div><span></span></div>`).join("")}</div></section>`;
    }

    function ciz() {
      durdur();
      kirli = false;
      if (ertelendi) { ertelendi = false; setTimeout(() => arkaTazele()); }
      const f = c.fatigue ?? {};
      kap.innerHTML = `<div class="sayfa">
        <div class="sayfa-bas"><div><p class="ust-yazi">${ç("Şehrim · Sağlık")}</p>
          <h1 class="b1">${c.region_id ? ç("Sağlık ocağı · {sehir}", { sehir: esc(bolgeAdi(c.region_id)) }) : ç("Sağlık ocağı")}</h1>
          <p class="aciklama">${ç("Savaşta biriken yorgunluğu doktorlar giderir. Tıp becerisi olan oyuncular nöbet tutar; yorgunlar sıraya girer.")}</p></div>
          <div class="oneri-dugmeler">${meydanaDonDugme("saglik")}
            <span class="cip ${f.tired ? "mercan" : ""}" id="saglik-yorgunluk-cip">${ikon("heart-pulse")}${esc(ç("Yorgunluk {n}", { n: sayi(f.points ?? 0) }))}</span></div></div>
        ${c.on_road ? `<div class="bilgi-kutusu" style="margin-bottom:14px">${ikon("route")}<span>${ç("Yoldasın; vardığın şehrin sağlık ocağı burada görünür.")}</span></div>` : ""}
        <div id="saglik-sahne-yer"></div>
        <div class="izgara iki">
          <div class="yigin">${yorgunlukHtml()}${siramHtml()}${doktorlarHtml()}</div>
          <div class="yigin">${doktorlukHtml()}${gecmisHtml()}</div>
        </div></div>`;
      const yer = $("#saglik-sahne-yer", kap);
      const b = ben();
      if (yer) { yer.replaceWith(sahne.el); sahne.yaz({ c, ben: { id: b.id, ad: b.name, gorunus, ulke: b.citizenship ?? null } }); }
      bagla();
      durdur = geriSay(kap, () => setTimeout(() => { if (!kapandi) tazele(); }, 1500));
    }

    async function isle(dugme, is) {
      if (dugme?.disabled) return;
      if (dugme) dugme.disabled = true;
      try { await is(); } catch (e) { tost(hataMetni(e), "circle-alert"); } finally { if (dugme?.isConnected) dugme.disabled = false; }
    }
    function siraPenceresi(s) {
      const f = c.fatigue ?? {};
      const sonra = Math.max(0, Number(f.points ?? 0) - Number(s.relief ?? 0));
      pencere({ ust: ç("Sağlık ocağı · {sehir}", { sehir: bolgeAdi(s.region_id) }), baslik: ç("{ad} ile muayene", { ad: s.doctor ?? "" }),
        govde: `<div class="liste"><div class="liste-satir"><span class="liste-ikon yesil">${ikon("clock-3")}</span><div><span class="tur">${ç("Muayene saati")}</span><b>${esc(saatYaz(s.next_slot?.starts_at))}</b></div><span></span></div>
            <div class="liste-satir"><span class="liste-ikon">${ikon("heart-pulse")}</span><div><span class="tur">${ç("Yorgunluk")}</span><b>${esc(ç("{a} → {b}", { a: sayi(f.points ?? 0), b: sayi(sonra) }))}</b></div><span></span></div>
            <div class="liste-satir"><span class="liste-ikon altin">${ikon("coins")}</span><div><span class="tur">${ç("Ücret")}</span><b>${esc(ç("{kr} kredi", { kr: kr(s.fee_cr ?? 0) }))}</b></div><span></span></div></div>
          <p class="kucuk" style="margin-top:10px">${ç("Ücret şimdi ayrılır; muayene saatinde bu şehirde değilsen ya da yorgunluğun kalmamışsa sana döner. Saati başlamadan sıradan çıkabilirsin.")}</p>`,
        dugmeler: [{ ad: ç("Vazgeç") }, { ad: ç("Sıraya gir"), sinif: "altin", ikon: "user-round-plus", is: () => isle(null, async () => {
          const v = await Sunucu.yap("clinic_visit_join", { p_shift: s.shift_id, p_expected_fee: Number(s.fee_cr ?? 0) });
          tost(ç("Sıraya girdin: muayene saatin {saat}.", { saat: saatKisa(v.slot_starts_at) }), "stethoscope");
          Durum.ozet().catch(() => {});
          await tazele();
        }) }] });
    }
    function bagla() {
      meydanaDonBagla(kap);
      for (const b of $$("[data-profil]", kap)) b.onclick = () => profilAc(b.dataset.profil, () => tazele());
      for (const b of $$("[data-git]", kap)) b.onclick = () => Kabuk.git(b.dataset.git);
      for (const b of $$("[data-saglik-gir]", kap)) b.onclick = () => {
        const s = (c.shifts ?? []).find((x) => x.shift_id === b.dataset.saglikGir);
        if (s) siraPenceresi(s);
      };
      $("#saglik-vazgec", kap)?.addEventListener("click", (e) => isle(e.currentTarget, async () => {
        await Sunucu.yap("clinic_visit_cancel", {});
        tost(ç("Sıradan çıktın; ücretin sana döndü."), "undo-2");
        Durum.ozet().catch(() => {});
        await tazele();
      }));
      $("#saglik-bitir", kap)?.addEventListener("click", () => pencere({ ust: ç("Doktorluk"), baslik: ç("Nöbeti bitir"),
        govde: `<p class="aciklama">${ç("Sırada bekleyenlerin ücreti döner; saati dolmuş muayene yapılır. Nöbetin çizelgende şimdiye kadar sayılır.")}</p>`,
        dugmeler: [{ ad: ç("Vazgeç") }, { ad: ç("Nöbeti bitir"), sinif: "mercan", ikon: "square", is: () => isle(null, async () => {
          const x = await Sunucu.yap("clinic_shift_end", {});
          tost(ç("Nöbetin bitti: {n} hasta muayene ettin, {kr} kredi kazandın.", { n: sayi(x.treated ?? 0), kr: kr(x.earned_cr ?? 0) }), "stethoscope");
          Durum.ozet().catch(() => {});
          await tazele();
        }) }] }));
      const f = $("#saglik-nobet-form", kap);
      f?.addEventListener("submit", (e) => {
        e.preventDefault();
        const d = $("button[type=submit]", f);
        const mesaj = $("#saglik-nobet-mesaj", f);
        const hata = (m) => { mesaj.innerHTML = `<div class="hata-kutusu" style="margin-top:8px">${ikon("circle-alert")}<span>${esc(m)}</span></div>`; };
        mesaj.innerHTML = "";
        const fd = new FormData(f);
        const birim = Number(fd.get("birim"));
        const ucret = krediAlt(fd.get("ucret"));
        if (!Number.isFinite(ucret) || ucret < 0 || ucret > Number(R().feeMaxCr ?? 300)) { hata(ç("Ücret 0 ile {kr} kredi arasında olmalı.", { kr: kr(R().feeMaxCr ?? 300) })); return; }
        isle(d, async () => {
          try {
            await Sunucu.yap("clinic_shift_open", { p_units: birim, p_fee: ucret });
          } catch (err) { hata(hataMetni(err)); return; }
          kirli = false;
          tost(ç("Nöbet açtın: {n} birim, ücret {kr} kredi.", { n: birim, kr: kr(ucret) }), "stethoscope");
          await tazele();
        });
      });
    }

    const tazele = tazeleyici(async () => { await yukle(); if (!kapandi) ciz(); });
    const arkaTazele = tazeleyici(async () => { await yukle(); if (kapandi) return; if (kirli) { ertelendi = true; return; } ciz(); });
    await Promise.all([Durum.kurallar().catch(() => null), Durum.ozet().catch(() => null)]);
    await yukle();
    ciz();
    const b1 = Durum.dinle("olay", ({ olay }) => { if (/^(clinic\.|travel\.arrived|war\.)/.test(olay)) yakinda(); });
    const saat = setInterval(() => { if (!document.hidden && !document.querySelector(".perde")) tazeleIste(); }, 30000);
    return () => {
      kapandi = true;
      durdur(); b1(); clearInterval(saat); clearTimeout(bekleyen);
      sahne.kapat();
    };
  },
});

// ===== 98zl_sinif3b.js =====
// ---------- Sınıf (D-143): şehirde verilen dersin 3B yaşayan sahnesi ya da hafif 2B ----------
// Arka duvarda kara tahta: dersin becerisi, öğretmen ve seviyesi, ders hakkı, başlama saati ya da kalan süre (tebeşirle);
// tahtanın solunda öğretmen masası ve becerinin eşyası (askerlikte miğfer ve harita, üretimde çekiç ve alet kutusu, lojistikte
// koliler, yönetimde dosya, müzikte saz, içerik üretiminde kamera, tıpta kalp maketi ve steteskop), duvarda gerçek saatle giden
// saat. Öğretmen (kendi görünümüyle) tahtanın önünde: ders sürerken anlatır, beklerken sınıfı bekler. İki sıra dörder sıra:
// yazılan öğrenciler (görünüşlerinin renkleriyle, kimliksiz) oturur, ders sürerken kitap okur; sen de yazıldıysan kendi
// görünümünle yerindesin; ne öğretmen ne öğrenciysen kapının yanında durursun. Ders yoksa sınıf boş, tahtada "Ders yok".
// Öğretmene dokununca profili, tahtaya dokununca dersin kartı. Yaşayan sahne (D-110): yalnız ekrandayken; masaüstünde 30,
// telefonda 20 kare/sn; hareket azaltılmışsa duruk. Gece ve gündüz şehrin gerçek güneşiyle.

const SINIF_SIRA = [[-2.25, -0.55], [-0.75, -0.55], [0.75, -0.55], [2.25, -0.55], [-2.25, 0.95], [-0.75, 0.95], [0.75, 0.95], [2.25, 0.95]];
const SINIF_OLCEK = 0.64, SINIF_KALABALIK = 0.9, SINIF_OTURAK = 0.26;
const SINIF_BECERI_RENK = { military: "#55603F", production: "#C65A3B", logistics: "#3D5A80", management: "#6B4A32", music: "#7D5FA0",
  content: "#2F6FB5", medicine: "#2E8C83" };

// Dersin (api.lessons satırı) ve kişinin kendisinden sahnenin verisi (3B ve 2B aynı veriyi çizer). l boşsa sınıf boş.
function sinifVerisi(l, ben, bolge) {
  const ogrenciler = (l?.class ?? []).slice(0, SINIF_SIRA.length).map((k) => ({ gorunus: k.look ?? null, ad: k.name ?? null, ben: !!k.me }));
  const benOgrenci = ogrenciler.findIndex((k) => k.ben);
  return {
    anahtar: l?.lesson_id ?? "", bolge: l?.region_id ?? bolge ?? null, sehir: (l?.region_id ?? bolge) ? bolgeAdi(l?.region_id ?? bolge) : "",
    gece: (l?.region_id ?? bolge) ? bolgeGecesi(l?.region_id ?? bolge) : 0,
    ders: l ? { id: l.lesson_id, beceri: l.skill, durum: l.status, baslangic: l.starts_at, bitis: l.ends_at, kapasite: Number(l.capacity ?? 0),
      yazili: Number(l.enrolled ?? 0), hak: Number(l.credit_minutes ?? 0), seviye: Number(l.teacher_level ?? 0),
      ogretmen: { id: l.teacher_id, ad: l.teacher ?? "", gorunus: l.teacher_look?.look ?? null, ulke: l.teacher_look?.country_id ?? null } } : null,
    ogrenciler, benOgrenci,
    ben: { id: ben?.id ?? "", ad: ben?.ad ?? "", gorunus: ben?.gorunus ?? null, ulke: ben?.ulke ?? null, ogretmen: !!l?.mine },
  };
}
// Tahtanın yazısı (3B ve 2B): satırlar
function sinifTahta(d, simdi = Date.now()) {
  const x = d.ders;
  if (!x) return { baslik: ç("Ders yok"), satirlar: [ç("Bu şehirde şu an bekleyen ders yok.")] };
  const sure = x.durum === "running" ? ç("Kalan {n} dakika", { n: Math.max(0, Math.ceil((Date.parse(x.bitis) - simdi) / 60000)) })
    : ç("Başlıyor: {saat}", { saat: saatKisa(x.baslangic) });
  return { baslik: ç("{beceri} dersi", { beceri: beceriAdi(x.beceri) }),
    satirlar: [ç("Öğretmen: {ad} · seviye {n}", { ad: x.ogretmen.ad, n: x.seviye }), ç("Ders hakkı {n} dakika", { n: x.hak }), sure,
      ç("{n} / {m} öğrenci", { n: x.yazili, m: x.kapasite })] };
}

// ---------- 2B: sınıfın önden görünüşü (SVG) ----------
function sinif2b(d) {
  const g0 = Math.round((d.gece ?? 0) * 20) / 20;
  const karis = (a, b, t) => epRenkKaris(a, b, t);
  // Önden görünüş: arka duvar 16–166, zemin 166–370. Derinlik (z) zeminde aşağı iner (tahtanın dibi ≈ 172); zemindeki her şeyin
  // ayağı zeminde: öğretmen tahtanın önünde, masası solda, iki sıra sıra önde
  const P = (x, z) => [350 + x * 66, 172 + (z + 2.9) * 40];
  const x = d.ders, suruyor = x?.durum === "running";
  const T = sinifTahta(d);
  // Kişi (ayakları y'de); konum dış grupta, CSS kıpırtısı iç grupta (CSS dönüşümü SVG'nin konumunu ezmesin). arka: sırtı dönük
  // (başın arkası saçlı)
  const kisi = (px, py, giysi, ten, sinif = "", veri = "", olcek = 1, arka = false) => `<g transform="translate(${px.toFixed(1)} ${py.toFixed(1)}) scale(${olcek})" ${veri}>
      <g class="sinif2b-kisi ${sinif}"><rect class="govde" x="-9" y="-33" width="18" height="24" rx="6" fill="${giysi}"/>
      <rect x="-6.5" y="-10" width="5" height="10" rx="2" fill="#3B3B44"/><rect x="1.5" y="-10" width="5" height="10" rx="2" fill="#3B3B44"/>
      <circle cy="-42" r="9" fill="${ten}"/>${arka ? `<path d="M-9 -43 a9 9 0 0 1 18 0 v5 h-18 z" fill="#3A2C22" opacity=".9"/>` : ""}</g></g>`;
  const siralar = SINIF_SIRA.map(([sx, sz], i) => {
    const [px, py] = P(sx, sz);
    const o = d.ogrenciler[i];
    let k = "";
    if (o) {
      const r = meydanKisiRenk(o.gorunus, o.ad ?? String(i));
      k = kisi(px, py - 2, r.giysi, r.ten, (o.ben ? "ben " : "") + (suruyor ? "okur" : "bekler"), o.ben ? 'data-sinif-sec="ben"' : "", o.ben ? 1 : 0.92, true);
    }
    return `<rect x="${px - 26}" y="${py - 30}" width="52" height="9" rx="2" fill="#B9935E"/><rect x="${px - 22}" y="${py - 21}" width="4" height="18" fill="#7A5C3E"/><rect x="${px + 18}" y="${py - 21}" width="4" height="18" fill="#7A5C3E"/>
      <rect x="${px - 12}" y="${py - 6}" width="24" height="6" rx="2" fill="#3D5A80"/>${k}`;
  }).join("");
  const [tx, ty] = P(-1.05, -2.45);
  const ogr = x ? (() => { const r = meydanKisiRenk(x.ogretmen.gorunus, x.ogretmen.ad); return kisi(tx, ty, r.giysi, r.ten, "ogretmen" + (suruyor ? " anlatir" : "") + (d.ben.ogretmen ? " ben" : ""), `data-sinif-kisi="${esc(x.ogretmen.id)}"`, 1.12); })() : "";
  // Ne öğretmen ne öğrenciysen arka duvarın sağındaki kapının önünde durursun
  const benKapi = !d.ben.ogretmen && d.benOgrenci < 0 && d.ben.id ? (() => { const r = meydanKisiRenk(d.ben.gorunus, d.ben.ad); return kisi(623, 188, r.giysi, r.ten, "ben", 'data-sinif-sec="ben"', 1.05); })() : "";
  const renk = SINIF_BECERI_RENK[x?.beceri] ?? "#4E7A5A";
  return `<svg viewBox="0 0 700 380" role="img" aria-label="${esc(ç("Sınıf (2B): kara tahta, öğretmen ve öğrenciler"))}" data-ders="${x ? x.durum : "yok"}" data-ogrenci="${d.ogrenciler.length}" data-ben="${d.ben.ogretmen ? "ogretmen" : d.benOgrenci >= 0 ? "ogrenci" : "kapi"}">
    <rect x="-600" y="-400" width="1900" height="1180" fill="${karis("#E8E0D0", "#1A1D2A", g0 * 0.85)}"/>
    <rect x="30" y="16" width="640" height="150" fill="${karis("#E9DFC9", "#2A2A36", g0 * 0.6)}"/>
    <rect x="30" y="166" width="640" height="204" fill="${karis("#B89A72", "#3A3028", g0 * 0.55)}"/>
    <rect x="30" y="160" width="640" height="6" fill="${karis(renk, "#202830", g0 * 0.4)}"/>
    <g data-sinif-sec="tahta" class="sinif2b-tik"><rect x="214" y="30" width="272" height="112" rx="5" fill="#6B4E36"/><rect x="222" y="37" width="256" height="98" rx="3" fill="${karis("#2F4F3E", "#1E2E26", g0 * 0.5)}"/>
      <text x="350" y="60" text-anchor="middle" font-size="15" font-weight="800" fill="#F1EDE2" class="sinif2b-tebesir">${esc(T.baslik)}</text>
      ${T.satirlar.map((s, i) => `<text x="350" y="${80 + i * 14}" text-anchor="middle" font-size="9.5" fill="#E2DDD0">${esc(s)}</text>`).join("")}
      <rect x="230" y="135" width="240" height="5" fill="#8B6B4A"/></g>
    <circle cx="560" cy="62" r="20" fill="#FBF8F1" stroke="#6B4E36" stroke-width="3"/><path d="M560 62 v-12 M560 62 h9" stroke="#2B2724" stroke-width="2.4" stroke-linecap="round"/>
    <rect x="130" y="34" width="70" height="78" rx="3" fill="#E9E3D6"/><rect x="135" y="39" width="60" height="68" fill="${karis("#BFDCEB", "#1C2A44", g0)}"/><path d="M165 39 v68 M135 73 h60" stroke="#E9E3D6" stroke-width="3"/>
    <rect x="600" y="62" width="46" height="104" rx="3" fill="${karis("#8B6B4A", "#3A3028", g0 * 0.5)}"/><circle cx="608" cy="116" r="3" fill="#D9B54A"/>
    <rect x="40" y="62" width="70" height="104" rx="3" fill="#8B6B4A"/>${[0, 1, 2].map((i) => `<rect x="46" y="${70 + i * 32}" width="58" height="4" fill="#6B4E36"/>${[0, 1, 2, 3, 4].map((j) => `<rect x="${48 + j * 11}" y="${54 + i * 32}" width="8" height="16" fill="${["#C65A3B", "#367F70", "#D9A548", "#3D5A80", "#7D5FA0"][(i + j) % 5]}"/>`).join("")}`).join("")}
    <rect x="${P(-2.75, -2.0)[0] - 40}" y="${P(-2.75, -2.0)[1] - 28}" width="80" height="12" rx="2" fill="#8B6B4A"/><rect x="${P(-2.75, -2.0)[0] - 34}" y="${P(-2.75, -2.0)[1] - 16}" width="6" height="22" fill="#5B3D28"/><rect x="${P(-2.75, -2.0)[0] + 28}" y="${P(-2.75, -2.0)[1] - 16}" width="6" height="22" fill="#5B3D28"/>
    ${x ? `<circle cx="${P(-2.75, -2.0)[0] + 14}" cy="${P(-2.75, -2.0)[1] - 34}" r="7" fill="${renk}"/>` : ""}
    ${ogr}${siralar}${benKapi}
    ${x ? "" : `<text x="350" y="${P(0, -1.6)[1]}" text-anchor="middle" font-size="12" font-weight="700" fill="${karis("#6B5A48", "#A89A88", g0)}">${esc(ç("Sınıf boş"))}</text>`}
  </svg>`;
}

// ---------- 3B ----------
function sinif3bKur(THREE, cizici) {
  if (!cizici.kur()) throw new Error("webgl-yok");
  const tuval = cizici.renderer.domElement;
  const sahne = new THREE.Scene();
  const kamera = new THREE.PerspectiveCamera(32, 1, 0.1, 120);
  let w = 1, h = 1, kirli = true, kapEl = null, gorunur = true, gozcu = null;
  let d = { anahtar: "", bolge: null, sehir: "", gece: 0, ders: null, ogrenciler: [], benOgrenci: -1,
    ben: { id: "", ad: "", gorunus: null, ulke: null, ogretmen: false } };
  const dinleyici = {};
  const etkinMi = () => cizici.etkin === api;
  const malzeme = new Map();
  const M = (renk, ek = {}) => {
    const k = renk + JSON.stringify(ek);
    if (!malzeme.has(k)) malzeme.set(k, new THREE.MeshStandardMaterial({ color: renk, roughness: 0.8, ...ek }));
    return malzeme.get(k);
  };
  const golgeli = (m) => { m.castShadow = true; m.receiveShadow = true; return m; };
  const kutu = (g, gx, gy, gz, renk, x = 0, y = 0, z = 0) => {
    const m = golgeli(new THREE.Mesh(new THREE.BoxGeometry(gx, gy, gz), typeof renk === "string" ? M(renk) : renk));
    m.position.set(x, y + gy / 2, z);
    g.add(m);
    return m;
  };
  const silindir = (g, r1, r2, yuk, renk, x = 0, y = 0, z = 0, seg = 16) => {
    const m = golgeli(new THREE.Mesh(new THREE.CylinderGeometry(r1, r2, yuk, seg), typeof renk === "string" ? M(renk) : renk));
    m.position.set(x, y + yuk / 2, z);
    g.add(m);
    return m;
  };
  const tuvalDoku = (gen, yuk) => {
    const c = document.createElement("canvas");
    c.width = gen; c.height = yuk;
    const t = new THREE.CanvasTexture(c);
    t.colorSpace = THREE.SRGBColorSpace;
    return { c, t, g: c.getContext("2d") };
  };
  const W = 9.4, D = 6.6;
  const tiklanir = [];

  // ---------- Işık ----------
  const yari = new THREE.HemisphereLight("#FFF6E8", "#5A5048", 1.25);
  const gunes = new THREE.DirectionalLight("#FFF1D8", 1.5);
  gunes.position.set(5, 9, 6);
  gunes.castShadow = true;
  gunes.shadow.mapSize.set(1024, 1024);
  Object.assign(gunes.shadow.camera, { left: -6.5, right: 6.5, top: 5, bottom: -5, near: 1, far: 40 });
  gunes.shadow.camera.updateProjectionMatrix();
  gunes.shadow.bias = -0.0005;
  sahne.add(yari, gunes, gunes.target);
  sahne.background = new THREE.Color("#E8E0D0");

  // ---------- Döşeme, duvarlar, pencereler, kapı ----------
  kutu(sahne, W + 0.6, 0.4, D + 0.6, "#5A4A3A", 0, -0.52, 0);
  kutu(sahne, W, 0.12, D, M("#B89A72", { roughness: 0.75 }), 0, -0.12, 0);              // parke
  const duvarMat = M("#EADFC9", { roughness: 0.95 });
  kutu(sahne, W, 3.0, 0.12, duvarMat, 0, 0, -D / 2);
  kutu(sahne, 0.12, 3.0, D, duvarMat, -W / 2, 0, 0);
  kutu(sahne, 0.12, 3.0, D, duvarMat, W / 2, 0, 0);
  const seritMat = new THREE.MeshStandardMaterial({ color: "#4E7A5A", roughness: 0.7 });   // becerinin renginde (paylaşılmaz)
  const beyaz = new THREE.Color("#FFFFFF");
  const seritler = [kutu(sahne, W, 0.9, 0.02, seritMat, 0, 0, -D / 2 + 0.07)];
  for (const s of [-1, 1]) seritler.push(kutu(sahne, 0.02, 0.9, D, seritMat, s * (W / 2 - 0.07), 0, 0));
  // Sağ duvarda iki pencere (gündüz aydınlık, gece koyu)
  const camMat = new THREE.MeshStandardMaterial({ color: "#BFD9E8", emissive: new THREE.Color("#BFD9E8"), emissiveIntensity: 0.35, roughness: 0.2 });
  for (const z of [-1.4, 1.3]) {
    kutu(sahne, 0.06, 1.3, 1.3, "#F7F2E6", W / 2 - 0.08, 1.2, z);
    const cam = new THREE.Mesh(new THREE.PlaneGeometry(1.14, 1.14), camMat);
    cam.rotation.y = -Math.PI / 2;
    cam.position.set(W / 2 - 0.12, 1.85, z);
    sahne.add(cam);
    kutu(sahne, 0.07, 0.04, 1.16, "#F7F2E6", W / 2 - 0.13, 1.83, z);
  }
  // Kapı (sağ duvarda, önde) ve sol duvarda kitaplık
  kutu(sahne, 0.08, 2.2, 1.0, "#8B6B4A", W / 2 - 0.1, 0, 2.55);
  kutu(sahne, 0.04, 0.06, 0.16, "#D9B54A", W / 2 - 0.16, 1.05, 2.25);
  {
    const raf = new THREE.Group();
    for (const y of [0.05, 0.62, 1.19, 1.76]) kutu(raf, 0.42, 0.05, 1.5, "#6B4E36", 0, y, 0);
    for (const s of [-1, 1]) kutu(raf, 0.42, 1.85, 0.05, "#5B3D28", 0, 0, s * 0.73);
    const renk = ["#C65A3B", "#367F70", "#D9A548", "#3D5A80", "#7D5FA0", "#8B6B4A"];
    for (let k = 0; k < 3; k++) for (let i = 0; i < 9; i++) {
      kutu(raf, 0.3, 0.38 + ((i * 7 + k) % 4) * 0.03, 0.12, renk[(i + k * 2) % renk.length], 0, 0.1 + k * 0.57, -0.62 + i * 0.155);
    }
    raf.position.set(-W / 2 + 0.3, 0, 0.4);
    sahne.add(raf);
  }

  // ---------- Kara tahta (arka duvar) ----------
  const tahtaDoku = tuvalDoku(768, 320);
  const tahta = new THREE.Group();
  {
    kutu(tahta, 4.1, 1.6, 0.08, "#6B4E36", 0, 0, 0);
    const yuz = new THREE.Mesh(new THREE.PlaneGeometry(3.9, 1.48), new THREE.MeshStandardMaterial({ map: tahtaDoku.t, roughness: 0.9 }));
    yuz.position.set(0, 0.8, 0.045);
    tahta.add(yuz);
    kutu(tahta, 3.6, 0.05, 0.14, "#8B6B4A", 0, -0.02, 0.09);
    for (const x of [-1.2, -1.05, 0.9]) kutu(tahta, 0.08, 0.02, 0.02, "#F3F0E8", x, 0.03, 0.1);   // tebeşirler
    tahta.position.set(0, 0.85, -D / 2 + 0.1);
    sahne.add(tahta);
    tiklanir.push({ nesne: tahta, ad: "tahta" });
  }
  let tahtaAnahtar = "";
  function tahtaYaz() {
    const T = sinifTahta(d);
    const a = JSON.stringify([T, DIL.kod]);
    if (a === tahtaAnahtar) return;
    tahtaAnahtar = a;
    const g = tahtaDoku.g;
    g.fillStyle = "#2F4F3E"; g.fillRect(0, 0, 768, 320);
    // Tebeşir izleri (silinmiş yazının gölgesi)
    g.fillStyle = "rgba(241,237,226,.06)";
    for (let i = 0; i < 9; i++) g.fillRect(40 + ((i * 97) % 640), 30 + ((i * 53) % 240), 120, 18);
    g.fillStyle = "#F1EDE2"; g.textAlign = "center"; g.textBaseline = "middle";
    g.font = "800 58px Figtree, system-ui, sans-serif";
    g.fillText(T.baslik, 384, 66, 720);
    g.font = "600 32px Figtree, system-ui, sans-serif"; g.fillStyle = "#E2DDD0";
    T.satirlar.forEach((s, i) => g.fillText(s, 384, 134 + i * 44, 720));
    tahtaDoku.t.needsUpdate = true;
    kirli = true;
  }
  // Duvar saati (tahtanın sağında): şehrin değil, cihazın saati; dakikada bir
  const saat = new THREE.Group();
  const akrep = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.2, 0.02).translate(0, 0.1, 0), M("#2B2724"));
  const yelkovan = new THREE.Mesh(new THREE.BoxGeometry(0.035, 0.28, 0.02).translate(0, 0.14, 0), M("#2B2724"));
  {
    const kadran = new THREE.Mesh(new THREE.CylinderGeometry(0.34, 0.34, 0.05, 28).rotateX(Math.PI / 2), M("#FBF8F1", { roughness: 0.5 }));
    const cerceve = new THREE.Mesh(new THREE.TorusGeometry(0.34, 0.035, 8, 28), M("#6B4E36"));
    akrep.position.z = 0.04; yelkovan.position.z = 0.05;
    saat.add(kadran, cerceve, akrep, yelkovan);
    saat.position.set(3.05, 2.35, -D / 2 + 0.12);
    sahne.add(saat);
  }
  let saatDakika = -1;
  function saatYazdir() {
    const t = new Date();
    const dk = t.getHours() * 60 + t.getMinutes();
    if (dk === saatDakika) return;
    saatDakika = dk;
    yelkovan.rotation.z = -(t.getMinutes() / 60) * Math.PI * 2;
    akrep.rotation.z = -(((t.getHours() % 12) + t.getMinutes() / 60) / 12) * Math.PI * 2;
    kirli = true;
  }

  // ---------- Öğretmen masası ve becerinin eşyası ----------
  const masa = new THREE.Group();
  kutu(masa, 1.3, 0.06, 0.62, "#8B6B4A", 0, 0.56, 0);
  for (const [a, b] of [[-0.6, -0.26], [0.6, -0.26], [-0.6, 0.26], [0.6, 0.26]]) kutu(masa, 0.06, 0.56, 0.06, "#5B3D28", a, 0, b);
  kutu(masa, 0.28, 0.04, 0.2, "#F7F4EC", -0.35, 0.62, 0.05);
  masa.position.set(-2.75, 0, -2.0);
  sahne.add(masa);
  const esyalar = {};
  {
    const yap = (ad, fn) => { const g = new THREE.Group(); g.position.set(0.25, 0.62, 0); fn(g); g.visible = false; masa.add(g); esyalar[ad] = g; };
    yap("military", (g) => {
      const m = golgeli(new THREE.Mesh(new THREE.SphereGeometry(0.16, 16, 10, 0, Math.PI * 2, 0, Math.PI / 2), M("#556043", { roughness: 0.6 })));
      g.add(m);
      kutu(g, 0.34, 0.01, 0.24, "#D9C9A0", -0.4, 0, 0.02);
    });
    yap("production", (g) => {
      kutu(g, 0.36, 0.14, 0.18, "#C65A3B", 0, 0, 0);
      const sap = silindir(g, 0.015, 0.015, 0.3, "#8B5A2B", -0.3, 0.02, 0.05, 8);
      sap.rotation.z = Math.PI / 2;
      kutu(g, 0.08, 0.06, 0.06, "#5E6670", -0.42, 0.0, 0.05);
    });
    yap("logistics", (g) => {
      kutu(g, 0.24, 0.18, 0.2, "#B07A4A", 0, 0, 0);
      kutu(g, 0.2, 0.14, 0.16, "#A9845E", 0.02, 0.18, 0);
      kutu(g, 0.18, 0.12, 0.16, "#B07A4A", -0.26, 0, 0.02);
    });
    yap("management", (g) => {
      kutu(g, 0.26, 0.04, 0.34, "#3D5A80", 0, 0, 0);
      kutu(g, 0.24, 0.02, 0.3, "#F3F0E8", 0, 0.04, 0);
      kutu(g, 0.26, 0.04, 0.34, "#D9A548", -0.32, 0, 0.02);
    });
    yap("music", (g) => {
      const gov = golgeli(new THREE.Mesh(new THREE.SphereGeometry(0.13, 14, 10), M("#B06A2E")));
      gov.scale.set(1, 0.45, 1.3);
      gov.position.y = 0.06;
      g.add(gov);
      const sap = kutu(g, 0.04, 0.03, 0.5, "#5B3D28", 0, 0.06, -0.38);
      sap.rotation.x = 0.12;
    });
    yap("content", (g) => {
      kutu(g, 0.22, 0.14, 0.14, "#2E3238", 0, 0, 0);
      const m = silindir(g, 0.045, 0.055, 0.1, "#1B1E24", 0, 0.03, 0.11, 12);
      m.rotation.x = Math.PI / 2;
    });
    yap("medicine", (g) => {
      silindir(g, 0.06, 0.08, 0.04, "#6B4E36", 0, 0, 0, 12);
      silindir(g, 0.012, 0.012, 0.12, metal(), 0, 0.04, 0, 6);
      const kalp = new THREE.Group();
      for (const x of [-0.05, 0.05]) { const s = golgeli(new THREE.Mesh(new THREE.SphereGeometry(0.07, 12, 10), M("#B5462F", { roughness: 0.5 }))); s.position.set(x, 0.24, 0); kalp.add(s); }
      const uc = golgeli(new THREE.Mesh(new THREE.ConeGeometry(0.1, 0.14, 12), M("#B5462F", { roughness: 0.5 })));
      uc.rotation.z = Math.PI; uc.position.y = 0.15;
      kalp.add(uc);
      g.add(kalp);
      const steto = golgeli(new THREE.Mesh(new THREE.TorusGeometry(0.11, 0.012, 6, 18), M("#33383E", { roughness: 0.45 })));
      steto.rotation.x = Math.PI / 2; steto.position.set(-0.36, 0.01, 0.04);
      g.add(steto);
    });
  }
  function metal() { return M("#AEB6BC", { metalness: 0.55, roughness: 0.35 }); }

  // ---------- Sıralar ve sandalyeler ----------
  for (const [x, z] of SINIF_SIRA) {
    const g = new THREE.Group();
    kutu(g, 0.9, 0.05, 0.44, "#B9935E", 0, 0.5, 0);
    for (const s of [-1, 1]) kutu(g, 0.05, 0.5, 0.4, "#7A5C3E", s * 0.4, 0, 0);
    const sandalye = new THREE.Group();
    kutu(sandalye, 0.42, 0.05, 0.38, "#3D5A80", 0, SINIF_OTURAK - 0.05, 0);
    kutu(sandalye, 0.42, 0.42, 0.05, "#3D5A80", 0, SINIF_OTURAK, 0.2);
    for (const a of [-0.17, 0.17]) for (const b of [-0.15, 0.15]) kutu(sandalye, 0.03, SINIF_OTURAK - 0.05, 0.03, "#2A2724", a, 0, b);
    sandalye.position.z = 0.48;
    g.add(sandalye);
    g.position.set(x, 0, z);
    sahne.add(g);
  }

  // ---------- Kişiler: öğretmen ve sen (tam figür), öğrenciler (kalabalık, görünüşlerinin renkleriyle) ----------
  const yuvaKur = () => {
    const fp = figurParcasi(THREE);
    fp.grup.scale.setScalar(SINIF_OLCEK);
    const kok = new THREE.Group();
    kok.add(fp.grup);
    kok.visible = false;
    sahne.add(kok);
    const y = { fp, kok, id: null, eylem: "bekle", faz: 0 };
    tiklanir.push({ nesne: kok, ad: "kisi", yuva: y });
    return y;
  };
  const ogretmenYuva = yuvaKur(), benYuva = yuvaKur();
  const kalabalik = kalabalikKur(THREE, SINIF_SIRA.length);
  sahne.add(kalabalik.grup);
  let kisiAnahtar = "";
  function kisileriYaz() {
    const x = d.ders, suruyor = x?.durum === "running";
    const anahtar = JSON.stringify([x?.ogretmen, x?.durum, d.ogrenciler, d.benOgrenci, d.ben]);
    if (anahtar === kisiAnahtar) return;
    kisiAnahtar = anahtar;
    ogretmenYuva.kok.visible = !!x;
    if (x) {
      ogretmenYuva.id = x.ogretmen.id;
      ogretmenYuva.fp.kur({ anahtar: x.ogretmen.id, ad: x.ogretmen.ad, gorunus: x.ogretmen.gorunus, ulke: x.ogretmen.ulke, rutbe: { sira: 0, sayi: 12 }, ek: null });
      ogretmenYuva.eylem = suruyor ? "anlat" : "bekle";
      ogretmenYuva.kok.position.set(-1.05, 0.02, -2.45);
      ogretmenYuva.kok.rotation.y = suruyor ? 0.25 : 0.1;
      ogretmenYuva.faz = (ozet(String(x.ogretmen.id)) % 1000) / 1000;
    }
    // Sen: öğretmensen yukarıda; öğrenciysen sıranda (tahtaya dönük); değilsen kapının yanında
    benYuva.kok.visible = !!d.ben.id && !d.ben.ogretmen;
    if (benYuva.kok.visible) {
      benYuva.id = d.ben.id;
      benYuva.fp.kur({ anahtar: d.ben.id, ad: d.ben.ad, gorunus: d.ben.gorunus, ulke: d.ben.ulke, rutbe: { sira: 0, sayi: 12 }, ek: null });
      if (d.benOgrenci >= 0) {
        const [sx, sz] = SINIF_SIRA[d.benOgrenci];
        benYuva.eylem = suruyor ? "oku" : "otur";
        benYuva.kok.position.set(sx, 0.02, sz + 0.5);
        benYuva.kok.rotation.y = Math.PI;
      } else {
        benYuva.eylem = "bekle";
        benYuva.kok.position.set(3.85, 0.02, 2.45);
        benYuva.kok.rotation.y = -0.5;
      }
    }
    kalabalik.yaz(d.ogrenciler.map((o, i) => {
      if (o.ben) return null;
      const [sx, sz] = SINIF_SIRA[i];
      const r = meydanKisiRenk(o.gorunus, o.ad ?? String(i));
      return { x: sx, z: sz + 0.5, y: SINIF_OTURAK - 0.3 * SINIF_KALABALIK, yon: Math.PI, eylem: suruyor ? "otur" : i % 2 ? "otur_bekle" : "otur",
        olcek: SINIF_KALABALIK, giysi: r.giysi, ten: r.ten, alt: r.alt, sapka: r.sapka, faz: i * 0.31 };
    }).filter(Boolean));
    kirli = true;
  }

  // ---------- Kamera ----------
  const YON = new THREE.Vector3(0, 0.78, 1).normalize(), YON_DAR = new THREE.Vector3(0, 1.05, 1).normalize();
  function kameraKur() {
    kamera.aspect = w / h;
    const dar = w / h < 1.3;
    const n = [[-W / 2, 0, D / 2], [W / 2, 0, D / 2], [-W / 2, 2.9, -D / 2], [W / 2, 2.9, -D / 2]].map(([a, b, c]) => new THREE.Vector3(a, b, c));
    kameraSigdir(THREE, kamera, n, dar ? YON_DAR : YON, { x: 0.99, ust: 0.95, alt: -0.97 });
    kirli = true;
  }

  // ---------- Etkileşim ----------
  const isin = new THREE.Raycaster(), imlec = new THREE.Vector2();
  tuval.addEventListener("pointerup", (e) => {
    if (!etkinMi()) return;
    const rr = tuval.getBoundingClientRect();
    imlec.set(((e.clientX - rr.left) / rr.width) * 2 - 1, -((e.clientY - rr.top) / rr.height) * 2 + 1);
    isin.setFromCamera(imlec, kamera);
    const adaylar = tiklanir.filter((x) => x.nesne.visible).map((x) => x.nesne);
    const vur = isin.intersectObjects(adaylar, true)[0];
    if (!vur) return;
    let o = vur.object;
    while (o && !tiklanir.some((x) => x.nesne === o)) o = o.parent;
    const t = tiklanir.find((x) => x.nesne === o);
    if (!t) return;
    if (t.ad === "kisi") {
      if (t.yuva === benYuva) dinleyici.sec?.("ben");
      else if (t.yuva.id) dinleyici.sec?.("kisi", t.yuva.id);
      return;
    }
    dinleyici.sec?.(t.ad, d.ders?.id ?? null);
  });

  function isikUygula() {
    const g = d.gece ?? 0;
    sahne.background.set("#E8E0D0").lerp(new THREE.Color("#1A1D2A"), g * 0.88);
    // Sınıf gece de aydınlık (tavan lambaları): gece yalnız pencereler ve arka plan kararır
    yari.intensity = 1.3 - g * 0.25;
    gunes.intensity = 1.5 * (1 - g * 0.55);
    camMat.emissive.set(g > 0.5 ? "#1C2A3C" : "#BFD9E8");
    camMat.emissiveIntensity = g > 0.5 ? 0.25 : 0.35;
    seritMat.color.set(SINIF_BECERI_RENK[d.ders?.beceri] ?? "#4E7A5A").lerp(beyaz, 0.45);
    for (const [ad, g2] of Object.entries(esyalar)) g2.visible = ad === d.ders?.beceri;
    kirli = true;
  }
  function yaz() {
    tahtaYaz();
    kisileriYaz();
    isikUygula();
    saatYazdir();
    if (kapEl) {
      const ds = kapEl.dataset;
      const yeni = { ders: d.ders ? d.ders.durum : "yok", ogrenci: String(d.ogrenciler.length), ben: d.ben.ogretmen ? "ogretmen" : d.benOgrenci >= 0 ? "ogrenci" : "kapi" };
      for (const [k, v] of Object.entries(yeni)) if (ds[k] !== v) ds[k] = v;
    }
    kirli = true;
  }

  let tahtaSaat = 0;
  const api = {
    get etiket() { return ç("Sınıf (3B): kara tahta, öğretmen ve öğrenciler"); },
    sahne, kamera,
    get kareMs() { return !gorunur || hareketAzalt ? 1000 : telefon() ? 50 : 33; },
    dinle(ad, fn) { dinleyici[ad] = fn; },
    kapBagla(el) {
      kapEl = el ?? null;
      gozcu?.disconnect();
      gozcu = null;
      if (kapEl && typeof IntersectionObserver !== "undefined") {
        gozcu = new IntersectionObserver((g) => { gorunur = g.some((x) => x.isIntersecting); kirli = true; });
        gozcu.observe(kapEl);
      }
      kisiAnahtar = ""; tahtaAnahtar = ""; saatDakika = -1;
      yaz();
    },
    get cizimSayisi() { let n = 0; sahne.traverseVisible((o) => { if (o.isMesh) n++; }); return n; },
    durumYaz(y) { d = { ...d, ...y }; yaz(); },
    kalite(k) { gunes.castShadow = k !== "dusuk"; kirli = true; },
    boyut(gen, yuk) { w = gen; h = yuk; kameraKur(); },
    etkinlestir(acik) { if (acik) kirli = true; },
    guncelle(dt, t) {
      if (!gorunur) return;
      for (const y of [ogretmenYuva, benYuva]) {
        if (!y.kok.visible) continue;
        const sure = y.fp.eylemSuresi(y.eylem) || 3;
        y.fp.pozla(y.eylem, ((t + y.faz * sure) % sure) / sure, t + y.faz * 7, hareketAzalt, true);
        if (!hareketAzalt) y.fp.canli(t + y.faz * 5);
      }
      if (!hareketAzalt) kalabalik.guncelle(t);
      // Kalan süre ve saat dakikada bir
      if (performance.now() - tahtaSaat > 20000) { tahtaSaat = performance.now(); tahtaYaz(); saatYazdir(); }
      kirli = true;
    },
    cizilmeli() { const c = kirli; kirli = false; return c; },
  };
  return api;
}

// ---------- Sınıfın kartı (Hayatım → Dersler): 3B ya da 2B, başlık ve özet yazı ----------
let sinif3bOrnek = null;
const SinifSahnesi = (() => {
  function ac() {
    const el = document.createElement("section");
    el.className = "kart sinif-kart";
    el.id = "sinif-oda";
    let d = null, hata3b = false, kapandi = false;
    const mod3b = () => Gorunum.uc() && !hata3b;
    let mod = mod3b() ? "3b" : "2b";
    const dinleyici = {};
    const sec = (ad, id) => dinleyici.sec?.(ad, id);
    const ikiBBagla = (kok) => {
      for (const g of $$("[data-sinif-kisi]", kok)) g.addEventListener("click", (e) => { e.stopPropagation(); sec("kisi", g.dataset.sinifKisi); });
      for (const g of $$("[data-sinif-sec]", kok)) g.addEventListener("click", (e) => { e.stopPropagation(); sec(g.dataset.sinifSec, d?.ders?.id ?? null); });
    };
    const baslik = (x) => (!x.ders ? ç("Sınıf boş") : x.ders.durum === "running" ? ç("Ders sürüyor") : ç("Ders bekliyor"));
    const yazi = (x) => {
      if (!x.ders) return ç("Şu an bu şehirde ders yok. Becerin en az {n} ise sen ders verebilirsin.", { n: Number(Durum.v.kurallar?.data?.profession?.lessons?.minSkill ?? 20) });
      const y = x.ders;
      return [ç("{beceri} dersi, öğretmen {ad} (seviye {n}).", { beceri: beceriAdi(y.beceri), ad: y.ogretmen.ad, n: y.seviye }),
        y.durum === "running" ? ç("Bitiş {saat}.", { saat: saatKisa(y.bitis) }) : ç("Başlangıç {saat}.", { saat: saatKisa(y.baslangic) }),
        ç("{n} / {m} öğrenci.", { n: y.yazili, m: y.kapasite }),
        x.ben.ogretmen ? ç("Bu ders senin.") : x.benOgrenci >= 0 ? ç("Bu derse yazıldın.") : ""].filter(Boolean).join(" ");
    };

    function ciz() {
      if (!d) return;
      el.innerHTML = `<div class="kart-bas"><div><p class="ust-yazi">${ç("Sınıf")}${d.sehir ? " · " + esc(d.sehir) : ""}</p>
          <h2 class="b2" id="sinif-oda-baslik">${esc(baslik(d))}</h2></div>
          ${Gorunum.webglVar() ? `<button class="dugme sade kucuk-d" id="sinif-mod" aria-pressed="${mod === "2b"}" title="${mod === "3b" ? ç("Hafif görünüme (2B) geç") : ç("3B görünüme geç")}">${ikon("layers")}${mod === "3b" ? ç("2B") : ç("3B")}</button>` : ""}</div>
        <div class="sinif-sahne sahne3b" id="sinif-sahne" data-mod="${mod}">
          ${mod === "3b" ? `<div class="yukleniyor sinif-on${sinif3bOrnek && Uc.cizici?.etkin === sinif3bOrnek ? " bitti" : ""}" id="sinif-yukleniyor" aria-label="${ç("Sınıf açılıyor…")}">${sinif2b(d)}</div>` : ""}
          <div class="sinif-2b" id="sinif-2b"${mod === "3b" ? " hidden" : ""}>${mod === "2b" ? sinif2b(d) : ""}</div>
        </div>
        <p class="kucuk" style="margin-top:8px" id="sinif-oda-yazi">${esc(yazi(d))}</p>`;
      $("#sinif-mod", el)?.addEventListener("click", () => {
        hata3b = false;
        const ikiB = mod === "3b";
        Gorunum.ayarla(ikiB ? "2b" : "3b");
        tost(ikiB ? ç("Hafif görünüm (2B) seçildi. Ayarlar'dan değiştirebilirsin.") : ç("3B görünüm seçildi."), "layers");
      });
      ikiBBagla($("#sinif-2b", el));
      sahneBagla();
    }
    const etkin3b = () => mod === "3b" && sinif3bOrnek && Uc.cizici?.etkin === sinif3bOrnek;
    function sahneBirak() { if (sinif3bOrnek && Uc.cizici?.etkin === sinif3bOrnek) Uc.cizici.birak(sinif3bOrnek); }
    async function sahneBagla() {
      const kutu = $("#sinif-sahne", el);
      if (!kutu || mod !== "3b") { sahneBirak(); return; }
      try {
        const { THREE, cizici } = await Uc.yukle();
        if (kapandi || mod !== "3b" || $("#sinif-sahne", el) !== kutu) return;
        sinif3bOrnek ??= sinif3bKur(THREE, cizici);
        const a = sinif3bOrnek;
        a.dinle("sec", sec);
        a.kapBagla(kutu);
        a.durumYaz(d);
        if (!cizici.bagla(a, kutu)) throw new Error("webgl-bagla");
        $("#sinif-yukleniyor", kutu)?.classList.add("bitti");
      } catch (e) {
        console.warn("3B sınıf açılamadı:", e);
        if (kapandi) return;
        hata3b = true; mod = "2b";
        tost(ç("3B sahne bu cihazda açılamadı; hafif görünüm gösteriliyor."), "layers");
        ciz();
      }
    }
    function tazeCiz() {
      const b = $("#sinif-oda-baslik", el);
      if (b) b.textContent = baslik(d);
      const y = $("#sinif-oda-yazi", el);
      if (y) y.textContent = yazi(d);
      if (etkin3b()) sinif3bOrnek.durumYaz(d);
      else if (mod === "2b") { const k = $("#sinif-2b", el); if (k) { k.innerHTML = sinif2b(d); ikiBBagla(k); } }
    }
    // veri: { l (api.lessons satırı ya da null), ben: { id, ad, gorunus, ulke }, bolge }
    function yaz(veri) {
      d = sinifVerisi(veri.l, veri.ben, veri.bolge);
      if (!el.isConnected || !el.childElementCount) { ciz(); return; }
      tazeCiz();
      if (mod === "3b" && !etkin3b()) sahneBagla();
    }
    const b1 = Gorunum.dinle(() => { const yeni = mod3b() ? "3b" : "2b"; if (yeni !== mod && d) { mod = yeni; ciz(); } });
    function kapat() { kapandi = true; b1(); sahneBirak(); }
    return { el, yaz, kapat, birak: sahneBirak, dinle(ad, fn) { dinleyici[ad] = fn; } };
  }
  return { ac };
})();

// ===== 98zm_dersler.js =====
// ---------- Hayatım → Dersler (D-143): şehirde verilen beceri dersleri ----------
// Üstte sınıfın sahnesi (98zl_sinif3b.js): sürdüğün ya da yazıldığın ders, yoksa şehrin sıradaki dersi ("Sınıfı gör" başka
// bir dersi gösterir). Bu şehirdeki dersler (beceri, öğretmen ve seviyesi, saat, ücret, ders hakkı, yer; "Yazıl" ya da
// "Kaydı bırak"), yazıldığın dersler (başka şehirde de), ders hakların (beceri başına dakika; o becerideki eğitimden düşülür),
// ders ver (becerisi yeterliyse: beceri, saat, ücret, kontenjan) ve verdiğin dersler (öğrencileri, iptal; son dersler).
// Karar sunucuda (profession-1.0.0); ekran sınırları gösterir ve önceden denetler. Yarım dakikada bir ve olaylarda tazelenir.

const DERS_DURUM = { scheduled: ç("Bekliyor"), running: ç("Sürüyor"), completed: ç("Bitti"), cancelled: ç("İptal edildi") };
const DERS_IPTAL = { teacher: ç("öğretmen iptal etti"), empty: ç("kimse yazılmadı"), teacher_away: ç("öğretmen şehirde değildi"), deleted: ç("hesap silindi"),
  student: ç("kaydı bıraktın"), absent: ç("ders saatinde şehirde değildin") };

Kabuk.kaydet("hayat/dersler", {
  async ac(kap) {
    let v = null;            // api.lessons
    let kapandi = false;
    let durdur = () => {};
    let odak = null;         // sahnede gösterilen ders (kişi seçtiyse)
    const sahne = SinifSahnesi.ac();
    sahne.dinle("sec", (ad, id) => {
      if (ad === "kisi") { if (id) profilAc(id, () => tazele()); return; }
      const el = (ad === "tahta" && id ? $(`[data-ders-satir="${CSS.escape(id)}"]`, kap) : null) ?? $(ad === "ben" ? "#dersler-ogrenci" : "#dersler-sehir", kap);
      if (!el) return;
      el.scrollIntoView({ behavior: hareketAzalt ? "auto" : "smooth", block: "center" });
      el.classList.remove("vurgu-yan"); void el.offsetWidth; el.classList.add("vurgu-yan");
    });
    const ben = () => Durum.v.ozet?.character ?? {};
    let gorunus;
    let bekleyen = null;
    const yakinda = () => { clearTimeout(bekleyen); bekleyen = setTimeout(() => { if (!kapandi) tazele(); }, 600); };
    let kirli = false, ertelendi = false;
    kap.addEventListener("input", (e) => { if (e.target.closest("#dersler-ac-form")) kirli = true; });
    const tazeleIste = () => { if (kirli) ertelendi = true; else tazele(); };

    async function yukle() {
      const [x, bak] = await Promise.all([Sunucu.cagir("lessons"), gorunus === undefined ? Sunucu.cagir("my_look").catch(() => null) : null]);
      v = x;
      if (gorunus === undefined) gorunus = bak?.look ?? null;
    }
    const R = () => v?.rule ?? meslekKurali().lessons ?? {};
    const beceriler = () => (v?.skills_list ?? Object.keys(BECERI)).filter((b) => BECERI[b]);
    // Sahnenin dersi: seçilen; değilse sürdüğüm, yazıldığım (bu şehirde), şehrin sıradaki dersi
    function sahneDersi() {
      const sehir = v.city ?? [];
      const hepsi = [...sehir, ...(v.teaching ?? []), ...(v.learning ?? [])];
      const sec = odak ? hepsi.find((l) => l.lesson_id === odak) : null;
      if (sec) return sec;
      odak = null;
      const burada = (l) => l.region_id === v.region_id;
      return (v.teaching ?? []).find((l) => l.status === "running" && burada(l)) ?? (v.learning ?? []).find((l) => l.status === "running" && burada(l))
        ?? [...(v.teaching ?? []), ...(v.learning ?? [])].filter(burada).sort((a, b) => Date.parse(a.starts_at) - Date.parse(b.starts_at))[0]
        ?? sehir[0] ?? null;
    }

    // Yazılmanın önündeki engel (sunucu da denetler)
    function yazilmaEngeli(l) {
      if (l.mine) return ç("Kendi dersin");
      if (l.status !== "scheduled") return ç("Ders başladı");
      if (v.on_road) return ç("Yoldasın");
      if (l.my_seat?.status === "enrolled") return null;
      const sev = Number(v.skills?.[l.skill] ?? 0), en = Number(l.teacher_level ?? 0) - Number(R().gapLevels ?? 5);
      if (sev > en) return ç("Seviyen yüksek (en çok {n})", { n: sayi(Math.max(0, en)) });
      if (l.blocked) return ç("Bu derse yazılamazsın");
      if (Number(l.enrolled ?? 0) >= Number(l.capacity ?? 0)) return ç("Yer yok");
      return null;
    }
    function dersSatir(l, { sahneDugme = true } = {}) {
      const yazili = l.my_seat?.status === "enrolled";
      const engel = yazilmaEngeli(l);
      const suruyor = l.status === "running";
      return `<div class="liste-satir ders-satir" data-ders-satir="${esc(l.lesson_id)}"><span class="liste-ikon ${suruyor ? "mercan" : yazili ? "yesil" : ""}">${ikon(BECERI[l.skill]?.ik ?? "presentation")}</span>
        <div><span class="tur">${esc(suruyor ? ç("Şimdi · bitiş {saat}", { saat: saatKisa(l.ends_at) }) : saatYaz(l.starts_at))}${l.region_id !== v.region_id ? " · " + esc(bolgeAdi(l.region_id)) : ""}</span>
          <b>${esc(ç("{beceri} dersi", { beceri: beceriAdi(l.skill) }))}</b>
          <div class="alt">${l.mine ? esc(ç("senin dersin")) : `<button class="baglanti" type="button" data-profil="${esc(l.teacher_id)}">${esc(l.teacher ?? "")}</button>`} · ${esc([ç("seviye {n}", { n: sayi(l.teacher_level ?? 0) }),
            ç("{kr} kredi", { kr: kr(l.fee_cr ?? 0) }), ç("ders hakkı {n} dk", { n: sayi(l.credit_minutes ?? 0) }), ç("{n} / {m} yer", { n: sayi(l.enrolled ?? 0), m: sayi(l.capacity ?? 0) })].join(" · "))}</div>
          ${engel && !yazili && !l.mine ? `<div class="alt saglik-engel">${esc(engel)}</div>` : ""}</div>
        <div class="mekan-satir-dugmeler">${sahneDugme ? `<button class="dugme sade kucuk-d" data-ders-goster="${esc(l.lesson_id)}" title="${esc(ç("Sınıfı gör"))}">${ikon("presentation")}${ç("Sınıf")}</button>` : ""}
          ${l.mine ? "" : yazili ? (l.status === "scheduled" ? `<button class="dugme ikincil kucuk-d" data-ders-birak="${esc(l.lesson_id)}">${ikon("x")}${ç("Kaydı bırak")}</button>` : `<span class="cip yesil">${ç("Yazıldın")}</span>`)
            : `<button class="dugme kucuk-d" data-ders-yazil="${esc(l.lesson_id)}" ${engel ? "disabled" : ""}>${ikon("user-round-plus")}${ç("Yazıl")}</button>`}</div></div>`;
    }
    function sehirHtml() {
      const l = (v.city ?? []).filter((x) => !x.mine);
      return `<section class="kart" id="dersler-sehir"><div class="kart-bas"><div><p class="ust-yazi">${esc(v.region_id ? bolgeAdi(v.region_id) : ç("Yoldasın"))}</p>
          <h2 class="b2">${ç("Bu şehirdeki dersler")}</h2></div><span class="ik-kutu">${ikon("presentation")}</span></div>
        ${l.length ? `<div class="liste">${l.map((x) => dersSatir(x)).join("")}</div>`
          : `<p class="bos">${v.on_road ? ç("Yoldasın; vardığın şehrin dersleri burada görünür.") : ç("Şu an bu şehirde bekleyen ders yok. Becerin en az {n} ise sen ders verebilirsin.", { n: sayi(R().minSkill ?? 20) })}</p>`}
        <p class="kucuk" style="margin-top:8px">${ç("Ders {dk} dakika sürer. O becerin öğretmeninkinden en az {f} seviye aşağıdaysa yazılırsın (günde {g} ders). Ücret yazılırken ayrılır; ders saatinde şehirde değilsen döner. Ders bitince ders hakkı kazanırsın.",
          { dk: sayi(R().unitMinutes ?? 30), f: sayi(R().gapLevels ?? 5), g: sayi(R().studentDaily ?? 1) })}</p></section>`;
    }
    function ogrenciHtml() {
      const l = v.learning ?? [], h = v.credits ?? {}, son = v.learned ?? [];
      const haklar = Object.entries(h).filter(([, m]) => Number(m) > 0);
      return `<section class="kart" id="dersler-ogrenci"><div class="kart-bas"><div><p class="ust-yazi">${ç("Öğrencilik")}</p>
          <h2 class="b2">${l.length ? ç("{n} derse yazıldın", { n: sayi(l.length) }) : ç("Ders hakların")}</h2></div><span class="ik-kutu">${ikon("graduation-cap")}</span></div>
        ${l.length ? `<div class="liste">${l.map((x) => dersSatir(x)).join("")}</div>` : ""}
        ${haklar.length ? `<div class="liste" style="margin-top:${l.length ? 10 : 0}px">${haklar.map(([b, m]) => `<div class="liste-satir"><span class="liste-ikon yesil">${ikon(BECERI[b]?.ik ?? "graduation-cap")}</span>
            <div><span class="tur">${ç("Ders hakkı")}</span><b>${esc(ç("{beceri}: {n} dakika", { beceri: beceriAdi(b), n: sayi(m) }))}</b><div class="alt">${esc(ç("sonraki {beceri} eğitiminden düşülür", { beceri: beceriAdi(b) }))}</div></div>
            <button class="dugme sade kucuk-d" data-git="hayat/egitim">${ikon("graduation-cap")}${ç("Eğitim")}</button></div>`).join("")}</div>`
          : `<p class="bos">${ç("Ders hakkın yok. Bir derse girince ders hakkı kazanırsın: o becerideki süren eğitimin hemen kısalır, artanı {g} gün içinde sonraki eğitimden düşülür.", { g: sayi(R().creditDays ?? 7) })}</p>`}
        ${son.length ? `<p class="ust-yazi" style="margin-top:12px">${ç("Son derslerin")}</p><div class="liste">${son.map((x) => `<div class="liste-satir"><span class="liste-ikon">${ikon(BECERI[x.skill]?.ik ?? "presentation")}</span>
            <div><span class="tur">${esc(zamanOnce(x.ends_at))} · ${esc(x.teacher ?? "")}</span><b>${esc(ç("{beceri} dersi", { beceri: beceriAdi(x.skill) }))}</b>
              <div class="alt">${esc(x.my_seat?.status === "attended" ? ç("katıldın: {n} dakika ders hakkı", { n: sayi(x.my_seat?.credit_minutes ?? 0) }) : ç("katılmadın: {neden}", { neden: DERS_IPTAL[x.my_seat?.cancel_reason ?? x.cancel_reason] ?? "" }))}</div></div><span></span></div>`).join("")}</div>` : ""}</section>`;
    }
    function ogretmenHtml() {
      const kur = R(), en = Number(kur.minSkill ?? 20);
      const uygun = beceriler().filter((b) => Number(v.skills?.[b] ?? 0) >= en);
      const bekleyen = (v.teaching ?? []).filter((l) => l.status === "scheduled").length;
      const sicil = v.record_until && Date.parse(v.record_until) > Date.now();
      const kalan = Math.max(0, Number(v.daily_work_cap ?? 0) - Number(v.units_today ?? 0));
      const engel = !uygun.length ? `<div class="bilgi-kutusu">${ikon("graduation-cap")}<span>${ç("Ders vermek için bir becerin en az {n} olmalı. Hayatım → Eğitim'den çalışabilirsin.", { n: sayi(en) })}</span></div>`
        : sicil ? `<div class="hata-kutusu">${ikon("scale")}<span>${ç("Sicil kaydın nedeniyle {zaman} tarihine kadar ders veremezsin.", { zaman: esc(saatYaz(v.record_until)) })}</span></div>`
        : v.on_road ? `<div class="bilgi-kutusu">${ikon("route")}<span>${ç("Yoldayken ders açılmaz; vardığın şehirde açarsın.")}</span></div>`
        : bekleyen >= Number(kur.upcomingMax ?? 3) ? `<div class="bilgi-kutusu">${ikon("calendar")}<span>${ç("Aynı anda en çok {n} bekleyen dersin olabilir.", { n: sayi(kur.upcomingMax ?? 3) })}</span></div>`
        : kalan <= 0 ? `<div class="bilgi-kutusu">${ikon("hourglass")}<span>${ç("Bugünkü çalışma sınırın doldu.")}</span></div>` : "";
      const simdi = Date.now();
      const yerel = (t) => { const z = new Date(t); z.setMinutes(z.getMinutes() - z.getTimezoneOffset()); return z.toISOString().slice(0, 16); };
      const enErken = simdi + (Number(kur.leadMinutes ?? 10) + 1) * 60000, enGec = simdi + Number(kur.horizonHours ?? 72) * 3600000;
      const oneri = Math.ceil((simdi + 60 * 60000) / (15 * 60000)) * 15 * 60000;
      const ogretim = (v.teaching ?? []).map((l) => {
        const ogr = l.students ?? [];
        return `<div class="liste-satir ders-satir" data-ders-satir="${esc(l.lesson_id)}"><span class="liste-ikon ${l.status === "running" ? "mercan" : "altin"}">${ikon(BECERI[l.skill]?.ik ?? "presentation")}</span>
          <div><span class="tur">${esc(l.status === "running" ? ç("Şimdi · bitiş {saat}", { saat: saatKisa(l.ends_at) }) : saatYaz(l.starts_at))}${l.region_id !== v.region_id ? " · " + esc(bolgeAdi(l.region_id)) : ""}</span>
            <b>${esc(ç("{beceri} dersin", { beceri: beceriAdi(l.skill) }))}</b>
            <div class="alt">${esc([ç("{n} / {m} öğrenci", { n: sayi(l.enrolled ?? 0), m: sayi(l.capacity ?? 0) }), ç("{kr} kredi", { kr: kr(l.fee_cr ?? 0) }), ç("ders hakkı {n} dk", { n: sayi(l.credit_minutes ?? 0) })].join(" · "))}</div>
            ${ogr.length ? `<div class="alt">${ogr.map((s) => `<button class="baglanti" type="button" data-profil="${esc(s.character_id)}">${esc(s.name ?? "")}</button>`).join(", ")}</div>` : ""}</div>
          <div class="mekan-satir-dugmeler"><button class="dugme sade kucuk-d" data-ders-goster="${esc(l.lesson_id)}">${ikon("presentation")}${ç("Sınıf")}</button>
            ${l.status === "scheduled" ? `<button class="dugme ikincil kucuk-d" data-ders-iptal="${esc(l.lesson_id)}">${ikon("x")}${ç("İptal et")}</button>` : ""}</div></div>`;
      }).join("");
      const gecmis = (v.taught ?? []).map((l) => `<div class="liste-satir"><span class="liste-ikon">${ikon(BECERI[l.skill]?.ik ?? "presentation")}</span>
          <div><span class="tur">${esc(zamanOnce(l.ends_at))} · ${esc(bolgeAdi(l.region_id))}</span><b>${esc(ç("{beceri} dersin", { beceri: beceriAdi(l.skill) }))}</b>
            <div class="alt">${esc(l.status === "completed" ? ç("{n} öğrenci katıldı · {kr} kredi kazandın", { n: sayi(l.attended ?? 0), kr: kr(l.earned_cr ?? 0) }) : ç("düştü: {neden}", { neden: DERS_IPTAL[l.cancel_reason] ?? "" }))}</div></div><span></span></div>`).join("");
      return `<section class="kart" id="dersler-ogretmen"><div class="kart-bas"><div><p class="ust-yazi">${ç("Öğretmenlik")}</p>
          <h2 class="b2">${ç("Ders ver")}</h2></div><span class="ik-kutu">${ikon("presentation")}</span></div>
        ${ogretim ? `<div class="liste" style="margin-bottom:12px">${ogretim}</div>` : ""}
        ${engel || `<form class="form" id="dersler-ac-form" novalidate>
          <label class="alan"><span>${ç("Beceri")}</span><select name="beceri">${uygun.map((b) => `<option value="${esc(b)}">${esc(ç("{beceri} (seviyen {n}; ders hakkı {m} dk)", { beceri: beceriAdi(b), n: sayi(v.skills?.[b] ?? 0),
            m: sayi(Math.min(Number(kur.creditMax ?? 90), Number(kur.creditBase ?? 30) + Number(v.skills?.[b] ?? 0))) }))}</option>`).join("")}</select></label>
          <label class="alan"><span>${ç("Başlangıç")}</span><input name="zaman" type="datetime-local" required min="${yerel(enErken)}" max="${yerel(enGec)}" value="${yerel(oneri)}"></label>
          <div class="satir" style="gap:10px;flex-wrap:wrap">
            <label class="alan" style="flex:1;min-width:140px"><span>${ç("Öğrenci başına ücret (kredi, en çok {kr})", { kr: kr(kur.feeMaxCr ?? 300) })}</span><input name="ucret" inputmode="decimal" required value="${esc(krediGirdi(kur.feeDefaultCr ?? 100))}"></label>
            <label class="alan" style="flex:1;min-width:120px"><span>${ç("Kontenjan")}</span><select name="kontenjan">${Array.from({ length: Number(kur.maxStudents ?? 8) }, (_, i) => i + 1).map((n) => `<option value="${n}" ${n === Math.min(4, Number(kur.maxStudents ?? 8)) ? "selected" : ""}>${esc(ç("{n} öğrenci", { n }))}</option>`).join("")}</select></label></div>
          <p class="kucuk">${ç("Ders {dk} dakika, bir çalışma birimi; en erken {e} dakika, en geç {s} saat sonra. Ders saatinde bu şehirde olmalısın; kimse yazılmazsa ders düşer. Ücret ders bitince maaş vergisiyle sana geçer.",
            { dk: sayi(kur.unitMinutes ?? 30), e: sayi(kur.leadMinutes ?? 10), s: sayi(kur.horizonHours ?? 72) })}</p>
          <div class="form-mesaj" id="dersler-ac-mesaj"></div>
          <div class="oneri-dugmeler"><button class="dugme altin" type="submit">${ikon("presentation")}${ç("Ders aç")}</button></div></form>`}
        ${gecmis ? `<p class="ust-yazi" style="margin-top:12px">${ç("Son verdiğin dersler")}</p><div class="liste">${gecmis}</div>` : ""}</section>`;
    }

    function ciz() {
      durdur();
      kirli = false;
      if (ertelendi) { ertelendi = false; setTimeout(() => tazele()); }
      kap.innerHTML = `<div class="sayfa">
        <div class="sayfa-bas"><div><p class="ust-yazi">${ç("Hayatım · Dersler")}</p><h1 class="b1">${ç("Dersler")}</h1>
          <p class="aciklama">${ç("Becerisi yüksek oyuncular bulundukları şehirde ders verir. Derse giren ders hakkı kazanır; o becerideki eğitimi kısalır.")}</p></div>
          <div class="oneri-dugmeler">${meydanaDonDugme("egitim")}<button class="dugme ikincil kucuk-d" data-git="hayat/egitim">${ikon("graduation-cap")}${ç("Eğitim")}</button></div></div>
        ${v.on_road ? `<div class="bilgi-kutusu" style="margin-bottom:14px">${ikon("route")}<span>${ç("Yoldasın; vardığın şehrin dersleri burada görünür.")}</span></div>` : ""}
        <div id="dersler-sahne-yer"></div>
        <div class="izgara iki">
          <div class="yigin">${sehirHtml()}${ogrenciHtml()}</div>
          <div class="yigin">${ogretmenHtml()}</div>
        </div></div>`;
      const yer = $("#dersler-sahne-yer", kap);
      const b = ben();
      if (yer) { yer.replaceWith(sahne.el); sahne.yaz({ l: sahneDersi(), ben: { id: b.id, ad: b.name, gorunus, ulke: b.citizenship ?? null }, bolge: v.region_id }); }
      bagla();
      durdur = geriSay(kap, () => setTimeout(() => { if (!kapandi) tazele(); }, 1500));
    }

    async function isle(dugme, is) {
      if (dugme?.disabled) return;
      if (dugme) dugme.disabled = true;
      try { await is(); } catch (e) { tost(hataMetni(e), "circle-alert"); } finally { if (dugme?.isConnected) dugme.disabled = false; }
    }
    const bul = (id) => [...(v.city ?? []), ...(v.learning ?? []), ...(v.teaching ?? [])].find((l) => l.lesson_id === id);
    function yazilPenceresi(l) {
      const sev = Number(v.skills?.[l.skill] ?? 0);
      pencere({ ust: ç("Ders · {sehir}", { sehir: bolgeAdi(l.region_id) }), baslik: ç("{beceri} dersi: {ad}", { beceri: beceriAdi(l.skill), ad: l.teacher ?? "" }),
        govde: `<div class="liste"><div class="liste-satir"><span class="liste-ikon yesil">${ikon("clock-3")}</span><div><span class="tur">${ç("Başlangıç")}</span><b>${esc(saatYaz(l.starts_at))}</b></div><span></span></div>
            <div class="liste-satir"><span class="liste-ikon">${ikon("graduation-cap")}</span><div><span class="tur">${ç("Ders hakkı")}</span><b>${esc(ç("{n} dakika ({beceri} {s} → öğretmen {t})", { n: sayi(l.credit_minutes ?? 0), beceri: beceriAdi(l.skill), s: sayi(sev), t: sayi(l.teacher_level ?? 0) }))}</b></div><span></span></div>
            <div class="liste-satir"><span class="liste-ikon altin">${ikon("coins")}</span><div><span class="tur">${ç("Ücret")}</span><b>${esc(ç("{kr} kredi", { kr: kr(l.fee_cr ?? 0) }))}</b></div><span></span></div></div>
          <p class="kucuk" style="margin-top:10px">${ç("Ücret şimdi ayrılır; ders saatinde bu şehirde değilsen ya da ders düşerse sana döner. Ders başlayana dek kaydı bırakabilirsin. Dersin yarım saati çizelgende yer tutar.")}</p>`,
        dugmeler: [{ ad: ç("Vazgeç") }, { ad: ç("Yazıl"), sinif: "altin", ikon: "user-round-plus", is: () => isle(null, async () => {
          await Sunucu.yap("lesson_enroll", { p_lesson: l.lesson_id, p_expected_fee: Number(l.fee_cr ?? 0) });
          tost(ç("{beceri} dersine yazıldın: {saat}.", { beceri: beceriAdi(l.skill), saat: saatYaz(l.starts_at) }), "presentation");
          odak = l.lesson_id;
          Durum.ozet().catch(() => {});
          await tazele();
        }) }] });
    }
    function bagla() {
      meydanaDonBagla(kap);
      for (const b of $$("[data-profil]", kap)) b.onclick = () => profilAc(b.dataset.profil, () => tazele());
      for (const b of $$("[data-git]", kap)) b.onclick = () => Kabuk.git(b.dataset.git);
      for (const b of $$("[data-ders-goster]", kap)) b.onclick = () => {
        odak = b.dataset.dersGoster;
        const l = bul(odak);
        const k = ben();
        sahne.yaz({ l, ben: { id: k.id, ad: k.name, gorunus, ulke: k.citizenship ?? null }, bolge: v.region_id });
        sahne.el.scrollIntoView({ behavior: hareketAzalt ? "auto" : "smooth", block: "start" });
      };
      for (const b of $$("[data-ders-yazil]", kap)) b.onclick = () => { const l = bul(b.dataset.dersYazil); if (l) yazilPenceresi(l); };
      for (const b of $$("[data-ders-birak]", kap)) b.onclick = () => isle(b, async () => {
        await Sunucu.yap("lesson_withdraw", { p_lesson: b.dataset.dersBirak });
        tost(ç("Kaydı bıraktın; ücretin sana döndü."), "undo-2");
        Durum.ozet().catch(() => {});
        await tazele();
      });
      for (const b of $$("[data-ders-iptal]", kap)) b.onclick = () => {
        const l = bul(b.dataset.dersIptal);
        pencere({ ust: ç("Öğretmenlik"), baslik: ç("{beceri} dersin iptal edilsin mi?", { beceri: beceriAdi(l?.skill) }),
          govde: `<p class="aciklama">${ç("Yazılan öğrencilerin ücreti döner ve onlara haber gider.")}</p>`,
          dugmeler: [{ ad: ç("Vazgeç") }, { ad: ç("İptal et"), sinif: "mercan", ikon: "x", is: () => isle(null, async () => {
            await Sunucu.yap("lesson_cancel", { p_lesson: b.dataset.dersIptal });
            tost(ç("Dersi iptal ettin; öğrencilerin ücreti döndü."), "undo-2");
            await tazele();
          }) }] });
      };
      const f = $("#dersler-ac-form", kap);
      f?.addEventListener("submit", (e) => {
        e.preventDefault();
        const d = $("button[type=submit]", f);
        const mesaj = $("#dersler-ac-mesaj", f);
        const hata = (m) => { mesaj.innerHTML = `<div class="hata-kutusu" style="margin-top:8px">${ikon("circle-alert")}<span>${esc(m)}</span></div>`; };
        mesaj.innerHTML = "";
        const fd = new FormData(f);
        const kur = R();
        const zaman = new Date(String(fd.get("zaman") ?? ""));
        const ucret = krediAlt(fd.get("ucret"));
        const dk = (zaman.getTime() - Date.now()) / 60000;
        if (!Number.isFinite(zaman.getTime()) || dk < Number(kur.leadMinutes ?? 10) || dk > Number(kur.horizonHours ?? 72) * 60) {
          hata(ç("Başlangıç en erken {e} dakika, en geç {s} saat sonra olmalı.", { e: sayi(kur.leadMinutes ?? 10), s: sayi(kur.horizonHours ?? 72) })); return;
        }
        if (!Number.isFinite(ucret) || ucret < 0 || ucret > Number(kur.feeMaxCr ?? 300)) { hata(ç("Ücret 0 ile {kr} kredi arasında olmalı.", { kr: kr(kur.feeMaxCr ?? 300) })); return; }
        isle(d, async () => {
          let l;
          try {
            l = await Sunucu.yap("lesson_open", { p_skill: String(fd.get("beceri")), p_starts_at: zaman.toISOString(), p_fee: ucret, p_capacity: Number(fd.get("kontenjan")) });
          } catch (err) { hata(hataMetni(err)); return; }
          kirli = false;
          odak = l?.lesson_id ?? null;
          tost(ç("Ders açtın: {beceri}, {saat}.", { beceri: beceriAdi(l?.skill ?? fd.get("beceri")), saat: saatYaz(l?.starts_at ?? zaman.toISOString()) }), "presentation");
          await tazele();
        });
      });
    }

    const tazele = tazeleyici(async () => { await yukle(); if (!kapandi) ciz(); });
    await Promise.all([Durum.kurallar().catch(() => null), Durum.ozet().catch(() => null)]);
    await yukle();
    ciz();
    const b1 = Durum.dinle("olay", ({ olay }) => { if (/^(lesson\.|travel\.arrived|training\.)/.test(olay)) yakinda(); });
    const saat = setInterval(() => { if (!document.hidden && !document.querySelector(".perde")) tazeleIste(); }, 30000);
    return () => {
      kapandi = true;
      durdur(); b1(); clearInterval(saat); clearTimeout(bekleyen);
      sahne.kapat();
    };
  },
});

// ===== 98zn_keyif.js =====
// ---------- Keyif (D-144): kişinin keyfi (yalnız kendisine görünür) ----------
// Keyif 0–100: kendiliğinden evinin "dinlenme seviyesine" yaklaşır (evin konforu: eşya türlerinin konfor puanları; her tür bir
// kez). Arkadaşlarla geçen an (yakınlık), yeme-içme (mekânda, ev partisinde), kültür (konser, festival) ve ev partisi artırır;
// her kaynağın günlük tavanı var. Keyfin yerindeyken (70 ve üstü) yeni başlayan eğitimin kısa sürer; askerlik hariç (keyif
// savaş gücüne dönüşmez). Düşük keyfin cezası yok. Kazançlar sunucuda dakikalık işle işlenir; ekran işlenmemişleri de sayar.
// Burada: kuralın yardımcıları, keyif kartı (Hayatım → Profil), üst banttaki çip, eğitimin keyif bandı, sipariş ve ikram
// tostunun notu, evin konforu (Evim) ve eşya penceresindeki konfor notu, Hayatım sahnesinin rozeti (2B).

const keyifKurali = () => Durum.v.kurallar?.data?.mood ?? {};
const KEYIF_AD = { happy: ç("Keyfin yerinde"), good: ç("İyi"), calm: ç("Sakin") };
const KEYIF_IKON = { happy: "face-grinning", good: "face-slightly-smiling", calm: "face-neutral" };
const KEYIF_KOVA = {
  friends: { ad: ç("Arkadaşlar"), ik: "heart-handshake", ipucu: ç("Selamlaşmak, ısmarlamak, hediye, aynı masada ya da evde vakit") },
  food: { ad: ç("Yeme-içme"), ik: "coffee", ipucu: ç("Mekânda içmek ve yemek, ev partisinde ikram") },
  culture: { ad: ç("Kültür"), ik: "ticket", ipucu: ç("Konserde seyirci ya da sahnede olmak, festivalde oy") },
  party: { ad: ç("Ev partisi"), ik: "party-popper", ipucu: ç("Parti vermek ya da bir partide en az 15 dakika kalmak") },
};

// Kovanın adı cümle içinde (küçük harfle)
const keyifKovaAdi = (k) => (KEYIF_KOVA[k]?.ad ?? "").toLocaleLowerCase(DIL.yerel);

// Evin konforu (kural motoruyla aynı: eşya türlerinin konfor puanları, her tür bir kez) ve dinlenme seviyesi
function evKonforu(items, kural = keyifKurali()) {
  const t = kural.comfort ?? {};
  return [...new Set((items ?? []).map((x) => x.i))].reduce((s, i) => s + Number(t[i] ?? 0), 0);
}
function keyifDinlenme(konfor, kural = keyifKurali()) {
  const r = kural.rest ?? { base: 20, comfortPpm: 500000, max: 60 };
  return Math.min(Number(r.max), Number(r.base) + Math.floor((Number(konfor) * Number(r.comfortPpm)) / 1000000));
}
// Keyfin yerindeyken eğitimin kısalması (askerlik hariç): dakika × (1 − oran), yukarı yuvarlanır, en az 1 (sunucuyla aynı)
function keyifKisalt(dk, beceri, m = Durum.v.askerlik?.mood) {
  const t = m?.training ?? keyifKurali().training ?? {};
  if (!m?.happy || !(Number(t.ppm) > 0) || (t.exclude ?? []).includes(beceri)) return dk;
  return Math.max(1, Math.ceil((dk * (1000000 - Number(t.ppm))) / 1000000));
}

// Çubuk: puan / tavan, "yerinde" eşiği, dinlenme seviyesi işareti
function keyifCubugu(m) {
  const p = Number(m?.points ?? 0), en = Math.max(1, Number(m?.max ?? 100)), e = Number(m?.happy_at ?? 70), d = Number(m?.rest ?? 0);
  return `<div class="keyif-cubuk ${esc(m?.level ?? "calm")}" role="img" aria-label="${esc(ç("Keyif {n} / {m}", { n: p, m: en }))}">
    <i style="width:${Math.round((Math.min(p, en) / en) * 100)}%"></i><b style="left:${Math.round((e / en) * 100)}%"></b>
    <s style="left:${Math.round((Math.min(d, en) / en) * 100)}%" title="${esc(ç("Dinlenme seviyesi {n}", { n: d }))}"></s></div>`;
}
function keyifDurumu(m) {
  if (!m) return "";
  const t = m.training ?? keyifKurali().training ?? {};
  if (m.happy) {
    const son = m.happy_until ? " " + ç("{zaman} kadar sürer; yeni kazançlar uzatır.", { zaman: saatYaz(m.happy_until) }) : "";
    return ç("Keyfin yerinde: yeni başlayan eğitimlerin {oran} kısa sürer (askerlik hariç).", { oran: ppmYuzde(t.ppm ?? 0) }) + son;
  }
  const kalan = Math.max(0, Number(m.happy_at ?? 70) - Number(m.points ?? 0));
  return ç("{n} puan daha toplarsan keyfin yerinde olur: yeni eğitimlerin {oran} kısa sürer (askerlik hariç). Düşük keyfin hiçbir cezası yok.",
    { n: kalan, oran: ppmYuzde(t.ppm ?? 0) });
}

// Sipariş ve ikram yanıtındaki keyif (kendi kazancın; sunucunun önizlemesi): askerlik özetindeki keyif tazelenir; tosta eklenecek
// kısa not döner (kazanç, ya da o kaynağın bugünkü tavanı dolduysa).
function keyifEki(r, kaynak = r?.mood_source) {
  const m = r?.mood;
  if (!m || typeof m !== "object") return "";
  const a = Durum.v.askerlik;
  if (a) { a.mood = m; Durum.yay("askerlik", a); }
  const n = Number(r.mood_gain ?? 0), kova = m.sources?.[kaynak];
  if (n > 0) return " " + ç("Keyfin +{n}: {p} / {m}.", { n, p: Number(m.points ?? 0), m: Number(m.max ?? 100) });
  if (kova && Number(m.today?.[kova] ?? 0) >= Number(m.caps?.[kova] ?? 0)) return " " + ç("Bugünkü {kova} keyfi doldu.", { kova: keyifKovaAdi(kova) });
  return "";
}
// Sipariş penceresinin notu: kendine içecek ya da yiyecek keyfini artırır (günlük tavanla); ısmarlama ve hediye alanınkini
function keyifSiparisNotu(cat) {
  const r = keyifKurali(), m = Durum.v.askerlik?.mood;
  const kaynak = { drink: "drink", food: "food", gift: "gift" }[cat];
  if (!kaynak || !r.gains?.[kaynak]) return "";
  const kova = r.sources?.[kaynak], g = Number(r.gains[kaynak]);
  if (kaynak === "gift") return ç("Hediye alanın keyfini {n} artırır.", { n: g });
  return ç("Kendine alırsan keyfin {n} artar (bugün {kova}: {a} / {b}); ısmarlarsan alanınki.",
    { n: g, kova: keyifKovaAdi(kova), a: Number(m?.today?.[kova] ?? 0), b: Number(r.caps?.[kova] ?? 0) });
}

// Hayatım → Profil'deki keyif kartı: yüz ve çubuk, durum, evin konforu ve dinlenme seviyesi, bugünkü kovalar (tavanlarıyla),
// nereden kazanılır (bağlantılar)
function keyifKarti(m) {
  if (!m) return "";
  const kovalar = Object.entries(KEYIF_KOVA).map(([k, x]) => {
    const n = Number(m.today?.[k] ?? 0), t = Number(m.caps?.[k] ?? 0);
    return `<div class="keyif-kova${n >= t && t > 0 ? " dolu" : ""}" data-keyif-kova="${k}" data-n="${n}">${ikon(x.ik)}<span><b>${esc(x.ad)}</b>
      <span class="kucuk">${esc(x.ipucu)}</span></span><span class="keyif-kova-sayi">${ç("{n} / {m}", { n, m: t })}</span></div>`;
  }).join("");
  return `<section class="kart keyif-kart" id="keyif-kart" data-keyif="${esc(m.level ?? "calm")}" data-puan="${Number(m.points ?? 0)}" data-dinlenme="${Number(m.rest ?? 0)}">
    <div class="kart-bas"><div><p class="ust-yazi">${ç("Keyif")}</p><h2 class="b2">${esc(KEYIF_AD[m.level] ?? "")} · ${ç("{n} / {m}", { n: Number(m.points ?? 0), m: Number(m.max ?? 100) })}</h2></div>
      <span class="ik-kutu keyif-yuz ${esc(m.level ?? "calm")}">${ikon(KEYIF_IKON[m.level] ?? "face-neutral")}</span></div>
    ${keyifCubugu(m)}
    <p class="aciklama" id="keyif-durum" style="margin-top:8px">${esc(keyifDurumu(m))}</p>
    <div class="bilgi-kutusu" id="keyif-ev">${ikon("sofa")}<span>${esc(ç("Evinin konforu {k}: keyfin kendiliğinden {d} seviyesine yaklaşır (yarım saatte bir puan). Evine farklı eşya ekledikçe artar.",
      { k: Number(m.comfort ?? 0), d: Number(m.home_rest ?? m.rest ?? 0) }))}</span>
      <button class="dugme sade kucuk-d" data-git="sehir/ev">${ikon("house")}${ç("Evim")}</button></div>
    <p class="ust-yazi" style="margin-top:12px">${ç("Bugün kazandıkların")}</p>
    <div class="keyif-kovalar">${kovalar}</div>
    <div class="oneri-dugmeler" style="margin-top:10px">
      <button class="dugme ikincil kucuk-d" data-git="sehir/mekanlar">${ikon("coffee")}${ç("Mekânlar")}</button>
      <button class="dugme ikincil kucuk-d" data-git="sehir/sahne">${ikon("ticket")}${ç("Sahne")}</button>
      <button class="dugme ikincil kucuk-d" data-git="meydan/arkadas">${ikon("heart-handshake")}${ç("Arkadaşlar")}</button>
    </div>
    <p class="kucuk" style="margin-top:8px">${ç("Keyfini yalnız sen görürsün. Savaş gücüne, oylara ya da gelire etkisi yok.")}</p>
  </section>`;
}

// Üst banttaki çip (geniş ekranda; dokununca Profil)
function keyifCipi(m) {
  if (!m) return "";
  return `<span class="deger-ayrac d-keyif-ayrac"></span><a class="deger d-keyif ${esc(m.level ?? "calm")}" href="#hayat/profil" data-keyif="${esc(m.level ?? "calm")}"
    title="${esc(ç("Keyif: {ad}", { ad: KEYIF_AD[m.level] ?? "" }))}">${ikon(KEYIF_IKON[m.level] ?? "face-neutral")}<span><span class="deger-sayi">${sayi(Number(m.points ?? 0))}</span></span></a>`;
}

// Eğitim ekranının keyif satırı: keyfin yerindeyken altın bant (kısalma oranı ve ne kadar süreceği), değilse kısa ipucu
function keyifEgitimBandi(m) {
  if (!m) return "";
  const t = m.training ?? keyifKurali().training ?? {};
  if (!(Number(t.ppm) > 0)) return "";
  if (m.happy) {
    return `<div class="yasa-bant altin" id="egitim-keyif" data-keyif="happy">${ikon("face-grinning")}<span>${esc(ç("Keyfin yerinde ({n}): yeni başlayan eğitimler {oran} kısa sürer (askerlik hariç).", { n: Number(m.points ?? 0), oran: ppmYuzde(t.ppm) })
      + (m.happy_until ? " " + ç("{zaman} kadar sürer; yeni kazançlar uzatır.", { zaman: saatYaz(m.happy_until) }) : ""))}</span>
      <button class="dugme ikincil kucuk-d" data-git="hayat/profil">${ikon("face-grinning")}${ç("Keyif")}</button></div>`;
  }
  return `<p class="kucuk egitim-keyif-ipucu" id="egitim-keyif" data-keyif="${esc(m.level ?? "calm")}">${ikon(KEYIF_IKON[m.level] ?? "face-neutral")}
    <span>${esc(ç("Keyfin {n}: {e} ve üstündeyken yeni eğitimler {oran} kısa sürer (askerlik hariç).", { n: Number(m.points ?? 0), e: Number(m.happy_at ?? 70), oran: ppmYuzde(t.ppm) }))}</span></p>`;
}

// Evim'deki konfor kartı: evin (ya da pansiyon odasının) konforu ve dinlenme seviyesi; bu evde kullanılabilen eşya türleri:
// var olanlar puanıyla, eksikler "+puan" olarak (eklenince konfor artar)
function evKonforKarti(oda, m) {
  const kural = keyifKurali();
  if (!oda || !kural.comfort) return "";
  const k = evKonforu(oda.items, kural), d = keyifDinlenme(k, kural);
  const var_ = new Set((oda.items ?? []).map((x) => x.i));
  const esya = (oda.catalog ?? []).filter((c) => Number(kural.comfort[c.id] ?? 0) > 0)
    .sort((a, b) => Number(kural.comfort[b.id]) - Number(kural.comfort[a.id]))
    .map((c) => `<span class="cip${var_.has(c.id) ? " yesil" : " yok"}" data-konfor-esya="${esc(c.id)}" data-var="${var_.has(c.id) ? 1 : 0}">${esc(çv(c.name))} ${var_.has(c.id) ? sayi(Number(kural.comfort[c.id])) : "+" + sayi(Number(kural.comfort[c.id]))}</span>`).join("");
  return `<section class="kart" id="evim-konfor" data-konfor="${k}" data-dinlenme="${d}">
    <div class="kart-bas"><div><p class="ust-yazi">${ç("Konfor ve keyif")}</p><h2 class="b2">${ç("Evinin konforu {k}", { k })}</h2></div><span class="ik-kutu">${ikon("sofa")}</span></div>
    <p class="aciklama">${esc(ç("Keyfin kendiliğinden {d} seviyesine yaklaşır (yarım saatte bir puan; en çok {en}). Her eşya türü bir kez sayılır: farklı eşya ekledikçe konfor artar.",
      { d, en: Number(kural.rest?.max ?? 60) }) + (m ? " " + ç("Şu an keyfin {n}.", { n: Number(m.points ?? 0) }) : ""))}</p>
    <div class="evim-konfor-esya">${esya}</div>
    <p class="kucuk" style="margin-top:8px">${ç("Eşyaları odanın düzeninde ekleyip kaydedince sayılır. Konfor güç vermez; yalnız keyfini etkiler.")}</p>
  </section>`;
}
// Eşya penceresindeki not: bu türün konfor puanı (evde yoksa "+n konfor")
function keyifEsyaNotu(id, items) {
  const k = Number(keyifKurali().comfort?.[id] ?? 0);
  if (!(k > 0)) return "";
  return (items ?? []).some((p) => p.i === id) ? ç("konfor {n} (sayıldı)", { n: k }) : ç("+{n} konfor", { n: k });
}

// Hayatım sahnesinin keyif rozeti (2B): figürün solunda yüz; dokununca keyif kartına gider
function keyifRozet2b(cx, cy, seviye) {
  if (!seviye) return "";
  const r = { happy: ["#E2B54A", "#8A6A10", "#4A3608"], good: ["#E1EBE5", "#174A40", "#174A40"], calm: ["#ECE9DE", "#87938C", "#56645E"] }[seviye]
    ?? ["#ECE9DE", "#87938C", "#56645E"];
  const agiz = seviye === "happy" ? `<path d="M${cx - 6} ${cy + 2} Q${cx} ${cy + 10} ${cx + 6} ${cy + 2} Z" fill="${r[2]}"/>`
    : seviye === "good" ? `<path d="M${cx - 5} ${cy + 3} Q${cx} ${cy + 7} ${cx + 5} ${cy + 3}" fill="none" stroke="${r[2]}" stroke-width="1.8" stroke-linecap="round"/>`
    : `<path d="M${cx - 5} ${cy + 4} H${cx + 5}" stroke="${r[2]}" stroke-width="1.8" stroke-linecap="round"/>`;
  return `<g data-hayat-git="keyif" class="hayat2b-tik" data-keyif-rozet="${seviye}"><circle cx="${cx}" cy="${cy}" r="12" fill="${r[0]}" stroke="${r[1]}" stroke-width="2"/>
    <circle cx="${cx - 4}" cy="${cy - 3}" r="1.7" fill="${r[2]}"/><circle cx="${cx + 4}" cy="${cy - 3}" r="1.7" fill="${r[2]}"/>${agiz}</g>`;
}
// Sahnedeki rozete dokununca: keyif kartı görünür (aynı ekranda; yoksa Profil)
function keyifKartinaGit() {
  const k = $("#keyif-kart");
  if (k) k.scrollIntoView({ behavior: "smooth", block: "center" });
  else Kabuk.git("hayat/profil");
}

// ===== 99_baslat.js =====
// ---------- Açılış: ayar, e-posta bağlantısından dönüş, oturum, karakter, kabuk ----------

const Uygulama = (() => {
  function acilisHatasi(metin) {
    // Satır içi olay özniteliği (onclick=…) içerik güvenlik politikasında çalışmaz (D-098); dinleyici kodla eklenir.
    $("#uygulama").innerHTML = `<div class="baslangic"><img src="img/amblem.png" alt="" width="72" height="72">
      <p>${esc(metin)}</p><button class="dugme ikincil" type="button" id="acilis-yenile">${ç("Yeniden dene")}</button></div>`;
    $("#acilis-yenile").addEventListener("click", () => location.reload());
  }

  async function basla() {
    try {
      await Sunucu.yukle();
    } catch (e) {
      return acilisHatasi(hataMetni(e));
    }
    const donus = Sunucu.Giris.adresiIsle();
    if (donus?.hata) return GirisEkrani.giris({ hata: donus.hata.message });
    // Parola sıfırlama adımı sekmede hatırlanır: dil değiştirince ya da sayfa yenilenince form kaybolmaz (22 Ekim 2026
    // incelemesi, AUTH-03); parola değişince ya da oturum kapanınca silinir
    let kurtarma = donus?.tur === "recovery";
    try { if (kurtarma) sessionStorage.setItem("civora.kurtarma", "1"); else kurtarma = sessionStorage.getItem("civora.kurtarma") === "1"; } catch { /* yok */ }
    if (kurtarma && Sunucu.Giris.oturum) return GirisEkrani.yeniParola();
    try { sessionStorage.removeItem("civora.kurtarma"); } catch { /* yok */ }
    if (!Sunucu.Giris.oturum) return GirisEkrani.giris();
    if (donus?.tur === "signup") tost(ç("E-posta adresin doğrulandı. Hoş geldin!"), "badge-check");
    if (donus?.tur === "email_change") tost(ç("E-posta adresin doğrulandı; hesabın artık kalıcı. Bundan sonra bu e-posta ve parolayla her cihazdan girebilirsin."), "badge-check");   // misafir kalıcı oldu (D-133)
    return oturumAcildi();
  }

  async function oturumAcildi() {
    let devletler = null;
    try {
      await Sunucu.Giris.gecerliJeton();
      if (!Sunucu.Giris.kullanici?.email) await Sunucu.Giris.kullaniciGetir().catch(() => {});
      devletler = Devletler.yukle();               // yeni devletler ülke ve bölge bilgisine eklenir (D-113; hata vermez)
      await Durum.ozet();
    } catch (e) {
      if (e.kod === "NO_CHARACTER") { await devletler; return KarakterEkrani.ac(); }
      if (e.kod === "ACCOUNT_SUSPENDED") return AskiEkrani.ac();   // hesap askıda (D-139)
      if (!Sunucu.Giris.oturum || e.kod === "NOT_AUTHENTICATED" || String(e.kod).startsWith("refresh_token")) {
        await Sunucu.Giris.cikis();
        return GirisEkrani.giris({ hata: ç("Oturumun sona erdi; yeniden giriş yap.") });
      }
      return acilisHatasi(hataMetni(e));
    }
    Sunucu.cagir("ping").catch(() => {});          // açılış ölçümü (D-068)
    // Kurallar arkada gelir; gelince resimlerdeki mağaza ürünleri çizilir (D-134; ekranlar kuralı zaten bekler)
    Durum.kurallar().then(() => { Kabuk.ustGuncelle(); Gorunus.yenile(); }).catch(() => {});
    await Durum.askerlik().catch(() => {});
    await devletler;
    Durum.canliBaslat();
    Kabuk.sifirla();
    await Kabuk.git(location.hash.slice(1) || Kabuk.VARSAYILAN, { gecmis: false });
    Konusma.baslat().catch((e) => console.warn("Konuşma düğmesi açılamadı:", e));   // her ekranda sohbet (D-116)
    // D-139: kaldırılan adın yerine yeni ad; topluluk kurallarının yeni sürümü
    adYenileIste();
    toplulukSurumDenetle();
  }

  // Oyun sürerken hesap askıya alınırsa (bir istek ACCOUNT_SUSPENDED dedi) kabuk kapanır, askı ekranı açılır
  function aski() {
    if (AskiEkrani.acik || !Sunucu.Giris.oturum) return;
    Konusma.bitir();
    Durum.canliBitir();
    Kabuk.sifirla();
    AskiEkrani.ac();
  }
  addEventListener("civora:aski", aski);

  async function cikis() {
    Konusma.bitir();
    Durum.temizle();
    Gorunus.temizle();
    await Sunucu.Giris.cikis();
    Kabuk.sifirla();
    history.replaceState(null, "", location.pathname);
    GirisEkrani.giris({ mesaj: ç("Çıkış yaptın.") });
  }

  // Başka sekmede çıkış ya da giriş (22 Ekim 2026 incelemesi, TECH-04): depodaki oturum değişince bu sekme de uyar. Çıkışta
  // giriş ekranına döner; başka hesapla girişte sayfa yeniden yüklenir (eski hesabın verisi ekranda kalmasın).
  addEventListener("storage", (e) => {
    if (e.key !== "civora.oturum") return;
    const eski = Sunucu.Giris.oturum, yeni = e.newValue ? JSON.parse(e.newValue) : null;
    if (!yeni && eski) {
      Konusma.bitir(); Durum.temizle(); Gorunus.temizle();
      Sunucu.Giris.yereldenCik();
      Kabuk.sifirla();
      history.replaceState(null, "", location.pathname);
      GirisEkrani.giris({ mesaj: ç("Başka bir sekmede çıkış yapıldı.") });
    } else if (yeni && !eski) {
      location.reload();
    } else if (yeni && eski && yeni.user?.id && eski.user?.id && yeni.user.id !== eski.user.id) {
      location.reload();   // başka hesap
    } else if (yeni && eski) {
      Sunucu.Giris.yereldenAl(yeni);   // aynı hesap, yenilenmiş jeton
    }
  });

  // Uygulama öne gelince açılış ölçümü ve veri tazeleme (enerji, yorgunluk ve keyif zamanla değişir: askerlik özeti de).
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible" && Sunucu.Giris.oturum && Durum.v.ozet) {
      Sunucu.cagir("ping").catch(() => {});
      Durum.ozet().catch(() => {});
      if (Durum.v.askerlik) Durum.askerlik().catch(() => {});
    }
  });
  // Açık ve önde dururken on dakikada bir yoklama: şehrin nabzındaki "bulunan" sayısı (son 30 dakikada açanlar; D-110)
  // uygulamayı uzun süre açık tutanı da sayar. Yoklama oturum saymaz (oturum arası kuralın boşluğundan kısa). Üst banttaki
  // enerji ve keyif (D-144; başkalarının ısmarlaması, yakınlık, konser dakikalık işle işlenir) için askerlik özeti de tazelenir.
  setInterval(() => {
    if (document.visibilityState === "visible" && Sunucu.Giris.oturum && Durum.v.ozet) {
      Sunucu.cagir("ping").catch(() => {});
      if (Durum.v.askerlik) Durum.askerlik().catch(() => {});
    }
  }, 10 * 60 * 1000);

  return { basla, oturumAcildi, cikis, aski };
})();

Uygulama.basla();
